-- Portico pre-release schema. Edit this baseline directly; reset development state after changes.
CREATE TABLE catalog_kinds(
 id INTEGER PRIMARY KEY CHECK(id BETWEEN 1 AND 99),
 name TEXT NOT NULL UNIQUE,
 playable INTEGER NOT NULL CHECK(playable IN(0,1)),
 container INTEGER NOT NULL CHECK(container IN(0,1)),
 searchable INTEGER NOT NULL CHECK(searchable IN(0,1)),
 browsable INTEGER NOT NULL CHECK(browsable IN(0,1)),
 listening INTEGER NOT NULL CHECK(listening IN(0,1))) STRICT;
INSERT INTO catalog_kinds VALUES
 (1,'movie',1,0,1,1,0),(2,'show',0,1,1,1,0),(3,'season',0,1,0,1,0),(4,'episode',1,0,1,1,0),
 (5,'artist',0,1,1,1,1),(6,'album',0,1,1,1,1),(7,'song',1,0,1,1,1),(8,'book',0,1,1,1,1),
 (9,'audiobook_file',1,0,0,1,1),(10,'collection',0,1,1,1,0),(11,'extra',1,0,0,1,0),
 (12,'disc',0,1,0,0,1),(13,'author',0,1,1,1,1),
 (20,'ebook',0,0,1,1,0),(21,'comic',0,0,1,1,0);
CREATE TABLE catalog_libraries(
 id INTEGER PRIMARY KEY AUTOINCREMENT,
 library_id TEXT NOT NULL UNIQUE REFERENCES libraries(id) ON DELETE CASCADE,
 root TEXT NOT NULL,
 name TEXT NOT NULL,
 kind INTEGER NOT NULL CHECK(kind BETWEEN 1 AND 99),
 retired INTEGER NOT NULL DEFAULT 0 CHECK(retired IN(0,1))) STRICT;
CREATE TABLE catalog_entities(
 id INTEGER PRIMARY KEY,
 public_id BLOB NOT NULL UNIQUE CHECK(length(public_id)=16),
 library_id INTEGER NOT NULL REFERENCES catalog_libraries(id),
 kind INTEGER NOT NULL REFERENCES catalog_kinds(id),
 parent_id INTEGER REFERENCES catalog_entities(id),
 title TEXT NOT NULL,
 sort_title TEXT NOT NULL DEFAULT '',
 metadata_language TEXT NOT NULL DEFAULT '',
 sort_key TEXT NOT NULL,
 sort_head TEXT NOT NULL,
 year INTEGER NOT NULL DEFAULT 0,
 added_ms INTEGER,
 retired INTEGER NOT NULL DEFAULT 0 CHECK(retired IN(0,1)),
 genre_sources INTEGER NOT NULL DEFAULT 0,
 asset_links INTEGER NOT NULL DEFAULT 0,
 acting_credits INTEGER NOT NULL DEFAULT 0,
 directing_credits INTEGER NOT NULL DEFAULT 0,
 writing_credits INTEGER NOT NULL DEFAULT 0,
 info_desired_epoch INTEGER NOT NULL DEFAULT 1 CHECK(typeof(info_desired_epoch)='integer' AND info_desired_epoch>0),
 info_applied_epoch INTEGER NOT NULL DEFAULT 1 CHECK(typeof(info_applied_epoch)='integer' AND info_applied_epoch>=0 AND info_applied_epoch<=info_desired_epoch),
 info_source_blockers INTEGER NOT NULL DEFAULT 0 CHECK(typeof(info_source_blockers)='integer' AND info_source_blockers>=0),
 info_availability_pending INTEGER NOT NULL DEFAULT 0 CHECK(info_availability_pending IN(0,1)),
 info_blocked_children INTEGER NOT NULL DEFAULT 0 CHECK(typeof(info_blocked_children)='integer' AND info_blocked_children>=0)) STRICT;
CREATE INDEX catalog_entities_title ON catalog_entities(library_id,kind,sort_key,id);
CREATE INDEX catalog_entities_genreless ON catalog_entities(kind,id) WHERE genre_sources=0;
CREATE INDEX catalog_entities_fact_gaps ON catalog_entities(kind,(asset_links=0)+(acting_credits=0)*2+(directing_credits=0)*4+(writing_credits=0)*8,id);
CREATE INDEX catalog_entities_summary_added ON catalog_entities(library_id,kind,retired,added_ms DESC,id DESC);
CREATE INDEX catalog_entities_added ON catalog_entities(library_id,added_ms DESC,id DESC) WHERE added_ms IS NOT NULL;
CREATE INDEX catalog_entities_parent ON catalog_entities(parent_id,id) WHERE parent_id IS NOT NULL;
CREATE INDEX catalog_entities_library ON catalog_entities(library_id,kind,id);
CREATE INDEX catalog_entities_library_id ON catalog_entities(library_id,id);
CREATE TABLE catalog_identities(
 root TEXT NOT NULL,
 source_key TEXT NOT NULL,
 public_id BLOB NOT NULL CHECK(length(public_id)=16),
 kind INTEGER NOT NULL,
 PRIMARY KEY(root,source_key)) WITHOUT ROWID, STRICT;
CREATE INDEX catalog_identities_public ON catalog_identities(public_id);
CREATE TABLE catalog_merged_ids(
 public_id BLOB PRIMARY KEY CHECK(length(public_id)=16),
 entity_id INTEGER NOT NULL REFERENCES catalog_entities(id) ON DELETE CASCADE) WITHOUT ROWID, STRICT;
CREATE INDEX catalog_merged_ids_entity ON catalog_merged_ids(entity_id);
CREATE TABLE catalog_kept_apart(
 entity_id INTEGER PRIMARY KEY REFERENCES catalog_entities(id) ON DELETE CASCADE) STRICT;
CREATE TABLE catalog_assets(
 id INTEGER PRIMARY KEY,
 token TEXT NOT NULL UNIQUE,
 path TEXT NOT NULL UNIQUE,
 size INTEGER NOT NULL,
 modified_ns INTEGER NOT NULL,
 container TEXT NOT NULL,
 video_codec TEXT NOT NULL,
 audio_codec TEXT NOT NULL,
 width INTEGER NOT NULL,
 height INTEGER NOT NULL,
 duration REAL NOT NULL,
 available INTEGER NOT NULL DEFAULT 1 CHECK(available IN(0,1)),
 info_epoch INTEGER NOT NULL DEFAULT 1 CHECK(typeof(info_epoch)='integer' AND info_epoch>0),
 info_order_available INTEGER NOT NULL DEFAULT 1 CHECK(info_order_available IN(0,1)),
 info_owner_object TEXT REFERENCES inventory_objects(id),
 info_owner_revision TEXT,
 CHECK((info_owner_object IS NULL)=(info_owner_revision IS NULL))) STRICT;
CREATE TABLE catalog_asset_links(
 entity_id INTEGER NOT NULL REFERENCES catalog_entities(id) ON DELETE CASCADE,
 asset_id INTEGER NOT NULL REFERENCES catalog_assets(id) ON DELETE CASCADE,
 part_index INTEGER NOT NULL DEFAULT 0,
 available INTEGER NOT NULL DEFAULT 1 CHECK(available IN(0,1)),
 start_seconds REAL NOT NULL DEFAULT 0,
 end_seconds REAL,
 edition TEXT NOT NULL DEFAULT '',
 info_duration REAL NOT NULL DEFAULT 0,
 info_pending_change INTEGER REFERENCES catalog_info_changes(id),
 info_shape_id INTEGER REFERENCES catalog_info_shapes(id),
 PRIMARY KEY(entity_id,asset_id)) WITHOUT ROWID, STRICT;
CREATE INDEX catalog_asset_links_order ON catalog_asset_links(entity_id,part_index,asset_id);
CREATE INDEX catalog_asset_links_asset ON catalog_asset_links(asset_id,entity_id);
CREATE INDEX catalog_assets_duration ON catalog_assets(duration);
CREATE INDEX catalog_assets_height ON catalog_assets(height);
CREATE TABLE catalog_item_version_counts(
 item_id INTEGER PRIMARY KEY,
 versions INTEGER NOT NULL) STRICT;
CREATE INDEX catalog_item_version_counts_value ON catalog_item_version_counts(versions,item_id);
CREATE TRIGGER catalog_entities_asset_links_join AFTER INSERT ON catalog_asset_links BEGIN
 UPDATE catalog_entities SET asset_links=asset_links+1 WHERE id=NEW.entity_id;
END;
CREATE TRIGGER catalog_entities_asset_links_leave AFTER DELETE ON catalog_asset_links BEGIN
 UPDATE catalog_entities SET asset_links=max(0,asset_links-1) WHERE id=OLD.entity_id;
END;
CREATE TRIGGER catalog_entities_asset_links_move AFTER UPDATE OF entity_id ON catalog_asset_links WHEN OLD.entity_id IS NOT NEW.entity_id BEGIN
 UPDATE catalog_entities SET asset_links=max(0,asset_links-1) WHERE id=OLD.entity_id;
 UPDATE catalog_entities SET asset_links=asset_links+1 WHERE id=NEW.entity_id;
END;
CREATE TRIGGER catalog_item_version_counts_join AFTER INSERT ON catalog_asset_links WHEN NEW.part_index=0 BEGIN
 INSERT INTO catalog_item_version_counts(item_id,versions) VALUES(NEW.entity_id,1) ON CONFLICT(item_id) DO UPDATE SET versions=versions+1;
END;
CREATE TRIGGER catalog_item_version_counts_leave AFTER DELETE ON catalog_asset_links WHEN OLD.part_index=0 BEGIN
 UPDATE catalog_item_version_counts SET versions=versions-1 WHERE item_id=OLD.entity_id;
 DELETE FROM catalog_item_version_counts WHERE item_id=OLD.entity_id AND versions<=0;
END;
CREATE TRIGGER catalog_item_version_counts_move AFTER UPDATE OF entity_id,part_index ON catalog_asset_links
 WHEN (OLD.entity_id,OLD.part_index=0) IS NOT (NEW.entity_id,NEW.part_index=0) BEGIN
 UPDATE catalog_item_version_counts SET versions=versions-1 WHERE OLD.part_index=0 AND item_id=OLD.entity_id;
 DELETE FROM catalog_item_version_counts WHERE OLD.part_index=0 AND item_id=OLD.entity_id AND versions<=0;
 INSERT INTO catalog_item_version_counts(item_id,versions) SELECT NEW.entity_id,1 WHERE NEW.part_index=0 ON CONFLICT(item_id) DO UPDATE SET versions=versions+1;
END;
CREATE TABLE catalog_item_details(
 entity_id INTEGER PRIMARY KEY REFERENCES catalog_entities(id) ON DELETE CASCADE,
 added_text TEXT,
 overview TEXT NOT NULL DEFAULT '',
 poster_url TEXT NOT NULL DEFAULT '',
 backdrop_url TEXT NOT NULL DEFAULT '',
 original_title TEXT NOT NULL DEFAULT '',
 edition TEXT NOT NULL DEFAULT '',
 tagline TEXT NOT NULL DEFAULT '',
 release_date TEXT NOT NULL DEFAULT '',
 content_rating TEXT NOT NULL DEFAULT '',
 studio TEXT NOT NULL DEFAULT '',
 network TEXT NOT NULL DEFAULT '',
 country TEXT NOT NULL DEFAULT '',
 tags TEXT NOT NULL DEFAULT '',
 labels TEXT NOT NULL DEFAULT '') STRICT;
CREATE TABLE catalog_item_availability(
 entity_id INTEGER PRIMARY KEY REFERENCES catalog_entities(id) ON DELETE CASCADE,
 available INTEGER NOT NULL CHECK(available IN(0,1)),
 retired INTEGER NOT NULL DEFAULT 0 CHECK(retired IN(0,1))) STRICT;
CREATE TABLE catalog_missing_titles(
 entity_id INTEGER PRIMARY KEY REFERENCES catalog_entities(id) ON DELETE CASCADE,
 library_id INTEGER NOT NULL REFERENCES catalog_libraries(id),
 missing_since_ms INTEGER NOT NULL) STRICT;
CREATE INDEX catalog_missing_titles_library ON catalog_missing_titles(library_id,missing_since_ms,entity_id);
CREATE INDEX catalog_missing_titles_time ON catalog_missing_titles(missing_since_ms,entity_id);
CREATE TABLE catalog_missing_title_counts(
 library_id INTEGER PRIMARY KEY REFERENCES catalog_libraries(id) ON DELETE CASCADE,
 total INTEGER NOT NULL CHECK(total>=0)) STRICT;
CREATE TRIGGER catalog_missing_title_count_insert AFTER INSERT ON catalog_missing_titles BEGIN
 INSERT INTO catalog_missing_title_counts(library_id,total) VALUES(NEW.library_id,1)
 ON CONFLICT(library_id) DO UPDATE SET total=total+1;
END;
CREATE TRIGGER catalog_missing_title_count_delete AFTER DELETE ON catalog_missing_titles BEGIN
 UPDATE catalog_missing_title_counts SET total=total-1 WHERE library_id=OLD.library_id;
END;
CREATE TRIGGER catalog_missing_title_count_move AFTER UPDATE OF library_id ON catalog_missing_titles WHEN OLD.library_id<>NEW.library_id BEGIN
 UPDATE catalog_missing_title_counts SET total=total-1 WHERE library_id=OLD.library_id;
 INSERT INTO catalog_missing_title_counts(library_id,total) VALUES(NEW.library_id,1)
 ON CONFLICT(library_id) DO UPDATE SET total=total+1;
END;
CREATE TABLE retained_title_state(
 id INTEGER PRIMARY KEY,
 profile_id TEXT NOT NULL,
 kind INTEGER NOT NULL,
 title TEXT NOT NULL DEFAULT '',
 watched INTEGER NOT NULL DEFAULT 0 CHECK(watched IN(0,1)),
 watchlisted INTEGER NOT NULL DEFAULT 0 CHECK(watchlisted IN(0,1)),
 favorite INTEGER NOT NULL DEFAULT 0 CHECK(favorite IN(0,1)),
 not_interested INTEGER NOT NULL DEFAULT 0 CHECK(not_interested IN(0,1)),
 rating REAL,
 last_played_at TEXT NOT NULL DEFAULT '',
 plays INTEGER NOT NULL DEFAULT 0,
 position INTEGER NOT NULL DEFAULT 0,
 unit INTEGER NOT NULL DEFAULT 0,
 completed INTEGER NOT NULL DEFAULT 0 CHECK(completed IN(0,1)),
 progress_at TEXT NOT NULL DEFAULT '',
 retained_ms INTEGER NOT NULL) STRICT;
CREATE INDEX retained_title_state_profile ON retained_title_state(profile_id,retained_ms,id);
CREATE TABLE retained_title_state_counts(
 profile_id TEXT PRIMARY KEY,
 title_count INTEGER NOT NULL CHECK(title_count>=0)) WITHOUT ROWID, STRICT;
CREATE TRIGGER retained_title_state_count_insert AFTER INSERT ON retained_title_state BEGIN
 INSERT INTO retained_title_state_counts(profile_id,title_count) VALUES(NEW.profile_id,1)
 ON CONFLICT(profile_id) DO UPDATE SET title_count=title_count+1;
END;
CREATE TRIGGER retained_title_state_count_delete AFTER DELETE ON retained_title_state BEGIN
 UPDATE retained_title_state_counts SET title_count=title_count-1 WHERE profile_id=OLD.profile_id;
 DELETE FROM retained_title_state_counts WHERE profile_id=OLD.profile_id AND title_count=0;
END;
CREATE TABLE retained_title_identities(
 identity TEXT NOT NULL,
 profile_id TEXT NOT NULL,
 state_id INTEGER NOT NULL REFERENCES retained_title_state(id) ON DELETE CASCADE,
 PRIMARY KEY(identity,profile_id)) WITHOUT ROWID, STRICT;
CREATE INDEX retained_title_identities_state ON retained_title_identities(state_id);
CREATE TABLE reading_publications(
 item_id INTEGER NOT NULL REFERENCES catalog_entities(id) ON DELETE CASCADE,
 asset_id INTEGER NOT NULL UNIQUE REFERENCES catalog_assets(id) ON DELETE CASCADE,
 format TEXT NOT NULL CHECK(format IN('epub','pdf','cbz','cb7','mobi','azw3','cbr')),
 PRIMARY KEY(item_id,asset_id),
 FOREIGN KEY(item_id,asset_id) REFERENCES catalog_asset_links(entity_id,asset_id) ON DELETE CASCADE) WITHOUT ROWID, STRICT;
CREATE TABLE reading_source_values(
 item_id INTEGER NOT NULL,
 asset_id INTEGER NOT NULL,
 field TEXT NOT NULL CHECK(field IN('author','series','seriesNumber','issueDate')),
 text_value TEXT,
 number_value REAL,
 source TEXT NOT NULL CHECK(source IN('file-name','folder','file-metadata')),
 inventory_object_id TEXT NOT NULL REFERENCES inventory_objects(id) ON DELETE CASCADE,
 source_revision TEXT NOT NULL CHECK(length(source_revision)>0),
 PRIMARY KEY(item_id,asset_id,field,source),
 FOREIGN KEY(item_id,asset_id) REFERENCES reading_publications(item_id,asset_id) ON DELETE CASCADE,
 CHECK(field<>'issueDate' OR (source='file-name' AND length(text_value) IN(7,10))),
 CHECK((field IN('author','series','issueDate') AND text_value IS NOT NULL AND length(text_value) BETWEEN 1 AND 4096 AND number_value IS NULL)
    OR (field='seriesNumber' AND text_value IS NULL AND number_value IS NOT NULL AND number_value>=0 AND number_value<=1.7976931348623157e308))) WITHOUT ROWID, STRICT;
-- Explicit recognized file type, separate from ebook/comic entity and owner metadata.
CREATE TABLE reading_publication_types(
 item_id INTEGER NOT NULL,
 asset_id INTEGER NOT NULL,
 publication_type TEXT CHECK(publication_type IS NULL OR publication_type IN('book','magazine','newspaper')),
 source_format TEXT NOT NULL CHECK(source_format IN('epub','cbz')),
 source_field TEXT NOT NULL CHECK(length(source_field) BETWEEN 1 AND 256),
 source_raw_json TEXT NOT NULL CHECK(json_valid(source_raw_json) AND json_type(source_raw_json)='array' AND json_array_length(source_raw_json)<=64 AND length(source_raw_json)<=262144),
 evidence_complete INTEGER NOT NULL CHECK(evidence_complete IN(0,1)),
 inventory_object_id TEXT NOT NULL REFERENCES inventory_objects(id) ON DELETE CASCADE,
 source_revision TEXT NOT NULL CHECK(length(source_revision)>0),
 classifier_version INTEGER NOT NULL CHECK(classifier_version>0),
 CHECK(publication_type IS NULL OR evidence_complete=1),
 PRIMARY KEY(item_id,asset_id),
 FOREIGN KEY(item_id,asset_id) REFERENCES reading_publications(item_id,asset_id) ON DELETE CASCADE) WITHOUT ROWID, STRICT;
CREATE INDEX reading_publication_types_inventory_object ON reading_publication_types(inventory_object_id);
-- Complete deterministic source-text evidence; NULL is unknown, never a zero guess.
CREATE TABLE reading_text_counts(
 item_id INTEGER NOT NULL,
 asset_id INTEGER NOT NULL,
 word_count INTEGER CHECK(word_count IS NULL OR word_count BETWEEN 0 AND 67108864),
 opening_lines TEXT CHECK(opening_lines IS NULL OR length(opening_lines)<=4096),
 opening_rule_version INTEGER NOT NULL DEFAULT 0 CHECK(opening_rule_version IN(0,1)),
 page_count INTEGER CHECK(page_count IS NULL OR page_count BETWEEN 1 AND 4096),
 page_rule_version INTEGER NOT NULL DEFAULT 0 CHECK(page_rule_version IN(0,1)),
 inventory_object_id TEXT NOT NULL REFERENCES inventory_objects(id) ON DELETE CASCADE,
 source_revision TEXT NOT NULL CHECK(length(source_revision)>0),
 rule_version INTEGER NOT NULL CHECK(rule_version>0),
 PRIMARY KEY(item_id,asset_id),
 FOREIGN KEY(item_id,asset_id) REFERENCES reading_publications(item_id,asset_id) ON DELETE CASCADE) WITHOUT ROWID, STRICT;
CREATE INDEX reading_text_counts_inventory_object ON reading_text_counts(inventory_object_id);

-- One global, monotonically moving revision for the persisted Reading text
-- index. Every accepting index transaction bumps it through the state triggers
-- below, so a cursor minted against an older index is refused instead of
-- continuing over changed hits.
CREATE TABLE reading_text_index_epoch(
 singleton INTEGER PRIMARY KEY CHECK(singleton=1),
 revision INTEGER NOT NULL CHECK(revision>0)) STRICT;
-- The one logical payload budget. It is derived text bytes, not measured
-- SQLite/FTS physical size, and every state insert, update or delete adjusts it
-- in the same transaction. The CHECK is the accounting guard.
CREATE TABLE reading_text_index_budget(
 singleton INTEGER PRIMARY KEY CHECK(singleton=1),
 payload_bytes INTEGER NOT NULL CHECK(payload_bytes BETWEEN 0 AND 1073741824)) STRICT;
INSERT INTO reading_text_index_budget(singleton,payload_bytes) VALUES(1,0);
-- One determined outcome for an exact publication observation. Publication and
-- inventory-object deletion cascade here, and foreign-key actions fire the
-- state delete trigger just like an ordinary DELETE (the recursive_triggers
-- pragma governs recursive trigger programs, not foreign-key actions). That
-- trigger removes the sections, returns the payload and bumps the revision, so
-- a cascade cannot orphan private derived text or a posting.
CREATE TABLE reading_text_index_state(
 item_id INTEGER NOT NULL,
 asset_id INTEGER NOT NULL,
 inventory_object_id TEXT NOT NULL REFERENCES inventory_objects(id) ON DELETE CASCADE,
 source_revision TEXT NOT NULL CHECK(length(source_revision)>0),
 index_rule_version INTEGER NOT NULL CHECK(index_rule_version>0),
 outcome TEXT NOT NULL CHECK(outcome IN('indexed','evicted','excluded','unsupported')),
 reason TEXT NOT NULL CHECK(length(reason)<=64),
 text_bytes INTEGER NOT NULL CHECK(text_bytes BETWEEN 0 AND 8388608),
 section_count INTEGER NOT NULL CHECK(section_count BETWEEN 0 AND 4096),
 indexed_at INTEGER NOT NULL CHECK(indexed_at>0),
 PRIMARY KEY(item_id,asset_id),
 FOREIGN KEY(item_id,asset_id) REFERENCES reading_publications(item_id,asset_id) ON DELETE CASCADE) WITHOUT ROWID, STRICT;
CREATE INDEX reading_text_index_state_eviction ON reading_text_index_state(outcome,indexed_at,item_id,asset_id);
CREATE INDEX reading_text_index_state_inventory_object ON reading_text_index_state(inventory_object_id);
-- Private derived spine text. id is the FTS external-content rowid and is never
-- reused, so a stale FTS entry can never collide with a later section. The
-- state foreign key is only a safety net: the state delete trigger removes the
-- sections first, so its cascade never removes a posting behind the trigger's
-- back.
CREATE TABLE reading_text_sections(
 id INTEGER PRIMARY KEY AUTOINCREMENT,
 item_id INTEGER NOT NULL,
 asset_id INTEGER NOT NULL,
 section_index INTEGER NOT NULL CHECK(section_index BETWEEN 0 AND 4095),
 section_path TEXT NOT NULL CHECK(length(section_path) BETWEEN 1 AND 1024),
 text TEXT NOT NULL CHECK(length(CAST(text AS BLOB)) BETWEEN 1 AND 8388608),
 utf16_length INTEGER NOT NULL CHECK(utf16_length BETWEEN 1 AND 8388608),
 UNIQUE(item_id,asset_id,section_index),
 FOREIGN KEY(item_id,asset_id) REFERENCES reading_text_index_state(item_id,asset_id) ON DELETE CASCADE) STRICT;
CREATE VIRTUAL TABLE reading_text_fts USING fts5(text,content='reading_text_sections',content_rowid='id',tokenize='unicode61 remove_diacritics 2');
-- Every section deletion, whatever statement caused it, removes its exact
-- external-content posting. This is the only posting-deletion path.
CREATE TRIGGER reading_text_sections_fts_delete AFTER DELETE ON reading_text_sections BEGIN
 INSERT INTO reading_text_fts(reading_text_fts,rowid,text) VALUES('delete',OLD.id,OLD.text);
END;
-- One state insertion or update moves the logical payload by its exact delta
-- and bumps the global index revision. A negative or overflowing budget aborts
-- the transaction through the budget CHECK rather than caching a wrong number.
CREATE TRIGGER reading_text_index_state_insert AFTER INSERT ON reading_text_index_state BEGIN
 UPDATE reading_text_index_budget SET payload_bytes=payload_bytes+NEW.text_bytes WHERE singleton=1;
 INSERT INTO reading_text_index_epoch(singleton,revision) VALUES(1,1) ON CONFLICT(singleton) DO UPDATE SET revision=revision+1;
END;
CREATE TRIGGER reading_text_index_state_update AFTER UPDATE ON reading_text_index_state BEGIN
 UPDATE reading_text_index_budget SET payload_bytes=payload_bytes+NEW.text_bytes-OLD.text_bytes WHERE singleton=1;
 INSERT INTO reading_text_index_epoch(singleton,revision) VALUES(1,1) ON CONFLICT(singleton) DO UPDATE SET revision=revision+1;
END;
-- An explicit state deletion removes its sections first (their trigger deletes
-- the postings), then returns the payload and bumps the revision.
CREATE TRIGGER reading_text_index_state_delete BEFORE DELETE ON reading_text_index_state BEGIN
 DELETE FROM reading_text_sections WHERE item_id=OLD.item_id AND asset_id=OLD.asset_id;
 UPDATE reading_text_index_budget SET payload_bytes=payload_bytes-OLD.text_bytes WHERE singleton=1;
 INSERT INTO reading_text_index_epoch(singleton,revision) VALUES(1,1) ON CONFLICT(singleton) DO UPDATE SET revision=revision+1;
END;
-- One determined scan-time cover outcome for an exact publication observation.
-- adopted: the automatic cover was written; absent: the package declares no
-- explicit cover; invalid: declared bytes are not adoptable. Transient failures
-- carry no row and are retried. Owner or other selected art is never replaced.
CREATE TABLE reading_cover_inspections(
 item_id INTEGER NOT NULL,
 asset_id INTEGER NOT NULL,
 inventory_object_id TEXT NOT NULL REFERENCES inventory_objects(id) ON DELETE CASCADE,
 source_revision TEXT NOT NULL CHECK(length(source_revision)>0),
 rule_version INTEGER NOT NULL CHECK(rule_version>0),
 outcome TEXT NOT NULL CHECK(outcome IN('adopted','absent','invalid')),
 attempted_at TEXT NOT NULL,
 PRIMARY KEY(item_id,asset_id),
 FOREIGN KEY(item_id,asset_id) REFERENCES reading_publications(item_id,asset_id) ON DELETE CASCADE) WITHOUT ROWID, STRICT;
CREATE INDEX reading_cover_inspections_inventory_object ON reading_cover_inspections(inventory_object_id);
CREATE TABLE reading_annotation_sets(
 owner_key TEXT NOT NULL,
 item_id INTEGER NOT NULL,
 asset_id INTEGER NOT NULL,
 source_revision TEXT NOT NULL CHECK(length(source_revision) BETWEEN 1 AND 256),
 revision INTEGER NOT NULL CHECK(revision BETWEEN 1 AND 9007199254740991),
 PRIMARY KEY(owner_key,item_id,asset_id,source_revision),
 FOREIGN KEY(item_id,asset_id) REFERENCES reading_publications(item_id,asset_id) ON DELETE CASCADE) WITHOUT ROWID, STRICT;
CREATE INDEX reading_annotation_sets_publication ON reading_annotation_sets(item_id,asset_id);
CREATE TABLE reading_annotations(
 owner_key TEXT NOT NULL,
 item_id INTEGER NOT NULL,
 asset_id INTEGER NOT NULL,
 source_revision TEXT NOT NULL CHECK(length(source_revision) BETWEEN 1 AND 256),
 id TEXT NOT NULL CHECK(length(id) BETWEEN 1 AND 64),
 kind TEXT NOT NULL CHECK(kind IN('bookmark','highlight')),
 format TEXT NOT NULL CHECK(format IN('epub','pdf','cbz','cb7','cbr')),
 cfi TEXT CHECK(cfi IS NULL OR length(cfi)<=4096),
 section TEXT CHECK(section IS NULL OR length(section)<=1024),
 page_index INTEGER,
 progression REAL NOT NULL CHECK(progression>=0 AND progression<=1),
 quote TEXT NOT NULL CHECK(length(quote)<=8192),
 note TEXT NOT NULL CHECK(length(note)<=4096),
 colour TEXT NOT NULL,
 created_at INTEGER NOT NULL CHECK(created_at BETWEEN 0 AND 9007199254740991),
 updated_at INTEGER NOT NULL CHECK(updated_at BETWEEN created_at AND 9007199254740991),
 PRIMARY KEY(owner_key,item_id,asset_id,source_revision,id),
 FOREIGN KEY(owner_key,item_id,asset_id,source_revision) REFERENCES reading_annotation_sets(owner_key,item_id,asset_id,source_revision) ON DELETE CASCADE,
 CHECK((kind='bookmark' AND quote='' AND colour='') OR (kind='highlight' AND length(quote)>0 AND colour IN('yellow','green','blue','pink'))),
 CHECK((format='epub' AND cfi IS NOT NULL AND page_index IS NULL) OR (format IN('pdf','cbz','cb7','cbr') AND cfi IS NULL AND section IS NULL AND page_index IS NOT NULL AND page_index BETWEEN 0 AND 1000000))) WITHOUT ROWID, STRICT;
CREATE TABLE reading_annotation_rects(
 owner_key TEXT NOT NULL,
 item_id INTEGER NOT NULL,
 asset_id INTEGER NOT NULL,
 source_revision TEXT NOT NULL,
 annotation_id TEXT NOT NULL,
 ordinal INTEGER NOT NULL CHECK(ordinal BETWEEN 0 AND 127),
 x REAL NOT NULL CHECK(x>=0 AND x<=1),
 y REAL NOT NULL CHECK(y>=0 AND y<=1),
 width REAL NOT NULL CHECK(width>0 AND width<=1 AND x+width<=1),
 height REAL NOT NULL CHECK(height>0 AND height<=1 AND y+height<=1),
 PRIMARY KEY(owner_key,item_id,asset_id,source_revision,annotation_id,ordinal),
 FOREIGN KEY(owner_key,item_id,asset_id,source_revision,annotation_id) REFERENCES reading_annotations(owner_key,item_id,asset_id,source_revision,id) ON DELETE CASCADE
) WITHOUT ROWID, STRICT;
CREATE TABLE reading_progress(
 owner_key TEXT NOT NULL,
 item_id INTEGER NOT NULL,
 asset_id INTEGER NOT NULL,
 source_revision TEXT NOT NULL CHECK(length(source_revision) BETWEEN 1 AND 256),
 format TEXT NOT NULL CHECK(format IN('epub','pdf','cbz','cb7','cbr')),
 cfi TEXT CHECK(cfi IS NULL OR length(cfi)<=8192),
 section TEXT CHECK(section IS NULL OR length(section)<=4096),
 page_index INTEGER,
 progression REAL NOT NULL CHECK(progression>=0 AND progression<=1),
 revision INTEGER NOT NULL CHECK(revision BETWEEN 1 AND 9007199254740991),
 observed_at INTEGER NOT NULL CHECK(observed_at BETWEEN 0 AND 9007199254740991),
 PRIMARY KEY(owner_key,item_id,asset_id),
 FOREIGN KEY(item_id,asset_id) REFERENCES reading_publications(item_id,asset_id) ON DELETE CASCADE,
 CHECK((format='epub' AND page_index IS NULL) OR (format IN('pdf','cbz','cb7','cbr') AND page_index IS NOT NULL AND page_index BETWEEN 0 AND 9007199254740991 AND cfi IS NULL AND section IS NULL))) WITHOUT ROWID, STRICT;
CREATE INDEX reading_progress_publication ON reading_progress(item_id,asset_id);
CREATE INDEX reading_progress_recent ON reading_progress(owner_key,observed_at DESC,item_id DESC,asset_id DESC);
CREATE TABLE retained_reading_progress(
 state_id INTEGER NOT NULL REFERENCES retained_title_state(id) ON DELETE CASCADE,
 source_id TEXT NOT NULL CHECK(length(source_id)>0),
 source_revision TEXT NOT NULL CHECK(length(source_revision) BETWEEN 1 AND 256),
 format TEXT NOT NULL CHECK(format IN('epub','pdf','cbz','cb7','cbr')),
 cfi TEXT CHECK(cfi IS NULL OR length(cfi)<=8192),
 section TEXT CHECK(section IS NULL OR length(section)<=4096),
 page_index INTEGER,
 progression REAL NOT NULL CHECK(progression>=0 AND progression<=1),
 revision INTEGER NOT NULL CHECK(revision BETWEEN 1 AND 9007199254740991),
 observed_at INTEGER NOT NULL CHECK(observed_at BETWEEN 0 AND 9007199254740991),
 PRIMARY KEY(state_id,source_id),
 CHECK((format='epub' AND page_index IS NULL) OR (format IN('pdf','cbz','cb7','cbr') AND page_index IS NOT NULL AND page_index BETWEEN 0 AND 9007199254740991 AND cfi IS NULL AND section IS NULL))) WITHOUT ROWID, STRICT;
CREATE TABLE catalog_shows(
 entity_id INTEGER PRIMARY KEY REFERENCES catalog_entities(id) ON DELETE CASCADE,
 local_key TEXT NOT NULL,
 source_edition TEXT NOT NULL DEFAULT '',
 provider_match_status TEXT NOT NULL DEFAULT 'unmatched',
 original_title TEXT NOT NULL DEFAULT '',
 tagline TEXT NOT NULL DEFAULT '',
 overview TEXT NOT NULL DEFAULT '',
 content_rating TEXT NOT NULL DEFAULT '',
 studio TEXT NOT NULL DEFAULT '',
 network TEXT NOT NULL DEFAULT '',
 country TEXT NOT NULL DEFAULT '',
 tags TEXT NOT NULL DEFAULT '',
 labels TEXT NOT NULL DEFAULT '') STRICT;
