 deleted INTEGER NOT NULL DEFAULT 0 CHECK(deleted IN(0,1)),
 created_at TEXT NOT NULL,
 entry_count INTEGER NOT NULL DEFAULT 0 CHECK(entry_count>=0),
 updated_at TEXT NOT NULL DEFAULT '',
 UNIQUE(owner_authority,owner_account,owner_profile,creation_operation)) STRICT;
CREATE INDEX catalog_playlists_owner ON catalog_playlists(owner_authority,owner_account,owner_profile,deleted,name COLLATE NOCASE,id);
CREATE TABLE catalog_playlist_entries(
 id INTEGER PRIMARY KEY,
 token TEXT NOT NULL UNIQUE,
 playlist_id INTEGER NOT NULL REFERENCES catalog_playlists(id) ON DELETE CASCADE,
 item_id INTEGER REFERENCES catalog_entities(id) ON DELETE SET NULL,
 position INTEGER NOT NULL,
 order_key TEXT NOT NULL DEFAULT '',
 UNIQUE(playlist_id,position)) STRICT;
CREATE INDEX catalog_playlist_entries_page ON catalog_playlist_entries(playlist_id,order_key,id);
CREATE INDEX catalog_playlist_entries_item ON catalog_playlist_entries(item_id) WHERE item_id IS NOT NULL;
CREATE TABLE metadata_kept_files(
 entity_id INTEGER PRIMARY KEY REFERENCES catalog_entities(id) ON DELETE CASCADE,
 files_fingerprint TEXT NOT NULL) STRICT;
CREATE TABLE catalog_people(
 id INTEGER PRIMARY KEY,
 token TEXT NOT NULL UNIQUE,
 identity_key TEXT NOT NULL,
 name TEXT NOT NULL,
 sort_name TEXT NOT NULL,
 biography TEXT NOT NULL DEFAULT '',
 birth_place TEXT NOT NULL DEFAULT '',
 biography_source TEXT NOT NULL DEFAULT '',
 birth_date TEXT NOT NULL DEFAULT '',
 death_date TEXT NOT NULL DEFAULT '',
 portrait_url TEXT NOT NULL DEFAULT '',
 provider_ids TEXT NOT NULL DEFAULT '{}',
 revision INTEGER NOT NULL DEFAULT 1) STRICT;
CREATE INDEX catalog_people_name ON catalog_people(sort_name,id);
CREATE UNIQUE INDEX catalog_people_identity ON catalog_people(identity_key);
CREATE TABLE catalog_people_aliases(
 alias TEXT PRIMARY KEY,
 person_id INTEGER NOT NULL REFERENCES catalog_people(id) ON DELETE CASCADE) WITHOUT ROWID, STRICT;
CREATE INDEX catalog_people_aliases_person ON catalog_people_aliases(person_id);
CREATE TABLE catalog_credits(
 entity_id INTEGER NOT NULL REFERENCES catalog_entities(id) ON DELETE CASCADE,
 ord INTEGER NOT NULL,
 person_id INTEGER REFERENCES catalog_people(id),
 role_id INTEGER NOT NULL REFERENCES catalog_credit_labels(id),
 department_id INTEGER NOT NULL REFERENCES catalog_credit_labels(id),
 credited_name TEXT NOT NULL,
 provider TEXT NOT NULL,
 credit_id TEXT NOT NULL,
 provider_person_id TEXT NOT NULL DEFAULT '',
 source_ordinal INTEGER NOT NULL,
 source_row_id TEXT,
 owner_entry_id TEXT,
 source_status TEXT NOT NULL DEFAULT 'current' CHECK(source_status IN('current','missing','replaced')),
 FOREIGN KEY(source_row_id,entity_id) REFERENCES credit_source_rows(source_row_id,entity_id),
 FOREIGN KEY(owner_entry_id,entity_id) REFERENCES credit_owner_entries(entry_id,entity_id),
 PRIMARY KEY(entity_id,ord)) WITHOUT ROWID, STRICT;
CREATE INDEX catalog_credits_person ON catalog_credits(person_id,entity_id);
CREATE INDEX catalog_credits_provider_person ON catalog_credits(provider,provider_person_id,entity_id) WHERE provider_person_id<>'';
CREATE INDEX catalog_credits_name ON catalog_credits(credited_name,entity_id);
CREATE INDEX catalog_credits_source_row ON catalog_credits(source_row_id,entity_id);
CREATE INDEX catalog_credits_owner_entry ON catalog_credits(owner_entry_id,entity_id);
CREATE TABLE catalog_credit_names(
 name TEXT PRIMARY KEY,
 credits INTEGER NOT NULL) WITHOUT ROWID, STRICT;
CREATE TRIGGER catalog_credit_names_join AFTER INSERT ON catalog_credits BEGIN
 INSERT INTO catalog_credit_names(name,credits) VALUES(NEW.credited_name,1) ON CONFLICT(name) DO UPDATE SET credits=credits+1;
END;
CREATE TRIGGER catalog_credit_names_leave AFTER DELETE ON catalog_credits BEGIN
 UPDATE catalog_credit_names SET credits=credits-1 WHERE name=OLD.credited_name;
 DELETE FROM catalog_credit_names WHERE name=OLD.credited_name AND credits<=0;
END;
CREATE TRIGGER catalog_credit_names_move AFTER UPDATE OF credited_name ON catalog_credits WHEN OLD.credited_name IS NOT NEW.credited_name BEGIN
 UPDATE catalog_credit_names SET credits=credits-1 WHERE name=OLD.credited_name;
 DELETE FROM catalog_credit_names WHERE name=OLD.credited_name AND credits<=0;
 INSERT INTO catalog_credit_names(name,credits) VALUES(NEW.credited_name,1) ON CONFLICT(name) DO UPDATE SET credits=credits+1;
END;
CREATE TABLE catalog_person_credit_counts(
 person_id INTEGER NOT NULL,
 library_id INTEGER NOT NULL,
 department_id INTEGER NOT NULL,
 credits INTEGER NOT NULL,
 PRIMARY KEY(person_id,library_id,department_id)) WITHOUT ROWID, STRICT;
CREATE TRIGGER catalog_entities_credit_roles_join AFTER INSERT ON catalog_credits BEGIN
 UPDATE catalog_entities SET acting_credits=acting_credits+COALESCE(((SELECT label FROM catalog_credit_labels WHERE id=NEW.department_id)='Acting'),0),directing_credits=directing_credits+COALESCE(((SELECT label FROM catalog_credit_labels WHERE id=NEW.role_id)='Director' OR (SELECT label FROM catalog_credit_labels WHERE id=NEW.department_id)='Directing'),0),writing_credits=writing_credits+COALESCE(((SELECT label FROM catalog_credit_labels WHERE id=NEW.role_id) IN('Writer','Screenplay') OR (SELECT label FROM catalog_credit_labels WHERE id=NEW.department_id)='Writing'),0) WHERE id=NEW.entity_id;
END;
CREATE TRIGGER catalog_entities_credit_roles_leave AFTER DELETE ON catalog_credits BEGIN
 UPDATE catalog_entities SET acting_credits=max(0,acting_credits-COALESCE(((SELECT label FROM catalog_credit_labels WHERE id=OLD.department_id)='Acting'),0)),directing_credits=max(0,directing_credits-COALESCE(((SELECT label FROM catalog_credit_labels WHERE id=OLD.role_id)='Director' OR (SELECT label FROM catalog_credit_labels WHERE id=OLD.department_id)='Directing'),0)),writing_credits=max(0,writing_credits-COALESCE(((SELECT label FROM catalog_credit_labels WHERE id=OLD.role_id) IN('Writer','Screenplay') OR (SELECT label FROM catalog_credit_labels WHERE id=OLD.department_id)='Writing'),0)) WHERE id=OLD.entity_id;
END;
CREATE TRIGGER catalog_entities_credit_roles_move AFTER UPDATE OF entity_id,role_id,department_id ON catalog_credits
 WHEN OLD.entity_id IS NOT NEW.entity_id OR OLD.role_id IS NOT NEW.role_id OR OLD.department_id IS NOT NEW.department_id BEGIN
 UPDATE catalog_entities SET acting_credits=max(0,acting_credits-COALESCE(((SELECT label FROM catalog_credit_labels WHERE id=OLD.department_id)='Acting'),0)),directing_credits=max(0,directing_credits-COALESCE(((SELECT label FROM catalog_credit_labels WHERE id=OLD.role_id)='Director' OR (SELECT label FROM catalog_credit_labels WHERE id=OLD.department_id)='Directing'),0)),writing_credits=max(0,writing_credits-COALESCE(((SELECT label FROM catalog_credit_labels WHERE id=OLD.role_id) IN('Writer','Screenplay') OR (SELECT label FROM catalog_credit_labels WHERE id=OLD.department_id)='Writing'),0)) WHERE id=OLD.entity_id;
 UPDATE catalog_entities SET acting_credits=acting_credits+COALESCE(((SELECT label FROM catalog_credit_labels WHERE id=NEW.department_id)='Acting'),0),directing_credits=directing_credits+COALESCE(((SELECT label FROM catalog_credit_labels WHERE id=NEW.role_id)='Director' OR (SELECT label FROM catalog_credit_labels WHERE id=NEW.department_id)='Directing'),0),writing_credits=writing_credits+COALESCE(((SELECT label FROM catalog_credit_labels WHERE id=NEW.role_id) IN('Writer','Screenplay') OR (SELECT label FROM catalog_credit_labels WHERE id=NEW.department_id)='Writing'),0) WHERE id=NEW.entity_id;
END;
CREATE TRIGGER catalog_person_credit_counts_join AFTER INSERT ON catalog_credits WHEN NEW.person_id IS NOT NULL BEGIN
 INSERT INTO catalog_person_credit_counts(person_id,library_id,department_id,credits) SELECT NEW.person_id,e.library_id,NEW.department_id,1 FROM catalog_entities e WHERE e.id=NEW.entity_id
  ON CONFLICT(person_id,library_id,department_id) DO UPDATE SET credits=credits+1;
END;
CREATE TRIGGER catalog_person_credit_counts_leave AFTER DELETE ON catalog_credits WHEN OLD.person_id IS NOT NULL BEGIN
 UPDATE catalog_person_credit_counts SET credits=credits-1 WHERE person_id=OLD.person_id AND department_id=OLD.department_id AND library_id=(SELECT library_id FROM catalog_entities WHERE id=OLD.entity_id);
 DELETE FROM catalog_person_credit_counts WHERE person_id=OLD.person_id AND department_id=OLD.department_id AND library_id=(SELECT library_id FROM catalog_entities WHERE id=OLD.entity_id) AND credits<=0;
END;
CREATE TRIGGER catalog_person_credit_counts_move AFTER UPDATE OF person_id,department_id,entity_id ON catalog_credits
 WHEN (OLD.person_id,OLD.department_id,OLD.entity_id) IS NOT (NEW.person_id,NEW.department_id,NEW.entity_id) BEGIN
 UPDATE catalog_person_credit_counts SET credits=credits-1 WHERE OLD.person_id IS NOT NULL AND person_id=OLD.person_id AND department_id=OLD.department_id AND library_id=(SELECT library_id FROM catalog_entities WHERE id=OLD.entity_id);
 DELETE FROM catalog_person_credit_counts WHERE OLD.person_id IS NOT NULL AND person_id=OLD.person_id AND department_id=OLD.department_id AND library_id=(SELECT library_id FROM catalog_entities WHERE id=OLD.entity_id) AND credits<=0;
 INSERT INTO catalog_person_credit_counts(person_id,library_id,department_id,credits) SELECT NEW.person_id,e.library_id,NEW.department_id,1 FROM catalog_entities e WHERE NEW.person_id IS NOT NULL AND e.id=NEW.entity_id
  ON CONFLICT(person_id,library_id,department_id) DO UPDATE SET credits=credits+1;
END;
CREATE TRIGGER catalog_person_credit_counts_entity_delete BEFORE DELETE ON catalog_entities BEGIN
 DELETE FROM catalog_credits WHERE entity_id=OLD.id;
END;
CREATE TRIGGER catalog_person_credit_counts_entity_move AFTER UPDATE OF library_id ON catalog_entities WHEN OLD.library_id IS NOT NEW.library_id BEGIN
 UPDATE catalog_person_credit_counts SET credits=credits-(SELECT count(*) FROM catalog_credits c WHERE c.entity_id=NEW.id AND c.person_id=catalog_person_credit_counts.person_id AND c.department_id=catalog_person_credit_counts.department_id)
  WHERE library_id=OLD.library_id AND EXISTS(SELECT 1 FROM catalog_credits c WHERE c.entity_id=NEW.id AND c.person_id=catalog_person_credit_counts.person_id AND c.department_id=catalog_person_credit_counts.department_id);
 DELETE FROM catalog_person_credit_counts WHERE library_id=OLD.library_id AND credits<=0 AND person_id IN(SELECT person_id FROM catalog_credits WHERE entity_id=NEW.id);
 INSERT INTO catalog_person_credit_counts(person_id,library_id,department_id,credits) SELECT person_id,NEW.library_id,department_id,count(*) FROM catalog_credits WHERE entity_id=NEW.id AND person_id IS NOT NULL GROUP BY person_id,department_id
  ON CONFLICT(person_id,library_id,department_id) DO UPDATE SET credits=credits+excluded.credits;
END;
CREATE TABLE catalog_term_sources(
 entity_id INTEGER NOT NULL,
 term_id INTEGER NOT NULL,
 provider TEXT NOT NULL,
 source_id TEXT NOT NULL,
 label_override TEXT,
 source_name TEXT NOT NULL DEFAULT '',
 ordinal INTEGER NOT NULL DEFAULT 0,
 PRIMARY KEY(entity_id,provider,source_id),
 FOREIGN KEY(entity_id,term_id) REFERENCES catalog_entity_terms(entity_id,term_id) ON DELETE CASCADE) WITHOUT ROWID, STRICT;
CREATE INDEX catalog_term_sources_overrides ON catalog_term_sources(label_override,entity_id,term_id) WHERE label_override IS NOT NULL;
CREATE INDEX catalog_term_source_membership ON catalog_term_sources(entity_id,term_id);
CREATE INDEX catalog_term_sources_provider ON catalog_term_sources(provider,source_id,entity_id);
CREATE INDEX catalog_term_sources_name_seek ON catalog_term_sources(source_name COLLATE NOCASE,entity_id);
CREATE TRIGGER catalog_entities_genre_sources_join AFTER INSERT ON catalog_term_sources WHEN (SELECT vocab FROM catalog_terms WHERE id=NEW.term_id)=1 BEGIN
 UPDATE catalog_entities SET genre_sources=genre_sources+1 WHERE id=NEW.entity_id;
END;
CREATE TRIGGER catalog_entities_genre_sources_leave AFTER DELETE ON catalog_term_sources WHEN (SELECT vocab FROM catalog_terms WHERE id=OLD.term_id)=1 BEGIN
 UPDATE catalog_entities SET genre_sources=max(0,genre_sources-1) WHERE id=OLD.entity_id;
END;
CREATE TRIGGER catalog_entities_genre_sources_move AFTER UPDATE OF entity_id,term_id ON catalog_term_sources WHEN OLD.entity_id IS NOT NEW.entity_id OR OLD.term_id IS NOT NEW.term_id BEGIN
 UPDATE catalog_entities SET genre_sources=max(0,genre_sources-1) WHERE id=OLD.entity_id AND (SELECT vocab FROM catalog_terms WHERE id=OLD.term_id)=1;
 UPDATE catalog_entities SET genre_sources=genre_sources+1 WHERE id=NEW.entity_id AND (SELECT vocab FROM catalog_terms WHERE id=NEW.term_id)=1;
END;
CREATE TABLE catalog_related_facets(
 entity_id INTEGER NOT NULL REFERENCES catalog_entities(id) ON DELETE CASCADE,
