 normalized TEXT NOT NULL,
 kind TEXT NOT NULL,
 library_id INTEGER NOT NULL DEFAULT 0,entity_kind INTEGER NOT NULL DEFAULT 0,container INTEGER NOT NULL DEFAULT 0,rating_key TEXT NOT NULL DEFAULT '',label_key TEXT NOT NULL DEFAULT '') STRICT;
CREATE VIRTUAL TABLE catalog_search_titles USING fts5(
 search,kind,content='catalog_search_documents',content_rowid='entity_id',
 tokenize='unicode61 remove_diacritics 2',prefix='2 3 4');
CREATE TABLE catalog_dirty(
