 title TEXT NOT NULL,
 sort_key TEXT NOT NULL,
 head TEXT NOT NULL,
 year INTEGER NOT NULL,
 added_text TEXT,
 item_id INTEGER REFERENCES catalog_entities(id),
 rating_key TEXT NOT NULL,
 label_key TEXT NOT NULL,
 available INTEGER NOT NULL CHECK(available IN(0,1)),
 recent INTEGER NOT NULL CHECK(recent IN(0,1)),
 backdrop INTEGER NOT NULL CHECK(backdrop IN(0,1)),
 duration_max REAL,
 rating_max REAL,
 recent_text TEXT,
 release_key TEXT NOT NULL DEFAULT '',
 latest_aired_key TEXT NOT NULL DEFAULT '',
 critic_key REAL NOT NULL DEFAULT 0,
 episode_count INTEGER NOT NULL DEFAULT 0,
 album_key TEXT NOT NULL DEFAULT '',
 artist_key TEXT NOT NULL DEFAULT '',
 track_key INTEGER NOT NULL DEFAULT 0,
 file_size INTEGER NOT NULL DEFAULT 0,
 resolution_key INTEGER NOT NULL DEFAULT 0,
 random_key INTEGER NOT NULL DEFAULT 0,
 availability_state TEXT NOT NULL DEFAULT 'unavailable') STRICT;
CREATE INDEX catalog_browse_release_key ON catalog_browse_rows(library_id,kind,release_key,entity_id);
CREATE INDEX catalog_browse_latest_aired_key ON catalog_browse_rows(library_id,kind,latest_aired_key,entity_id);
CREATE INDEX catalog_browse_critic_key ON catalog_browse_rows(library_id,kind,critic_key,entity_id);
CREATE INDEX catalog_browse_episode_count ON catalog_browse_rows(library_id,kind,episode_count,entity_id);
CREATE INDEX catalog_browse_album_key ON catalog_browse_rows(library_id,kind,album_key,entity_id);
CREATE INDEX catalog_browse_artist_key ON catalog_browse_rows(library_id,kind,artist_key,entity_id);
CREATE INDEX catalog_browse_track_key ON catalog_browse_rows(library_id,kind,track_key,entity_id);
CREATE INDEX catalog_browse_file_size ON catalog_browse_rows(library_id,kind,file_size,entity_id);
CREATE INDEX catalog_browse_resolution_key ON catalog_browse_rows(library_id,kind,resolution_key,entity_id);
CREATE INDEX catalog_browse_availability ON catalog_browse_rows(library_id,kind,availability_state,sort_key COLLATE NOCASE,entity_id);
CREATE VIRTUAL TABLE catalog_title_grams USING fts5(title,content='',contentless_delete=1,tokenize='trigram case_sensitive 1',detail='none');
CREATE TRIGGER catalog_title_grams_insert AFTER INSERT ON catalog_browse_rows BEGIN
 INSERT INTO catalog_title_grams(rowid,title) VALUES(NEW.entity_id,portico_fold_text(NEW.title)); END;
CREATE TRIGGER catalog_title_grams_update AFTER UPDATE OF title ON catalog_browse_rows WHEN OLD.title IS NOT NEW.title BEGIN
 DELETE FROM catalog_title_grams WHERE rowid=OLD.entity_id;
 INSERT INTO catalog_title_grams(rowid,title) VALUES(NEW.entity_id,portico_fold_text(NEW.title)); END;
CREATE TRIGGER catalog_personal_sort_rows_title AFTER UPDATE OF sort_key ON catalog_browse_rows WHEN OLD.sort_key IS NOT NEW.sort_key BEGIN
 UPDATE catalog_personal_sort_rows SET sort_key=NEW.sort_key WHERE entity_id=NEW.entity_id; END;
