 PRIMARY KEY(library_id,kind,ordering,sort_value,entity_id)) WITHOUT ROWID, STRICT;
CREATE INDEX catalog_browse_blocks_full ON catalog_browse_blocks(library_id,kind,ordering) WHERE total>2048;
CREATE TRIGGER catalog_browse_blocks_title_join AFTER INSERT ON catalog_browse_rows BEGIN
 UPDATE catalog_browse_blocks SET total=total+1 WHERE (library_id,kind,ordering,sort_value,entity_id)=(SELECT library_id,kind,ordering,sort_value,entity_id FROM catalog_browse_blocks WHERE library_id=NEW.library_id AND kind=NEW.kind AND ordering=0 AND (sort_value<lower(NEW.sort_key) OR sort_value=lower(NEW.sort_key) AND entity_id<=NEW.entity_id) ORDER BY sort_value DESC,entity_id DESC LIMIT 1);
 INSERT INTO catalog_browse_blocks(library_id,kind,ordering,sort_value,entity_id,total) SELECT NEW.library_id,NEW.kind,0,lower(NEW.sort_key),NEW.entity_id,1
  WHERE NOT EXISTS(SELECT 1 FROM catalog_browse_blocks WHERE library_id=NEW.library_id AND kind=NEW.kind AND ordering=0 AND (sort_value<lower(NEW.sort_key) OR sort_value=lower(NEW.sort_key) AND entity_id<=NEW.entity_id));
 INSERT INTO catalog_browse_blocks(library_id,kind,ordering,sort_value,entity_id,total)
  SELECT b.library_id,b.kind,0,
   (SELECT seek_value FROM(SELECT * FROM(SELECT lower(r.sort_key) AS seek_value,r.entity_id AS seek_id FROM catalog_browse_rows r INDEXED BY catalog_browse_title WHERE r.library_id=b.library_id AND r.kind=b.kind AND r.sort_key COLLATE NOCASE=b.sort_value AND r.entity_id>=b.entity_id ORDER BY r.entity_id LIMIT 1025) UNION ALL SELECT * FROM(SELECT lower(r.sort_key) AS seek_value,r.entity_id AS seek_id FROM catalog_browse_rows r INDEXED BY catalog_browse_title WHERE r.library_id=b.library_id AND r.kind=b.kind AND r.sort_key COLLATE NOCASE>b.sort_value ORDER BY r.sort_key COLLATE NOCASE,r.entity_id LIMIT 1025)) ORDER BY seek_value,seek_id LIMIT 1 OFFSET 1024),
   (SELECT seek_id FROM(SELECT * FROM(SELECT lower(r.sort_key) AS seek_value,r.entity_id AS seek_id FROM catalog_browse_rows r INDEXED BY catalog_browse_title WHERE r.library_id=b.library_id AND r.kind=b.kind AND r.sort_key COLLATE NOCASE=b.sort_value AND r.entity_id>=b.entity_id ORDER BY r.entity_id LIMIT 1025) UNION ALL SELECT * FROM(SELECT lower(r.sort_key) AS seek_value,r.entity_id AS seek_id FROM catalog_browse_rows r INDEXED BY catalog_browse_title WHERE r.library_id=b.library_id AND r.kind=b.kind AND r.sort_key COLLATE NOCASE>b.sort_value ORDER BY r.sort_key COLLATE NOCASE,r.entity_id LIMIT 1025)) ORDER BY seek_value,seek_id LIMIT 1 OFFSET 1024),
   b.total-1024
  FROM catalog_browse_blocks b INDEXED BY catalog_browse_blocks_full WHERE b.library_id=NEW.library_id AND b.kind=NEW.kind AND b.ordering=0 AND b.total>2048;
 UPDATE catalog_browse_blocks SET total=1024 WHERE (library_id,kind,ordering,sort_value,entity_id)=(SELECT library_id,kind,ordering,sort_value,entity_id FROM catalog_browse_blocks INDEXED BY catalog_browse_blocks_full WHERE library_id=NEW.library_id AND kind=NEW.kind AND ordering=0 AND total>2048 LIMIT 1);
END;
