CREATE TABLE compact_visibility_blocks(
 class_id INTEGER NOT NULL,
 generation INTEGER NOT NULL,
 library_id INTEGER NOT NULL,
 kind INTEGER NOT NULL,
 ordering INTEGER NOT NULL CHECK(ordering BETWEEN 0 AND 5),
 sort_value ANY NOT NULL,
 entity_id INTEGER NOT NULL,
 total INTEGER NOT NULL CHECK(total>=0),
 PRIMARY KEY(class_id,generation,library_id,kind,ordering,sort_value,entity_id)) WITHOUT ROWID, STRICT;
CREATE INDEX compact_visibility_blocks_full ON compact_visibility_blocks(class_id,generation,library_id,kind,ordering) WHERE total>2048;
CREATE TRIGGER compact_visibility_blocks_title_join AFTER INSERT ON compact_visibility_rows BEGIN
 UPDATE compact_visibility_blocks SET total=total+1 WHERE (class_id,generation,library_id,kind,ordering,sort_value,entity_id)=(SELECT class_id,generation,library_id,kind,ordering,sort_value,entity_id FROM compact_visibility_blocks WHERE class_id=NEW.class_id AND generation=NEW.generation AND library_id=NEW.library_id AND kind=NEW.kind AND ordering=0 AND (sort_value<lower(NEW.sort_key) OR sort_value=lower(NEW.sort_key) AND entity_id<=NEW.entity_id) ORDER BY sort_value DESC,entity_id DESC LIMIT 1);
 INSERT INTO compact_visibility_blocks(class_id,generation,library_id,kind,ordering,sort_value,entity_id,total) SELECT NEW.class_id,NEW.generation,NEW.library_id,NEW.kind,0,lower(NEW.sort_key),NEW.entity_id,1
  WHERE NOT EXISTS(SELECT 1 FROM compact_visibility_blocks WHERE class_id=NEW.class_id AND generation=NEW.generation AND library_id=NEW.library_id AND kind=NEW.kind AND ordering=0 AND (sort_value<lower(NEW.sort_key) OR sort_value=lower(NEW.sort_key) AND entity_id<=NEW.entity_id));
 INSERT INTO compact_visibility_blocks(class_id,generation,library_id,kind,ordering,sort_value,entity_id,total)
  SELECT b.class_id,b.generation,b.library_id,b.kind,0,
   (SELECT seek_value FROM(SELECT * FROM(SELECT lower(r.sort_key) AS seek_value,r.entity_id AS seek_id FROM compact_visibility_rows r INDEXED BY compact_visibility_page WHERE r.class_id=b.class_id AND r.generation=b.generation AND r.library_id=b.library_id AND r.kind=b.kind AND r.sort_key COLLATE NOCASE=b.sort_value AND r.entity_id>=b.entity_id ORDER BY r.entity_id LIMIT 1025) UNION ALL SELECT * FROM(SELECT lower(r.sort_key) AS seek_value,r.entity_id AS seek_id FROM compact_visibility_rows r INDEXED BY compact_visibility_page WHERE r.class_id=b.class_id AND r.generation=b.generation AND r.library_id=b.library_id AND r.kind=b.kind AND r.sort_key COLLATE NOCASE>b.sort_value ORDER BY r.sort_key COLLATE NOCASE,r.entity_id LIMIT 1025)) ORDER BY seek_value,seek_id LIMIT 1 OFFSET 1024),
   (SELECT seek_id FROM(SELECT * FROM(SELECT lower(r.sort_key) AS seek_value,r.entity_id AS seek_id FROM compact_visibility_rows r INDEXED BY compact_visibility_page WHERE r.class_id=b.class_id AND r.generation=b.generation AND r.library_id=b.library_id AND r.kind=b.kind AND r.sort_key COLLATE NOCASE=b.sort_value AND r.entity_id>=b.entity_id ORDER BY r.entity_id LIMIT 1025) UNION ALL SELECT * FROM(SELECT lower(r.sort_key) AS seek_value,r.entity_id AS seek_id FROM compact_visibility_rows r INDEXED BY compact_visibility_page WHERE r.class_id=b.class_id AND r.generation=b.generation AND r.library_id=b.library_id AND r.kind=b.kind AND r.sort_key COLLATE NOCASE>b.sort_value ORDER BY r.sort_key COLLATE NOCASE,r.entity_id LIMIT 1025)) ORDER BY seek_value,seek_id LIMIT 1 OFFSET 1024),
   b.total-1024
  FROM compact_visibility_blocks b INDEXED BY compact_visibility_blocks_full WHERE b.class_id=NEW.class_id AND b.generation=NEW.generation AND b.library_id=NEW.library_id AND b.kind=NEW.kind AND b.ordering=0 AND b.total>2048;
 UPDATE compact_visibility_blocks SET total=1024 WHERE (class_id,generation,library_id,kind,ordering,sort_value,entity_id)=(SELECT class_id,generation,library_id,kind,ordering,sort_value,entity_id FROM compact_visibility_blocks INDEXED BY compact_visibility_blocks_full WHERE class_id=NEW.class_id AND generation=NEW.generation AND library_id=NEW.library_id AND kind=NEW.kind AND ordering=0 AND total>2048 LIMIT 1);
