 INSERT INTO inventory_policy_pending(library_id,revision) VALUES(NEW.library_id,NEW.revision)
 ON CONFLICT(library_id) DO UPDATE SET revision=excluded.revision;
END;
CREATE TRIGGER inventory_library_create AFTER INSERT ON libraries BEGIN
 INSERT INTO library_sources(id,library_id,name,configured_root,root) VALUES(NEW.id,NEW.id,NEW.name,NEW.root,NEW.root);
 INSERT INTO library_scan_policies(library_id,episode_thumbnail_mode) VALUES(NEW.id,CASE WHEN NEW.kind IN('tv','anime') THEN 'provider_then_made' ELSE 'off' END);
END;
CREATE TRIGGER inventory_source_configuration AFTER UPDATE OF name,root,configured_root,classification,follow_symlinks,interval_seconds,enabled,root_identity,identity_confirmed ON library_sources BEGIN
 UPDATE library_configuration SET revision=revision+1,metadata_revision=metadata_revision+1 WHERE library_id=NEW.library_id;
 UPDATE admin_revision SET revision=revision+1 WHERE id=1;
END;
CREATE TRIGGER inventory_source_add AFTER INSERT ON library_sources BEGIN
 UPDATE library_configuration SET revision=revision+1,metadata_revision=metadata_revision+1 WHERE library_id=NEW.library_id;
 UPDATE admin_revision SET revision=revision+1 WHERE id=1;
END;
CREATE TRIGGER inventory_policy_change AFTER UPDATE ON library_scan_policies BEGIN
 UPDATE library_configuration SET revision=revision+1,metadata_revision=metadata_revision+1 WHERE library_id=NEW.library_id;
 UPDATE admin_revision SET revision=revision+1 WHERE id=1;
END;
CREATE TRIGGER inventory_availability_source AFTER UPDATE OF health,enabled,incarnation,generation ON library_sources
 WHEN OLD.health IS NOT NEW.health OR OLD.enabled IS NOT NEW.enabled OR OLD.incarnation IS NOT NEW.incarnation OR OLD.generation IS NOT NEW.generation BEGIN
 UPDATE library_revisions SET revision=revision+1 WHERE library_id=NEW.library_id AND (OLD.enabled IS NOT NEW.enabled OR OLD.incarnation IS NOT NEW.incarnation OR OLD.generation IS NOT NEW.generation OR (OLD.health IN('root_changed','removing')) IS NOT (NEW.health IN('root_changed','removing')));
 UPDATE admin_revision SET revision=revision+1 WHERE id=1;
END;
CREATE TRIGGER inventory_availability_object AFTER UPDATE OF state,retired,root_incarnation,unsupported_reason ON inventory_objects
 WHEN OLD.state IS NOT NEW.state OR OLD.retired IS NOT NEW.retired OR OLD.root_incarnation IS NOT NEW.root_incarnation OR OLD.unsupported_reason IS NOT NEW.unsupported_reason BEGIN
 UPDATE library_revisions SET revision=revision+1 WHERE library_id=(SELECT library_id FROM library_sources WHERE id=NEW.source_id);
END;
CREATE TRIGGER job_observation_update AFTER UPDATE ON jobs BEGIN
 INSERT INTO job_observations(job_id,updated_at,finished_at) VALUES(NEW.id,strftime('%Y-%m-%dT%H:%M:%fZ','now'),CASE WHEN NEW.status IN('complete','complete_with_warnings','failed','cancelled') THEN strftime('%Y-%m-%dT%H:%M:%fZ','now') END)
 ON CONFLICT(job_id) DO UPDATE SET updated_at=excluded.updated_at,finished_at=COALESCE(job_observations.finished_at,excluded.finished_at);
END;
