 BEGIN UPDATE metadata_publication_heads SET metadata_revision=metadata_revision+1 WHERE item_id IN(NEW.entity_id);END;
CREATE TRIGGER metadata_publication_metadata_tags_DELETE AFTER DELETE ON metadata_tags
 BEGIN UPDATE metadata_publication_heads SET metadata_revision=metadata_revision+1 WHERE item_id IN(OLD.entity_id);END;
