 DELETE FROM topshelf_tokens WHERE authority='local' AND account_id=OLD.id;
 DELETE FROM identity_device_families WHERE device_id IN (SELECT id FROM identity_devices WHERE authority='local' AND account_id=OLD.id);
 DELETE FROM identity_devices WHERE authority='local' AND account_id=OLD.id;
END;
