CREATE TRIGGER direct_account_created AFTER INSERT ON accounts BEGIN
 INSERT INTO direct_memberships(account_id,role) VALUES(NEW.id,CASE WHEN EXISTS(SELECT 1 FROM direct_memberships WHERE role='owner') THEN 'member' ELSE 'owner' END);
 INSERT INTO direct_profiles(id,account_id,name,is_primary) VALUES(NEW.profile_id,NEW.id,NEW.username,1);
END;
CREATE TRIGGER authorization_family_revoked AFTER UPDATE OF revoked ON authorization_session_families
 WHEN NEW.revoked=1 AND OLD.revoked=0
 BEGIN
 UPDATE playback_sessions SET state='stopped' WHERE session_hash IN(SELECT token_hash FROM authorization_family_tokens WHERE family_id=NEW.id);
 DELETE FROM authorization_family_renewals WHERE family_id=NEW.id;
 DELETE FROM identity_refresh_credentials WHERE family_id=NEW.id;
 DELETE FROM identity_refresh_receipts WHERE family_id=NEW.id;
 END;
