 UPDATE mount_revision SET revision=revision+1 WHERE id=1; END;
CREATE TRIGGER mount_revision_delete AFTER DELETE ON managed_mounts BEGIN
 UPDATE mount_revision SET revision=revision+1 WHERE id=1; END;
