WHEN NEW.enabled=0 OR NEW.deleted!=0
BEGIN DELETE FROM live_source_dependencies WHERE source_id=NEW.source_id AND kind='rule' AND id=NEW.id; END;
CREATE TRIGGER live_logo_source_insert AFTER INSERT ON live_sources
 WHEN EXISTS(SELECT 1 FROM live_channel_logos WHERE generation_id=NEW.active_generation) BEGIN
 INSERT INTO live_logo_jobs(source_id,generation_id,state) VALUES(NEW.id,NEW.active_generation,'pending')
 ON CONFLICT(source_id) DO UPDATE SET generation_id=excluded.generation_id,state='pending',imported=0,skipped=0,last_channel='',next_attempt_ms=0;
END;
