 BEGIN
  DELETE FROM continue_show_dismissals WHERE profile_id=OLD.profile_id AND item_id=OLD.item_id;
 END;
CREATE TRIGGER authorization_revocation_metadata AFTER UPDATE OF revoked ON authorization_session_families
WHEN NEW.revoked=1 AND OLD.revoked=0 AND (NEW.revoked_reason='' OR NEW.revoked_at='') BEGIN
 UPDATE authorization_session_families SET
  revoked_reason=CASE WHEN NEW.revoked_reason='' THEN 'admin_revoke' ELSE NEW.revoked_reason END,
  revoked_at=CASE WHEN NEW.revoked_at='' THEN strftime('%Y-%m-%dT%H:%M:%SZ','now') ELSE NEW.revoked_at END
 WHERE id=NEW.id;
END;
