CREATE TRIGGER mb_song_link_update AFTER UPDATE ON mb_song_links BEGIN UPDATE mb_song_heads SET revision=revision+1 WHERE item_id IN(OLD.item_id,NEW.item_id);UPDATE library_revisions SET revision=revision+1 WHERE library_id IN(SELECT cl.library_id FROM catalog_entities ce JOIN catalog_libraries cl ON cl.id=ce.library_id WHERE ce.id IN(OLD.item_id,NEW.item_id));END;
CREATE TRIGGER mb_song_link_delete AFTER DELETE ON mb_song_links BEGIN UPDATE mb_song_heads SET revision=revision+1 WHERE item_id IN(OLD.item_id);UPDATE library_revisions SET revision=revision+1 WHERE library_id IN(SELECT cl.library_id FROM catalog_entities ce JOIN catalog_libraries cl ON cl.id=ce.library_id WHERE ce.id IN(OLD.item_id));END;
CREATE TRIGGER mb_album_link_insert AFTER INSERT ON mb_album_links BEGIN UPDATE mb_album_heads SET revision=revision+1 WHERE album_id IN(NEW.album_id);UPDATE library_revisions SET revision=revision+1 WHERE library_id IN(SELECT cl.library_id FROM catalog_entities ce JOIN catalog_libraries cl ON cl.id=ce.library_id WHERE ce.id IN(NEW.album_id));END;
CREATE TRIGGER mb_album_link_update AFTER UPDATE ON mb_album_links BEGIN UPDATE mb_album_heads SET revision=revision+1 WHERE album_id IN(OLD.album_id,NEW.album_id);UPDATE library_revisions SET revision=revision+1 WHERE library_id IN(SELECT cl.library_id FROM catalog_entities ce JOIN catalog_libraries cl ON cl.id=ce.library_id WHERE ce.id IN(OLD.album_id,NEW.album_id));END;
CREATE TRIGGER mb_album_link_delete AFTER DELETE ON mb_album_links BEGIN UPDATE mb_album_heads SET revision=revision+1 WHERE album_id IN(OLD.album_id);UPDATE library_revisions SET revision=revision+1 WHERE library_id IN(SELECT cl.library_id FROM catalog_entities ce JOIN catalog_libraries cl ON cl.id=ce.library_id WHERE ce.id IN(OLD.album_id));END;
CREATE TRIGGER mb_observed_source_changed AFTER UPDATE OF source_revision ON metadata_publication_heads WHEN OLD.source_revision IS NOT NEW.source_revision BEGIN
 UPDATE mb_album_heads SET revision=revision+1,membership_revision=membership_revision+1 WHERE album_id IN(SELECT album_id FROM catalog_songs WHERE entity_id IN(OLD.item_id,NEW.item_id));
 UPDATE mb_jobs SET status='pending',attempts=0,next_attempt='',error='',generation=generation+1,revision=revision+1,lease='',lease_until='' WHERE (kind='song' AND entity_id IN(SELECT NEW.item_id)) OR (kind='album' AND entity_id IN(SELECT album_id FROM catalog_songs WHERE entity_id IN(OLD.item_id,NEW.item_id)));END;
CREATE TRIGGER mb_library_scope_changed AFTER UPDATE OF root,kind ON libraries BEGIN
 UPDATE mb_album_heads SET revision=revision+1,membership_revision=membership_revision+1 WHERE album_id IN(SELECT ce.id FROM catalog_libraries cl JOIN catalog_entities ce ON ce.library_id=cl.id AND ce.kind=6 WHERE cl.library_id IN(OLD.id,NEW.id));
 UPDATE mb_jobs SET status='pending',attempts=0,next_attempt='',error='',generation=generation+1,revision=revision+1,lease='',lease_until='' WHERE entity_id IN(SELECT ce.id FROM catalog_libraries cl JOIN catalog_entities ce ON ce.library_id=cl.id AND ce.kind IN(6,7) WHERE cl.library_id IN(OLD.id,NEW.id));END;
CREATE TRIGGER tvdb_publication_library_scope AFTER UPDATE OF root,kind ON libraries WHEN OLD.root IS NOT NEW.root OR OLD.kind IS NOT NEW.kind
 BEGIN
UPDATE catalog_facet_source_state SET source_epoch=source_epoch+1 WHERE singleton=1;
 INSERT INTO catalog_upstream_sources(domain,source_id,token,flags) SELECT 43,id,library_id,64 FROM catalog_libraries WHERE library_id=OLD.id
 ON CONFLICT(domain,source_id) DO UPDATE SET token=excluded.token,flags=flags|excluded.flags,revision=revision+1,source_epoch=0,phase=0,has_after=0,after_id=0,after_aux=0,after_key='',active_id=NULL,active_key='',active_available=0,seen_inventory=0,inner_has=0,inner_id=0,inner_aux=0,inner_key='';
 INSERT INTO catalog_dirty(domain,entity_id,revision) SELECT 43,source_id,1 FROM catalog_upstream_sources WHERE domain=43 AND source_id=(SELECT id FROM catalog_libraries WHERE library_id=OLD.id)
 ON CONFLICT(domain,entity_id) DO UPDATE SET revision=revision+1;
UPDATE catalog_facet_source_state SET source_epoch=source_epoch+1 WHERE singleton=1;
 INSERT INTO catalog_upstream_sources(domain,source_id,token,flags) SELECT 43,id,library_id,64 FROM catalog_libraries WHERE library_id=NEW.id
 ON CONFLICT(domain,source_id) DO UPDATE SET token=excluded.token,flags=flags|excluded.flags,revision=revision+1,source_epoch=0,phase=0,has_after=0,after_id=0,after_aux=0,after_key='',active_id=NULL,active_key='',active_available=0,seen_inventory=0,inner_has=0,inner_id=0,inner_aux=0,inner_key='';
 INSERT INTO catalog_dirty(domain,entity_id,revision) SELECT 43,source_id,1 FROM catalog_upstream_sources WHERE domain=43 AND source_id=(SELECT id FROM catalog_libraries WHERE library_id=NEW.id)
 ON CONFLICT(domain,entity_id) DO UPDATE SET revision=revision+1;
END;
