 WHEN NOT EXISTS(SELECT 1 FROM catalog_assets a JOIN catalog_info_changes c ON c.asset_id=a.id AND c.asset_token=a.token WHERE a.token=NEW.asset_id AND c.slot=0 AND c.phase=2) BEGIN
