CREATE TABLE catalog_browse_availability_counts(library_id INTEGER NOT NULL,kind INTEGER NOT NULL,availability_state TEXT NOT NULL,rating_key TEXT NOT NULL,label_key TEXT NOT NULL,container INTEGER NOT NULL,total INTEGER NOT NULL,PRIMARY KEY(library_id,kind,availability_state,rating_key,label_key,container)) WITHOUT ROWID, STRICT;
CREATE TRIGGER catalog_browse_availability_counts_join AFTER INSERT ON catalog_browse_rows BEGIN INSERT INTO catalog_browse_availability_counts VALUES(NEW.library_id,NEW.kind,NEW.availability_state,'','',-1,1) ON CONFLICT(library_id,kind,availability_state,rating_key,label_key,container) DO UPDATE SET total=total+1; INSERT INTO catalog_browse_availability_counts(library_id,kind,availability_state,rating_key,label_key,container,total) VALUES(NEW.library_id,NEW.kind,NEW.availability_state,NEW.rating_key,NEW.label_key,(NEW.item_id IS NULL),1) ON CONFLICT(library_id,kind,availability_state,rating_key,label_key,container) DO UPDATE SET total=total+1; END;
CREATE TRIGGER catalog_browse_availability_counts_leave AFTER DELETE ON catalog_browse_rows BEGIN UPDATE catalog_browse_availability_counts SET total=total-1 WHERE library_id=OLD.library_id AND kind=OLD.kind AND availability_state=OLD.availability_state AND container=-1 AND rating_key='' AND label_key=''; DELETE FROM catalog_browse_availability_counts WHERE library_id=OLD.library_id AND kind=OLD.kind AND availability_state=OLD.availability_state AND container=-1 AND rating_key='' AND label_key='' AND total=0; UPDATE catalog_browse_availability_counts SET total=total-1 WHERE (library_id,kind,availability_state,rating_key,label_key,container)=(OLD.library_id,OLD.kind,OLD.availability_state,OLD.rating_key,OLD.label_key,(OLD.item_id IS NULL)); DELETE FROM catalog_browse_availability_counts WHERE (library_id,kind,availability_state,rating_key,label_key,container)=(OLD.library_id,OLD.kind,OLD.availability_state,OLD.rating_key,OLD.label_key,(OLD.item_id IS NULL)) AND total=0; END;
CREATE TRIGGER catalog_browse_availability_counts_move AFTER UPDATE OF library_id,kind,availability_state,rating_key,label_key,item_id ON catalog_browse_rows WHEN (OLD.library_id,OLD.kind,OLD.availability_state,OLD.rating_key,OLD.label_key,(OLD.item_id IS NULL)) IS NOT (NEW.library_id,NEW.kind,NEW.availability_state,NEW.rating_key,NEW.label_key,(NEW.item_id IS NULL)) BEGIN UPDATE catalog_browse_availability_counts SET total=total-1 WHERE (library_id,kind,availability_state,rating_key,label_key,container)=(OLD.library_id,OLD.kind,OLD.availability_state,OLD.rating_key,OLD.label_key,(OLD.item_id IS NULL)); DELETE FROM catalog_browse_availability_counts WHERE (library_id,kind,availability_state,rating_key,label_key,container)=(OLD.library_id,OLD.kind,OLD.availability_state,OLD.rating_key,OLD.label_key,(OLD.item_id IS NULL)) AND total=0; INSERT INTO catalog_browse_availability_counts(library_id,kind,availability_state,rating_key,label_key,container,total) VALUES(NEW.library_id,NEW.kind,NEW.availability_state,NEW.rating_key,NEW.label_key,(NEW.item_id IS NULL),1) ON CONFLICT(library_id,kind,availability_state,rating_key,label_key,container) DO UPDATE SET total=total+1; END;
CREATE TABLE catalog_browse_availability_counts_previous(generation INTEGER NOT NULL,present INTEGER NOT NULL,library_id INTEGER,kind INTEGER,availability_state TEXT,rating_key TEXT,label_key TEXT,container INTEGER,total INTEGER,PRIMARY KEY(generation,library_id,kind,availability_state,rating_key,label_key,container)) WITHOUT ROWID, STRICT;
CREATE VIEW catalog_browse_availability_counts_serving AS SELECT r.library_id,r.kind,r.availability_state,r.rating_key,r.label_key,r.container,r.total FROM catalog_browse_availability_counts r WHERE NOT EXISTS(SELECT 1 FROM catalog_generations g JOIN catalog_browse_availability_counts_previous p ON p.generation=g.generation WHERE g.singleton=1 AND g.retaining=1 AND (p.library_id,p.kind,p.availability_state,p.rating_key,p.label_key,p.container)=(r.library_id,r.kind,r.availability_state,r.rating_key,r.label_key,r.container))
 UNION ALL SELECT p.library_id,p.kind,p.availability_state,p.rating_key,p.label_key,p.container,p.total FROM catalog_browse_availability_counts_previous p WHERE p.generation=(SELECT generation FROM catalog_generations WHERE singleton=1 AND retaining=1) AND p.present=1;
CREATE TRIGGER catalog_browse_availability_counts_retain_insert BEFORE INSERT ON catalog_browse_availability_counts WHEN (SELECT retaining FROM catalog_generations WHERE singleton=1)=1 AND NOT EXISTS(SELECT 1 FROM catalog_browse_availability_counts r WHERE (r.library_id,r.kind,r.availability_state,r.rating_key,r.label_key,r.container)=(NEW.library_id,NEW.kind,NEW.availability_state,NEW.rating_key,NEW.label_key,NEW.container)) BEGIN INSERT INTO catalog_browse_availability_counts_previous(generation,present,library_id,kind,availability_state,rating_key,label_key,container,total) SELECT generation,0,NEW.library_id,NEW.kind,NEW.availability_state,NEW.rating_key,NEW.label_key,NEW.container,NEW.total FROM catalog_generations WHERE singleton=1 ON CONFLICT(generation,library_id,kind,availability_state,rating_key,label_key,container) DO NOTHING; END;
CREATE TRIGGER catalog_browse_availability_counts_retain_update BEFORE UPDATE ON catalog_browse_availability_counts WHEN (SELECT retaining FROM catalog_generations WHERE singleton=1)=1 BEGIN INSERT INTO catalog_browse_availability_counts_previous(generation,present,library_id,kind,availability_state,rating_key,label_key,container,total) SELECT generation,1,OLD.library_id,OLD.kind,OLD.availability_state,OLD.rating_key,OLD.label_key,OLD.container,OLD.total FROM catalog_generations WHERE singleton=1 ON CONFLICT(generation,library_id,kind,availability_state,rating_key,label_key,container) DO NOTHING; END;
CREATE TRIGGER catalog_browse_availability_counts_retain_delete BEFORE DELETE ON catalog_browse_availability_counts WHEN (SELECT retaining FROM catalog_generations WHERE singleton=1)=1 BEGIN INSERT INTO catalog_browse_availability_counts_previous(generation,present,library_id,kind,availability_state,rating_key,label_key,container,total) SELECT generation,1,OLD.library_id,OLD.kind,OLD.availability_state,OLD.rating_key,OLD.label_key,OLD.container,OLD.total FROM catalog_generations WHERE singleton=1 ON CONFLICT(generation,library_id,kind,availability_state,rating_key,label_key,container) DO NOTHING; END;
CREATE TABLE catalog_search_prefix_terms(id INTEGER PRIMARY KEY AUTOINCREMENT,prefix TEXT NOT NULL UNIQUE) STRICT;
CREATE TABLE catalog_search_prefix_rows(term_id INTEGER NOT NULL REFERENCES catalog_search_prefix_terms(id),entity_id INTEGER NOT NULL REFERENCES catalog_search_documents(entity_id) ON DELETE CASCADE,kind INTEGER NOT NULL,library_id INTEGER NOT NULL,tier INTEGER NOT NULL,container INTEGER NOT NULL,rating_key TEXT NOT NULL,label_key TEXT NOT NULL,PRIMARY KEY(term_id,kind,library_id,tier,entity_id)) WITHOUT ROWID, STRICT;
CREATE INDEX catalog_search_prefix_rows_entity ON catalog_search_prefix_rows(entity_id,term_id);
CREATE TABLE catalog_search_prefix_counts(term_id INTEGER NOT NULL,kind INTEGER NOT NULL,library_id INTEGER NOT NULL,container INTEGER NOT NULL,rating_key TEXT NOT NULL,label_key TEXT NOT NULL,total INTEGER NOT NULL,PRIMARY KEY(term_id,kind,library_id,container,rating_key,label_key)) WITHOUT ROWID, STRICT;
CREATE TRIGGER catalog_search_prefix_rows_join AFTER INSERT ON catalog_search_prefix_rows BEGIN
 INSERT INTO catalog_search_prefix_counts VALUES(NEW.term_id,NEW.kind,NEW.library_id,-1,'','',1) ON CONFLICT(term_id,kind,library_id,container,rating_key,label_key) DO UPDATE SET total=total+1;
 INSERT INTO catalog_search_prefix_counts VALUES(NEW.term_id,NEW.kind,NEW.library_id,NEW.container,NEW.rating_key,NEW.label_key,1) ON CONFLICT(term_id,kind,library_id,container,rating_key,label_key) DO UPDATE SET total=total+1;
END;
CREATE TRIGGER catalog_search_prefix_rows_leave AFTER DELETE ON catalog_search_prefix_rows BEGIN
 UPDATE catalog_search_prefix_counts SET total=total-1 WHERE term_id=OLD.term_id AND kind=OLD.kind AND library_id=OLD.library_id AND container=-1 AND rating_key='' AND label_key='';
 DELETE FROM catalog_search_prefix_counts WHERE term_id=OLD.term_id AND kind=OLD.kind AND library_id=OLD.library_id AND container=-1 AND rating_key='' AND label_key='' AND total=0;
 UPDATE catalog_search_prefix_counts SET total=total-1 WHERE (term_id,kind,library_id,container,rating_key,label_key)=(OLD.term_id,OLD.kind,OLD.library_id,OLD.container,OLD.rating_key,OLD.label_key);
 DELETE FROM catalog_search_prefix_counts WHERE (term_id,kind,library_id,container,rating_key,label_key)=(OLD.term_id,OLD.kind,OLD.library_id,OLD.container,OLD.rating_key,OLD.label_key) AND total=0;
END;
CREATE TABLE catalog_search_prefix_rows_next(term_id INTEGER NOT NULL REFERENCES catalog_search_prefix_terms(id),entity_id INTEGER NOT NULL REFERENCES catalog_search_documents_next(entity_id) ON DELETE CASCADE,kind INTEGER NOT NULL,library_id INTEGER NOT NULL,tier INTEGER NOT NULL,container INTEGER NOT NULL,rating_key TEXT NOT NULL,label_key TEXT NOT NULL,PRIMARY KEY(term_id,kind,library_id,tier,entity_id)) WITHOUT ROWID, STRICT;
CREATE INDEX catalog_search_prefix_rows_next_entity ON catalog_search_prefix_rows_next(entity_id,term_id);
CREATE TABLE catalog_search_prefix_counts_next(term_id INTEGER NOT NULL,kind INTEGER NOT NULL,library_id INTEGER NOT NULL,container INTEGER NOT NULL,rating_key TEXT NOT NULL,label_key TEXT NOT NULL,total INTEGER NOT NULL,PRIMARY KEY(term_id,kind,library_id,container,rating_key,label_key)) WITHOUT ROWID, STRICT;
CREATE TRIGGER catalog_search_prefix_rows_next_join AFTER INSERT ON catalog_search_prefix_rows_next BEGIN
 INSERT INTO catalog_search_prefix_counts_next VALUES(NEW.term_id,NEW.kind,NEW.library_id,-1,'','',1) ON CONFLICT(term_id,kind,library_id,container,rating_key,label_key) DO UPDATE SET total=total+1;
 INSERT INTO catalog_search_prefix_counts_next VALUES(NEW.term_id,NEW.kind,NEW.library_id,NEW.container,NEW.rating_key,NEW.label_key,1) ON CONFLICT(term_id,kind,library_id,container,rating_key,label_key) DO UPDATE SET total=total+1;
END;
