 DELETE FROM catalog_search_prefix_counts_next WHERE (term_id,kind,library_id,container,rating_key,label_key)=(OLD.term_id,OLD.kind,OLD.library_id,OLD.container,OLD.rating_key,OLD.label_key) AND total=0;
