 UPDATE catalog_browse_blocks SET total=total+1 WHERE (library_id,kind,ordering,sort_value,entity_id)=(SELECT library_id,kind,ordering,sort_value,entity_id FROM catalog_browse_blocks WHERE library_id=NEW.library_id AND kind=NEW.kind AND ordering=5 AND (sort_value<NEW.random_key OR sort_value=NEW.random_key AND entity_id<=NEW.entity_id) ORDER BY sort_value DESC,entity_id DESC LIMIT 1);
 INSERT INTO catalog_browse_blocks(library_id,kind,ordering,sort_value,entity_id,total) SELECT NEW.library_id,NEW.kind,5,NEW.random_key,NEW.entity_id,1
  WHERE NOT EXISTS(SELECT 1 FROM catalog_browse_blocks WHERE library_id=NEW.library_id AND kind=NEW.kind AND ordering=5 AND (sort_value<NEW.random_key OR sort_value=NEW.random_key AND entity_id<=NEW.entity_id));
 INSERT INTO catalog_browse_blocks(library_id,kind,ordering,sort_value,entity_id,total)
  SELECT b.library_id,b.kind,5,
   (SELECT seek_value FROM(SELECT * FROM(SELECT r.random_key AS seek_value,r.entity_id AS seek_id FROM catalog_browse_rows r INDEXED BY catalog_browse_random_key WHERE r.library_id=b.library_id AND r.kind=b.kind AND r.random_key=b.sort_value AND r.entity_id>=b.entity_id ORDER BY r.entity_id LIMIT 1025) UNION ALL SELECT * FROM(SELECT r.random_key AS seek_value,r.entity_id AS seek_id FROM catalog_browse_rows r INDEXED BY catalog_browse_random_key WHERE r.library_id=b.library_id AND r.kind=b.kind AND r.random_key>b.sort_value ORDER BY r.random_key,r.entity_id LIMIT 1025)) ORDER BY seek_value,seek_id LIMIT 1 OFFSET 1024),
   (SELECT seek_id FROM(SELECT * FROM(SELECT r.random_key AS seek_value,r.entity_id AS seek_id FROM catalog_browse_rows r INDEXED BY catalog_browse_random_key WHERE r.library_id=b.library_id AND r.kind=b.kind AND r.random_key=b.sort_value AND r.entity_id>=b.entity_id ORDER BY r.entity_id LIMIT 1025) UNION ALL SELECT * FROM(SELECT r.random_key AS seek_value,r.entity_id AS seek_id FROM catalog_browse_rows r INDEXED BY catalog_browse_random_key WHERE r.library_id=b.library_id AND r.kind=b.kind AND r.random_key>b.sort_value ORDER BY r.random_key,r.entity_id LIMIT 1025)) ORDER BY seek_value,seek_id LIMIT 1 OFFSET 1024),
   b.total-1024
  FROM catalog_browse_blocks b INDEXED BY catalog_browse_blocks_full WHERE b.library_id=NEW.library_id AND b.kind=NEW.kind AND b.ordering=5 AND b.total>2048;
 UPDATE catalog_browse_blocks SET total=1024 WHERE (library_id,kind,ordering,sort_value,entity_id)=(SELECT library_id,kind,ordering,sort_value,entity_id FROM catalog_browse_blocks INDEXED BY catalog_browse_blocks_full WHERE library_id=NEW.library_id AND kind=NEW.kind AND ordering=5 AND total>2048 LIMIT 1);
