 UPDATE catalog_browse_blocks SET total=total-1 WHERE (library_id,kind,ordering,sort_value,entity_id)=(SELECT library_id,kind,ordering,sort_value,entity_id FROM catalog_browse_blocks WHERE library_id=OLD.library_id AND kind=OLD.kind AND ordering=14 AND (sort_value<OLD.resolution_key OR sort_value=OLD.resolution_key AND entity_id<=OLD.entity_id) ORDER BY sort_value DESC,entity_id DESC LIMIT 1);
 INSERT INTO catalog_browse_blocks(library_id,kind,ordering,sort_value,entity_id,total)
  SELECT b.library_id,b.kind,14,(SELECT seek_value FROM(SELECT * FROM(SELECT r.resolution_key AS seek_value,r.entity_id AS seek_id FROM catalog_browse_rows r INDEXED BY catalog_browse_resolution_key WHERE r.library_id=OLD.library_id AND r.kind=OLD.kind AND r.resolution_key=OLD.resolution_key AND r.entity_id>OLD.entity_id ORDER BY r.entity_id LIMIT 1) UNION ALL SELECT * FROM(SELECT r.resolution_key AS seek_value,r.entity_id AS seek_id FROM catalog_browse_rows r INDEXED BY catalog_browse_resolution_key WHERE r.library_id=OLD.library_id AND r.kind=OLD.kind AND r.resolution_key>OLD.resolution_key ORDER BY r.resolution_key,r.entity_id LIMIT 1)) ORDER BY seek_value,seek_id LIMIT 1 OFFSET 0),(SELECT seek_id FROM(SELECT * FROM(SELECT r.resolution_key AS seek_value,r.entity_id AS seek_id FROM catalog_browse_rows r INDEXED BY catalog_browse_resolution_key WHERE r.library_id=OLD.library_id AND r.kind=OLD.kind AND r.resolution_key=OLD.resolution_key AND r.entity_id>OLD.entity_id ORDER BY r.entity_id LIMIT 1) UNION ALL SELECT * FROM(SELECT r.resolution_key AS seek_value,r.entity_id AS seek_id FROM catalog_browse_rows r INDEXED BY catalog_browse_resolution_key WHERE r.library_id=OLD.library_id AND r.kind=OLD.kind AND r.resolution_key>OLD.resolution_key ORDER BY r.resolution_key,r.entity_id LIMIT 1)) ORDER BY seek_value,seek_id LIMIT 1 OFFSET 0),b.total FROM catalog_browse_blocks b
  WHERE b.library_id=OLD.library_id AND b.kind=OLD.kind AND b.ordering=14 AND b.sort_value=OLD.resolution_key AND b.entity_id=OLD.entity_id AND b.total>0
   AND EXISTS(SELECT 1 FROM(SELECT * FROM(SELECT r.resolution_key AS seek_value,r.entity_id AS seek_id FROM catalog_browse_rows r INDEXED BY catalog_browse_resolution_key WHERE r.library_id=OLD.library_id AND r.kind=OLD.kind AND r.resolution_key=OLD.resolution_key AND r.entity_id>OLD.entity_id ORDER BY r.entity_id LIMIT 1) UNION ALL SELECT * FROM(SELECT r.resolution_key AS seek_value,r.entity_id AS seek_id FROM catalog_browse_rows r INDEXED BY catalog_browse_resolution_key WHERE r.library_id=OLD.library_id AND r.kind=OLD.kind AND r.resolution_key>OLD.resolution_key ORDER BY r.resolution_key,r.entity_id LIMIT 1)) ORDER BY seek_value,seek_id LIMIT 1 OFFSET 0)
  ON CONFLICT(library_id,kind,ordering,sort_value,entity_id) DO UPDATE SET total=total+excluded.total;
 DELETE FROM catalog_browse_blocks WHERE library_id=OLD.library_id AND kind=OLD.kind AND ordering=14 AND sort_value=OLD.resolution_key AND entity_id=OLD.entity_id;
 UPDATE catalog_browse_blocks SET total=total+1 WHERE (library_id,kind,ordering,sort_value,entity_id)=(SELECT library_id,kind,ordering,sort_value,entity_id FROM catalog_browse_blocks WHERE library_id=NEW.library_id AND kind=NEW.kind AND ordering=14 AND (sort_value<NEW.resolution_key OR sort_value=NEW.resolution_key AND entity_id<=NEW.entity_id) ORDER BY sort_value DESC,entity_id DESC LIMIT 1);
 INSERT INTO catalog_browse_blocks(library_id,kind,ordering,sort_value,entity_id,total) SELECT NEW.library_id,NEW.kind,14,NEW.resolution_key,NEW.entity_id,1
  WHERE NOT EXISTS(SELECT 1 FROM catalog_browse_blocks WHERE library_id=NEW.library_id AND kind=NEW.kind AND ordering=14 AND (sort_value<NEW.resolution_key OR sort_value=NEW.resolution_key AND entity_id<=NEW.entity_id));
 INSERT INTO catalog_browse_blocks(library_id,kind,ordering,sort_value,entity_id,total)
  SELECT b.library_id,b.kind,14,
   (SELECT seek_value FROM(SELECT * FROM(SELECT r.resolution_key AS seek_value,r.entity_id AS seek_id FROM catalog_browse_rows r INDEXED BY catalog_browse_resolution_key WHERE r.library_id=b.library_id AND r.kind=b.kind AND r.resolution_key=b.sort_value AND r.entity_id>=b.entity_id ORDER BY r.entity_id LIMIT 1025) UNION ALL SELECT * FROM(SELECT r.resolution_key AS seek_value,r.entity_id AS seek_id FROM catalog_browse_rows r INDEXED BY catalog_browse_resolution_key WHERE r.library_id=b.library_id AND r.kind=b.kind AND r.resolution_key>b.sort_value ORDER BY r.resolution_key,r.entity_id LIMIT 1025)) ORDER BY seek_value,seek_id LIMIT 1 OFFSET 1024),
   (SELECT seek_id FROM(SELECT * FROM(SELECT r.resolution_key AS seek_value,r.entity_id AS seek_id FROM catalog_browse_rows r INDEXED BY catalog_browse_resolution_key WHERE r.library_id=b.library_id AND r.kind=b.kind AND r.resolution_key=b.sort_value AND r.entity_id>=b.entity_id ORDER BY r.entity_id LIMIT 1025) UNION ALL SELECT * FROM(SELECT r.resolution_key AS seek_value,r.entity_id AS seek_id FROM catalog_browse_rows r INDEXED BY catalog_browse_resolution_key WHERE r.library_id=b.library_id AND r.kind=b.kind AND r.resolution_key>b.sort_value ORDER BY r.resolution_key,r.entity_id LIMIT 1025)) ORDER BY seek_value,seek_id LIMIT 1 OFFSET 1024),
   b.total-1024
  FROM catalog_browse_blocks b INDEXED BY catalog_browse_blocks_full WHERE b.library_id=NEW.library_id AND b.kind=NEW.kind AND b.ordering=14 AND b.total>2048;
 UPDATE catalog_browse_blocks SET total=1024 WHERE (library_id,kind,ordering,sort_value,entity_id)=(SELECT library_id,kind,ordering,sort_value,entity_id FROM catalog_browse_blocks INDEXED BY catalog_browse_blocks_full WHERE library_id=NEW.library_id AND kind=NEW.kind AND ordering=14 AND total>2048 LIMIT 1);
END;
CREATE TRIGGER compact_visibility_blocks_random_join AFTER INSERT ON compact_visibility_rows BEGIN
 UPDATE compact_visibility_blocks SET total=total+1 WHERE (class_id,generation,library_id,kind,ordering,sort_value,entity_id)=(SELECT class_id,generation,library_id,kind,ordering,sort_value,entity_id FROM compact_visibility_blocks WHERE class_id=NEW.class_id AND generation=NEW.generation AND library_id=NEW.library_id AND kind=NEW.kind AND ordering=5 AND (sort_value<NEW.random_key OR sort_value=NEW.random_key AND entity_id<=NEW.entity_id) ORDER BY sort_value DESC,entity_id DESC LIMIT 1);
 INSERT INTO compact_visibility_blocks(class_id,generation,library_id,kind,ordering,sort_value,entity_id,total) SELECT NEW.class_id,NEW.generation,NEW.library_id,NEW.kind,5,NEW.random_key,NEW.entity_id,1
  WHERE NOT EXISTS(SELECT 1 FROM compact_visibility_blocks WHERE class_id=NEW.class_id AND generation=NEW.generation AND library_id=NEW.library_id AND kind=NEW.kind AND ordering=5 AND (sort_value<NEW.random_key OR sort_value=NEW.random_key AND entity_id<=NEW.entity_id));
 INSERT INTO compact_visibility_blocks(class_id,generation,library_id,kind,ordering,sort_value,entity_id,total)
  SELECT b.class_id,b.generation,b.library_id,b.kind,5,
   (SELECT seek_value FROM(SELECT * FROM(SELECT r.random_key AS seek_value,r.entity_id AS seek_id FROM compact_visibility_rows r INDEXED BY compact_visibility_random WHERE r.class_id=b.class_id AND r.generation=b.generation AND r.library_id=b.library_id AND r.kind=b.kind AND r.random_key=b.sort_value AND r.entity_id>=b.entity_id ORDER BY r.entity_id LIMIT 1025) UNION ALL SELECT * FROM(SELECT r.random_key AS seek_value,r.entity_id AS seek_id FROM compact_visibility_rows r INDEXED BY compact_visibility_random WHERE r.class_id=b.class_id AND r.generation=b.generation AND r.library_id=b.library_id AND r.kind=b.kind AND r.random_key>b.sort_value ORDER BY r.random_key,r.entity_id LIMIT 1025)) ORDER BY seek_value,seek_id LIMIT 1 OFFSET 1024),
   (SELECT seek_id FROM(SELECT * FROM(SELECT r.random_key AS seek_value,r.entity_id AS seek_id FROM compact_visibility_rows r INDEXED BY compact_visibility_random WHERE r.class_id=b.class_id AND r.generation=b.generation AND r.library_id=b.library_id AND r.kind=b.kind AND r.random_key=b.sort_value AND r.entity_id>=b.entity_id ORDER BY r.entity_id LIMIT 1025) UNION ALL SELECT * FROM(SELECT r.random_key AS seek_value,r.entity_id AS seek_id FROM compact_visibility_rows r INDEXED BY compact_visibility_random WHERE r.class_id=b.class_id AND r.generation=b.generation AND r.library_id=b.library_id AND r.kind=b.kind AND r.random_key>b.sort_value ORDER BY r.random_key,r.entity_id LIMIT 1025)) ORDER BY seek_value,seek_id LIMIT 1 OFFSET 1024),
   b.total-1024
  FROM compact_visibility_blocks b INDEXED BY compact_visibility_blocks_full WHERE b.class_id=NEW.class_id AND b.generation=NEW.generation AND b.library_id=NEW.library_id AND b.kind=NEW.kind AND b.ordering=5 AND b.total>2048;
 UPDATE compact_visibility_blocks SET total=1024 WHERE (class_id,generation,library_id,kind,ordering,sort_value,entity_id)=(SELECT class_id,generation,library_id,kind,ordering,sort_value,entity_id FROM compact_visibility_blocks INDEXED BY compact_visibility_blocks_full WHERE class_id=NEW.class_id AND generation=NEW.generation AND library_id=NEW.library_id AND kind=NEW.kind AND ordering=5 AND total>2048 LIMIT 1);
END;
