 PRIMARY KEY(collection_id,item_id)) WITHOUT ROWID, STRICT;
CREATE INDEX catalog_automatic_member_overrides_item ON catalog_automatic_member_overrides(item_id);
CREATE TRIGGER catalog_automatic_member_insert AFTER INSERT ON catalog_automatic_members BEGIN
 INSERT INTO catalog_automatic_collections(library_id,provider,provider_id,name) VALUES(NEW.library_id,NEW.provider,NEW.provider_id,NEW.name)
 ON CONFLICT(library_id,provider,provider_id) DO UPDATE SET name=excluded.name,dirty=1;
END;
CREATE TRIGGER catalog_automatic_member_delete AFTER DELETE ON catalog_automatic_members BEGIN
 UPDATE catalog_automatic_collections SET dirty=1 WHERE library_id=OLD.library_id AND provider=OLD.provider AND provider_id=OLD.provider_id;
END;
CREATE TRIGGER catalog_automatic_fields_insert AFTER INSERT ON screen_metadata_fields WHEN NEW.field IN('relations','collectionName') AND NEW.target_kind='item' BEGIN
DELETE FROM catalog_automatic_members WHERE item_id=NEW.target_id;
 INSERT INTO catalog_automatic_members(item_id,library_id,provider,provider_id,name)
 SELECT e.id,e.library_id,json_extract(j.value,'$.target.provider'),json_extract(j.value,'$.target.id'),json_extract(j.value,'$.name')
 FROM catalog_entities e JOIN screen_metadata_fields f ON f.target_id=e.id AND f.target_kind='item' AND f.field='relations',json_each(f.value) j
 WHERE e.id=NEW.target_id AND e.kind=1 AND json_valid(f.value) AND json_extract(j.value,'$.kind')='collection'
 AND COALESCE(json_extract(j.value,'$.target.provider'),'')<>'' AND COALESCE(json_extract(j.value,'$.target.id'),'')<>'' AND COALESCE(json_extract(j.value,'$.name'),'')<>''
 AND NOT EXISTS(SELECT 1 FROM screen_metadata_fields n WHERE n.target_kind='item' AND n.target_id=e.id AND n.field='collectionName' AND json_valid(n.value) AND trim(json_extract(n.value,'$'))<>'')
 ON CONFLICT DO NOTHING;
 INSERT INTO catalog_automatic_members(item_id,library_id,provider,provider_id,name)
 SELECT e.id,e.library_id,'nfo',lower(trim(json_extract(f.value,'$'))),trim(json_extract(f.value,'$')) FROM catalog_entities e JOIN screen_metadata_fields f ON f.target_id=e.id AND f.target_kind='item' AND f.field='collectionName'
 WHERE e.id=NEW.target_id AND e.kind=1 AND json_valid(f.value) AND trim(json_extract(f.value,'$'))<>'' ON CONFLICT DO NOTHING;
END;
CREATE TRIGGER catalog_automatic_fields_update AFTER UPDATE ON screen_metadata_fields WHEN NEW.field IN('relations','collectionName') AND NEW.target_kind='item' BEGIN
DELETE FROM catalog_automatic_members WHERE item_id=NEW.target_id;
 INSERT INTO catalog_automatic_members(item_id,library_id,provider,provider_id,name)
 SELECT e.id,e.library_id,json_extract(j.value,'$.target.provider'),json_extract(j.value,'$.target.id'),json_extract(j.value,'$.name')
 FROM catalog_entities e JOIN screen_metadata_fields f ON f.target_id=e.id AND f.target_kind='item' AND f.field='relations',json_each(f.value) j
 WHERE e.id=NEW.target_id AND e.kind=1 AND json_valid(f.value) AND json_extract(j.value,'$.kind')='collection'
 AND COALESCE(json_extract(j.value,'$.target.provider'),'')<>'' AND COALESCE(json_extract(j.value,'$.target.id'),'')<>'' AND COALESCE(json_extract(j.value,'$.name'),'')<>''
 AND NOT EXISTS(SELECT 1 FROM screen_metadata_fields n WHERE n.target_kind='item' AND n.target_id=e.id AND n.field='collectionName' AND json_valid(n.value) AND trim(json_extract(n.value,'$'))<>'')
 ON CONFLICT DO NOTHING;
 INSERT INTO catalog_automatic_members(item_id,library_id,provider,provider_id,name)
 SELECT e.id,e.library_id,'nfo',lower(trim(json_extract(f.value,'$'))),trim(json_extract(f.value,'$')) FROM catalog_entities e JOIN screen_metadata_fields f ON f.target_id=e.id AND f.target_kind='item' AND f.field='collectionName'
 WHERE e.id=NEW.target_id AND e.kind=1 AND json_valid(f.value) AND trim(json_extract(f.value,'$'))<>'' ON CONFLICT DO NOTHING;
END;
CREATE TRIGGER catalog_automatic_fields_delete AFTER DELETE ON screen_metadata_fields WHEN OLD.field IN('relations','collectionName') AND OLD.target_kind='item' BEGIN
DELETE FROM catalog_automatic_members WHERE item_id=OLD.target_id;
 INSERT INTO catalog_automatic_members(item_id,library_id,provider,provider_id,name)
 SELECT e.id,e.library_id,json_extract(j.value,'$.target.provider'),json_extract(j.value,'$.target.id'),json_extract(j.value,'$.name')
 FROM catalog_entities e JOIN screen_metadata_fields f ON f.target_id=e.id AND f.target_kind='item' AND f.field='relations',json_each(f.value) j
 WHERE e.id=OLD.target_id AND e.kind=1 AND json_valid(f.value) AND json_extract(j.value,'$.kind')='collection'
 AND COALESCE(json_extract(j.value,'$.target.provider'),'')<>'' AND COALESCE(json_extract(j.value,'$.target.id'),'')<>'' AND COALESCE(json_extract(j.value,'$.name'),'')<>''
 AND NOT EXISTS(SELECT 1 FROM screen_metadata_fields n WHERE n.target_kind='item' AND n.target_id=e.id AND n.field='collectionName' AND json_valid(n.value) AND trim(json_extract(n.value,'$'))<>'')
 ON CONFLICT DO NOTHING;
 INSERT INTO catalog_automatic_members(item_id,library_id,provider,provider_id,name)
 SELECT e.id,e.library_id,'nfo',lower(trim(json_extract(f.value,'$'))),trim(json_extract(f.value,'$')) FROM catalog_entities e JOIN screen_metadata_fields f ON f.target_id=e.id AND f.target_kind='item' AND f.field='collectionName'
 WHERE e.id=OLD.target_id AND e.kind=1 AND json_valid(f.value) AND trim(json_extract(f.value,'$'))<>'' ON CONFLICT DO NOTHING;
END;
CREATE TABLE catalog_title_tombstones(
 public_id TEXT PRIMARY KEY,library_id TEXT NOT NULL,title TEXT NOT NULL,kind INTEGER NOT NULL,
 poster_url TEXT NOT NULL,backdrop_url TEXT NOT NULL,recording INTEGER NOT NULL,
 removed_at TEXT NOT NULL,expires_at TEXT NOT NULL) STRICT;
CREATE INDEX catalog_title_tombstones_expiry ON catalog_title_tombstones(expires_at);
CREATE TABLE catalog_title_tombstone_viewers(
 public_id TEXT NOT NULL REFERENCES catalog_title_tombstones(public_id) ON DELETE CASCADE,
 profile_id TEXT NOT NULL,activity_at TEXT NOT NULL,continuing INTEGER NOT NULL CHECK(continuing IN(0,1)),PRIMARY KEY(public_id,profile_id)) WITHOUT ROWID, STRICT;
CREATE TABLE catalog_title_tombstone_attributes(
 public_id TEXT NOT NULL REFERENCES catalog_title_tombstones(public_id) ON DELETE CASCADE,
 field_id INTEGER NOT NULL,value_key TEXT NOT NULL,source_value TEXT NOT NULL,
 PRIMARY KEY(public_id,field_id,value_key)) WITHOUT ROWID, STRICT;
CREATE TRIGGER catalog_title_removed BEFORE DELETE ON catalog_entities WHEN OLD.kind IN(1,4,7,9) BEGIN
 INSERT INTO catalog_title_tombstones(public_id,library_id,title,kind,poster_url,backdrop_url,recording,removed_at,expires_at)
 VALUES(pid(OLD.public_id),COALESCE((SELECT library_id FROM catalog_libraries WHERE id=OLD.library_id),''),OLD.title,OLD.kind,
 COALESCE((SELECT poster_url FROM catalog_item_details WHERE entity_id=OLD.id),''),COALESCE((SELECT backdrop_url FROM catalog_item_details WHERE entity_id=OLD.id),''),
 EXISTS(SELECT 1 FROM dvr_catalog_provenance WHERE item_id=OLD.id),strftime('%Y-%m-%dT%H:%M:%fZ','now'),strftime('%Y-%m-%dT%H:%M:%fZ','now','+30 days'))
 ON CONFLICT(public_id) DO NOTHING;
 INSERT OR IGNORE INTO catalog_title_tombstone_viewers SELECT pid(OLD.public_id),a.profile_id,a.updated_at,a.state<>'ended' AND p.position>0 AND p.completed=0 FROM progress_activity a JOIN progress p ON p.profile_id=a.profile_id AND p.item_id=a.item_id WHERE a.item_id=OLD.id;
 INSERT OR IGNORE INTO catalog_title_tombstone_viewers SELECT pid(OLD.public_id),profile_id,updated_at,0 FROM personal_history WHERE item_id=OLD.id;
 INSERT OR IGNORE INTO catalog_title_tombstone_viewers SELECT pid(OLD.public_id),profile_id,COALESCE(last_played_at,''),0 FROM personal_items WHERE item_id=OLD.id AND (watchlisted=1 OR favorite=1);
 INSERT OR IGNORE INTO catalog_title_tombstone_attributes
 SELECT pid(OLD.public_id),term.field_id,term.value_key,edge.source_value FROM catalog_item_attribute_edges edge JOIN catalog_attribute_terms term ON term.id=edge.term_id WHERE edge.item_id=OLD.id AND term.field_id IN(1,2,3);
END;
CREATE TABLE catalog_removed_title_revisions(profile_id TEXT PRIMARY KEY,revision INTEGER NOT NULL) STRICT;
CREATE TRIGGER catalog_removed_title_reference_insert AFTER INSERT ON catalog_title_tombstone_viewers BEGIN
 INSERT INTO catalog_removed_title_revisions VALUES(NEW.profile_id,1) ON CONFLICT(profile_id) DO UPDATE SET revision=revision+1;
END;
CREATE TRIGGER catalog_removed_title_reference_update AFTER UPDATE ON catalog_title_tombstone_viewers BEGIN
 INSERT INTO catalog_removed_title_revisions VALUES(NEW.profile_id,1) ON CONFLICT(profile_id) DO UPDATE SET revision=revision+1;
END;
CREATE TRIGGER catalog_removed_title_reference_delete AFTER DELETE ON catalog_title_tombstone_viewers BEGIN
 INSERT INTO catalog_removed_title_revisions VALUES(OLD.profile_id,1) ON CONFLICT(profile_id) DO UPDATE SET revision=revision+1;
END;
CREATE TABLE live_reminders(id TEXT PRIMARY KEY,owner_key TEXT NOT NULL,kind TEXT NOT NULL CHECK(kind IN('live-source','library-channel')),source_id TEXT NOT NULL,channel_id TEXT NOT NULL,generation_id TEXT NOT NULL,programme_id TEXT NOT NULL,revision INTEGER NOT NULL,start_utc TEXT NOT NULL) STRICT;
CREATE INDEX live_reminders_owner ON live_reminders(owner_key,id);
CREATE TRIGGER live_reminders_bound BEFORE INSERT ON live_reminders WHEN (SELECT count(*) FROM live_reminders WHERE owner_key=NEW.owner_key)>=1000 AND NOT EXISTS(SELECT 1 FROM live_reminders WHERE id=NEW.id) BEGIN SELECT RAISE(ABORT,'This profile has reached its reminder limit.'); END;
CREATE TABLE dvr_programme_images(recording_id TEXT PRIMARY KEY REFERENCES dvr_recordings(id) ON DELETE CASCADE,url TEXT NOT NULL REFERENCES live_programme_images(url)) STRICT;
CREATE TRIGGER dvr_retain_programme_image AFTER INSERT ON dvr_recordings BEGIN
 INSERT OR IGNORE INTO dvr_programme_images SELECT NEW.id,img.url FROM live_programme_icons i JOIN live_programme_images img ON img.url=i.url WHERE i.generation_id=NEW.guide_generation AND i.programme_id=NEW.programme_id;
END;
CREATE TRIGGER dvr_refresh_programme_image AFTER UPDATE OF guide_generation,programme_json ON dvr_recordings WHEN NEW.state NOT IN('deleted','pending-delete') BEGIN
 INSERT OR IGNORE INTO dvr_programme_images SELECT NEW.id,img.url FROM live_programme_icons i JOIN live_programme_images img ON img.url=i.url WHERE i.generation_id=NEW.guide_generation AND i.programme_id=NEW.programme_id;
END;
CREATE TRIGGER dvr_retain_late_programme_image AFTER INSERT ON live_programme_images BEGIN
 INSERT OR IGNORE INTO dvr_programme_images SELECT r.id,NEW.url FROM dvr_recordings r JOIN live_programme_icons i ON i.generation_id=r.guide_generation AND i.programme_id=r.programme_id WHERE i.url=NEW.url AND r.state NOT IN('deleted','pending-delete');
END;
CREATE TRIGGER dvr_release_programme_image AFTER UPDATE OF state ON dvr_recordings WHEN NEW.state='deleted' BEGIN DELETE FROM dvr_programme_images WHERE recording_id=NEW.id; END;
CREATE TRIGGER dvr_preserve_programme_image BEFORE DELETE ON live_programme_images WHEN EXISTS(SELECT 1 FROM dvr_programme_images WHERE url=OLD.url) BEGIN SELECT RAISE(IGNORE); END;
CREATE INDEX dvr_programme_images_url ON dvr_programme_images(url);
CREATE INDEX identity_devices_people_name ON identity_devices(name,id);
CREATE INDEX identity_devices_people_first_seen ON identity_devices(first_seen DESC,id DESC);
CREATE TRIGGER screen_metadata_attention_browse_insert AFTER INSERT ON screen_metadata_attention WHEN NEW.retired=0 AND NEW.reason NOT IN('pending','searching','pending_search','pending_episodes','pending_children','pending_apply') BEGIN
 UPDATE library_revisions SET revision=revision+1,order_revision=order_revision+1 WHERE library_id=NEW.library_id;
END;
CREATE TRIGGER screen_metadata_attention_browse_update AFTER UPDATE ON screen_metadata_attention WHEN (OLD.retired=0 AND OLD.reason NOT IN('pending','searching','pending_search','pending_episodes','pending_children','pending_apply')) OR (NEW.retired=0 AND NEW.reason NOT IN('pending','searching','pending_search','pending_episodes','pending_children','pending_apply')) BEGIN
 UPDATE library_revisions SET revision=revision+1,order_revision=order_revision+1 WHERE library_id IN(OLD.library_id,NEW.library_id);
END;
CREATE TRIGGER screen_metadata_attention_browse_delete AFTER DELETE ON screen_metadata_attention WHEN OLD.retired=0 AND OLD.reason NOT IN('pending','searching','pending_search','pending_episodes','pending_children','pending_apply') BEGIN
 UPDATE library_revisions SET revision=revision+1,order_revision=order_revision+1 WHERE library_id=OLD.library_id;
END;
CREATE TRIGGER listening_metadata_attention_browse_insert AFTER INSERT ON listening_metadata_attention WHEN NEW.retired=0 AND NEW.reason NOT IN('pending','searching','pending_search','pending_episodes','pending_children','pending_apply') AND NEW.kind IN('album','song') BEGIN
 UPDATE library_revisions SET revision=revision+1,order_revision=order_revision+1 WHERE library_id=NEW.library_id;
END;
CREATE TRIGGER listening_metadata_attention_browse_update AFTER UPDATE ON listening_metadata_attention WHEN (OLD.retired=0 AND OLD.reason NOT IN('pending','searching','pending_search','pending_episodes','pending_children','pending_apply') AND OLD.kind IN('album','song')) OR (NEW.retired=0 AND NEW.reason NOT IN('pending','searching','pending_search','pending_episodes','pending_children','pending_apply') AND NEW.kind IN('album','song')) BEGIN
 UPDATE library_revisions SET revision=revision+1,order_revision=order_revision+1 WHERE library_id IN(OLD.library_id,NEW.library_id);
END;
CREATE TRIGGER listening_metadata_attention_browse_delete AFTER DELETE ON listening_metadata_attention WHEN OLD.retired=0 AND OLD.reason NOT IN('pending','searching','pending_search','pending_episodes','pending_children','pending_apply') AND OLD.kind IN('album','song') BEGIN
 UPDATE library_revisions SET revision=revision+1,order_revision=order_revision+1 WHERE library_id=OLD.library_id;
END;
CREATE TRIGGER library_metadata_agents_browse_insert AFTER INSERT ON library_metadata_agents BEGIN
 UPDATE library_revisions SET revision=revision+1,order_revision=order_revision+1 WHERE library_id=NEW.library_id;
END;
CREATE TRIGGER library_metadata_agents_browse_update AFTER UPDATE ON library_metadata_agents BEGIN
 UPDATE library_revisions SET revision=revision+1,order_revision=order_revision+1 WHERE library_id IN(OLD.library_id,NEW.library_id);
END;
CREATE TRIGGER library_metadata_agents_browse_delete AFTER DELETE ON library_metadata_agents BEGIN
 UPDATE library_revisions SET revision=revision+1,order_revision=order_revision+1 WHERE library_id=OLD.library_id;
END;
CREATE INDEX screen_metadata_attention_browse ON screen_metadata_attention(library_id,entity_id,generation) WHERE retired=0 AND reason NOT IN('pending','searching','pending_search','pending_episodes','pending_children','pending_apply');
CREATE INDEX listening_metadata_attention_browse ON listening_metadata_attention(library_id,entity_id) WHERE retired=0 AND kind IN('album','song') AND reason NOT IN('pending','searching','pending_search','pending_episodes','pending_children','pending_apply');
CREATE TABLE owner_reset_file(singleton INTEGER PRIMARY KEY CHECK(singleton=1),account_id TEXT NOT NULL REFERENCES accounts(id) ON DELETE CASCADE,epoch INTEGER NOT NULL,portico INTEGER NOT NULL CHECK(portico IN(0,1)),code_hash TEXT NOT NULL,issued_at INTEGER NOT NULL,expires_at INTEGER NOT NULL,failed_attempts INTEGER NOT NULL DEFAULT 0 CHECK(failed_attempts BETWEEN 0 AND 5)) STRICT;
CREATE TABLE member_password_resets(account_id TEXT PRIMARY KEY REFERENCES accounts(id) ON DELETE CASCADE,code_hash TEXT NOT NULL,epoch INTEGER NOT NULL,expires_at INTEGER NOT NULL,failed_attempts INTEGER NOT NULL DEFAULT 0 CHECK(failed_attempts BETWEEN 0 AND 5),turn_off_two_step INTEGER NOT NULL CHECK(turn_off_two_step IN(0,1)),membership_revision INTEGER NOT NULL,issuer_id TEXT NOT NULL REFERENCES accounts(id) ON DELETE CASCADE,issuer_epoch INTEGER NOT NULL) STRICT;
CREATE TABLE reset_file_sessions(family_id TEXT PRIMARY KEY REFERENCES authorization_session_families(id) ON DELETE CASCADE,kind TEXT NOT NULL CHECK(kind IN('owner','password'))) STRICT;
CREATE TRIGGER owner_change_account_insert BEFORE INSERT ON accounts WHEN EXISTS(SELECT 1 FROM networking_claim_intents WHERE owner_change_reserved=1 AND approved_username=NEW.username COLLATE NOCASE) BEGIN SELECT RAISE(ABORT,'owner_change_identity_reserved'); END;
CREATE TRIGGER owner_change_account_rename BEFORE UPDATE OF username ON accounts WHEN NEW.username<>OLD.username COLLATE NOCASE AND EXISTS(SELECT 1 FROM networking_claim_intents WHERE owner_change_reserved=1 AND approved_username=NEW.username COLLATE NOCASE) BEGIN SELECT RAISE(ABORT,'owner_change_identity_reserved'); END;
CREATE TRIGGER owner_change_link_insert BEFORE INSERT ON account_portico_links WHEN EXISTS(SELECT 1 FROM networking_claim_intents WHERE owner_change_reserved=1 AND account_id=NEW.hosted_account_id) BEGIN SELECT RAISE(ABORT,'owner_change_identity_reserved'); END;
CREATE TRIGGER owner_change_link_update BEFORE UPDATE OF hosted_account_id ON account_portico_links WHEN NEW.hosted_account_id<>OLD.hosted_account_id AND EXISTS(SELECT 1 FROM networking_claim_intents WHERE owner_change_reserved=1 AND account_id=NEW.hosted_account_id) BEGIN SELECT RAISE(ABORT,'owner_change_identity_reserved'); END;

-- One identity authority per configured server. Before setup there is no row;
-- setup defaults to Portico and installs its explicit choice before accounts.
CREATE TABLE identity_state(singleton INTEGER PRIMARY KEY CHECK(singleton=1),sign_in_kind TEXT NOT NULL CHECK(sign_in_kind IN('portico','local')),revision INTEGER NOT NULL DEFAULT 1 CHECK(revision>0)) STRICT;
CREATE TRIGGER identity_kind_short_invitation_retire AFTER UPDATE OF sign_in_kind ON identity_state
 WHEN NEW.sign_in_kind<>OLD.sign_in_kind
 BEGIN DELETE FROM access_invitation_short_codes; END;
CREATE TRIGGER identity_local_no_portico_link BEFORE INSERT ON account_portico_links
 WHEN (SELECT sign_in_kind FROM identity_state WHERE singleton=1)='local'
 BEGIN SELECT RAISE(ABORT,'sign_in_kind_local'); END;
CREATE TRIGGER identity_local_no_portico_link_update BEFORE UPDATE ON account_portico_links
 WHEN (SELECT sign_in_kind FROM identity_state WHERE singleton=1)='local'
 BEGIN SELECT RAISE(ABORT,'sign_in_kind_local'); END;
CREATE TRIGGER identity_portico_no_password_insert BEFORE INSERT ON accounts
 WHEN length(NEW.password_hash)>0 AND (SELECT sign_in_kind FROM identity_state WHERE singleton=1)='portico'
 BEGIN SELECT RAISE(ABORT,'sign_in_kind_portico'); END;
CREATE TRIGGER identity_portico_no_password_update BEFORE UPDATE OF password_hash ON accounts
 WHEN length(NEW.password_hash)>0 AND (SELECT sign_in_kind FROM identity_state WHERE singleton=1)='portico'
 BEGIN SELECT RAISE(ABORT,'sign_in_kind_portico'); END;
CREATE TRIGGER identity_kind_local_fence BEFORE UPDATE OF sign_in_kind ON identity_state
 WHEN NEW.sign_in_kind='local' AND EXISTS(SELECT 1 FROM account_portico_links)
 BEGIN SELECT RAISE(ABORT,'sign_in_kind_local'); END;
CREATE TRIGGER identity_kind_portico_fence BEFORE UPDATE OF sign_in_kind ON identity_state
 WHEN NEW.sign_in_kind='portico' AND EXISTS(SELECT 1 FROM accounts WHERE length(password_hash)>0)
 BEGIN SELECT RAISE(ABORT,'sign_in_kind_portico'); END;

CREATE TABLE identity_move_waiting(account_id TEXT PRIMARY KEY REFERENCES accounts(id) ON DELETE CASCADE,move_id TEXT NOT NULL,state TEXT NOT NULL CHECK(state IN('waiting','linked','did_not_move')),old_password_hash BLOB,old_password_until_ms INTEGER NOT NULL DEFAULT 0,created_ms INTEGER NOT NULL) STRICT;
CREATE INDEX accounts_people_username ON accounts(username COLLATE NOCASE,id);
CREATE INDEX direct_memberships_people_role ON direct_memberships(role,disabled,account_id);
CREATE INDEX identity_devices_people_activity ON identity_devices(account_id,authority,platform,last_seen DESC);

CREATE TRIGGER identity_access_tokens_disabled AFTER UPDATE OF access_tokens ON direct_memberships WHEN NEW.access_tokens=0 AND OLD.access_tokens=1 BEGIN
 UPDATE api_credentials SET revoked_ms=unixepoch('subsec')*1000,ended_reason='permission_removed' WHERE account_id=NEW.account_id AND kind='token' AND revoked_ms=0;
 UPDATE authorization_session_families SET revoked=1,revoked_reason='membership_removed' WHERE id IN(SELECT family_id FROM api_credentials WHERE account_id=NEW.account_id AND kind='token') AND revoked=0;
END;
CREATE TRIGGER identity_access_tokens_insert BEFORE INSERT ON api_credentials WHEN NEW.kind='token' AND NOT EXISTS(SELECT 1 FROM direct_memberships WHERE account_id=NEW.account_id AND access_tokens=1 AND disabled=0) BEGIN SELECT RAISE(ABORT,'access_tokens_off');END;

CREATE TABLE identity_moves(id TEXT PRIMARY KEY,owner_id TEXT NOT NULL,owner_revision INTEGER NOT NULL,from_kind TEXT NOT NULL CHECK(from_kind IN('portico','local')),to_kind TEXT NOT NULL CHECK(to_kind IN('portico','local')),start_over INTEGER NOT NULL CHECK(start_over IN(0,1)),stage TEXT NOT NULL CHECK(stage IN('preview','moving_to_portico','moving_to_local','complete','cancelled')),revision INTEGER NOT NULL CHECK(revision>0),people INTEGER NOT NULL,other_people_count INTEGER NULL CHECK(other_people_count BETWEEN 0 AND 10000),devices INTEGER NOT NULL,profiles INTEGER NOT NULL,retained_profiles INTEGER NULL,removed_profiles INTEGER NULL,server_name TEXT NOT NULL,created_ms INTEGER NOT NULL,confirmed_ms INTEGER NOT NULL DEFAULT 0,confirmation TEXT NOT NULL DEFAULT '',invitations INTEGER NOT NULL DEFAULT 0,owner_confirmed INTEGER NOT NULL DEFAULT 0 CHECK(owner_confirmed IN(0,1)),CHECK(from_kind<>to_kind),CHECK((retained_profiles IS NULL AND removed_profiles IS NULL) OR (start_over=1 AND retained_profiles IS NOT NULL AND removed_profiles IS NOT NULL AND retained_profiles BETWEEN 0 AND 9007199254740991 AND removed_profiles BETWEEN 0 AND 9007199254740991 AND retained_profiles<=9007199254740991-removed_profiles AND retained_profiles+removed_profiles=profiles))) STRICT;
CREATE UNIQUE INDEX identity_one_move ON identity_moves((1)) WHERE stage NOT IN('complete','cancelled');
CREATE TABLE identity_owner_completions(
 operation_id TEXT PRIMARY KEY REFERENCES networking_claim_intents(operation_id),
 move_id TEXT NOT NULL REFERENCES identity_moves(id),
 family_id TEXT NOT NULL UNIQUE REFERENCES authorization_session_families(id) ON DELETE CASCADE,
 token_hash TEXT NOT NULL,token_generation INTEGER NOT NULL CHECK(token_generation>0),
 owner_id TEXT NOT NULL REFERENCES accounts(id) ON DELETE CASCADE,
 owner_profile_id TEXT NOT NULL REFERENCES direct_profiles(id),owner_epoch INTEGER NOT NULL CHECK(owner_epoch>0),
 phase TEXT NOT NULL CHECK(phase IN('prepared','installed','consumed','completed','cancelled','expired','superseded')),
 claim_hash TEXT NOT NULL CHECK(length(claim_hash)=43),claim_payload BLOB NOT NULL,
 claim_signature BLOB NOT NULL CHECK(length(claim_signature)=64),start_payload BLOB NOT NULL,
 start_signature BLOB NOT NULL CHECK(length(start_signature)=64),state_hash TEXT NOT NULL,
 switch_count_payload BLOB NULL CHECK(switch_count_payload IS NULL OR length(switch_count_payload) BETWEEN 1 AND 8192),
 switch_count_signature BLOB NULL CHECK(switch_count_signature IS NULL OR length(switch_count_signature)=64),
 code_challenge TEXT NOT NULL CHECK(length(code_challenge)=43),installation_id TEXT NOT NULL,server_challenge_hash TEXT NOT NULL,
 created_ms INTEGER NOT NULL,expires_ms INTEGER NOT NULL CHECK(expires_ms>created_ms),
 installed_ms INTEGER NOT NULL DEFAULT 0,completed_ms INTEGER NOT NULL DEFAULT 0,consumed_ms INTEGER NOT NULL DEFAULT 0,
 attempt_id TEXT NOT NULL DEFAULT '',transaction_id TEXT NOT NULL DEFAULT '',move_revision INTEGER NOT NULL CHECK(move_revision>0),
 registration_id TEXT NOT NULL DEFAULT '',registration_origin TEXT NOT NULL DEFAULT '',
 route_generation INTEGER NOT NULL DEFAULT 0 CHECK(route_generation>=0),
 CHECK((switch_count_payload IS NULL AND switch_count_signature IS NULL) OR (switch_count_payload IS NOT NULL AND switch_count_signature IS NOT NULL))
) STRICT;
CREATE TABLE identity_setup_completions(
 operation_id TEXT PRIMARY KEY REFERENCES networking_claim_intents(operation_id),
 setup_request_id TEXT NOT NULL, setup_revision INTEGER NOT NULL CHECK(setup_revision>0),setup_proof TEXT NOT NULL,
 phase TEXT NOT NULL CHECK(phase IN('prepared','installed','consumed','completed','cancelled','expired','superseded')),
 claim_hash TEXT NOT NULL CHECK(length(claim_hash)=43),claim_payload BLOB NOT NULL CHECK(length(claim_payload) BETWEEN 1 AND 8192),claim_signature BLOB NOT NULL CHECK(length(claim_signature)=64),
 start_payload BLOB NOT NULL CHECK(length(start_payload) BETWEEN 1 AND 8192),start_signature BLOB NOT NULL CHECK(length(start_signature)=64),
 state_hash TEXT NOT NULL,code_challenge TEXT NOT NULL CHECK(length(code_challenge)=43),installation_id TEXT NOT NULL,server_challenge_hash TEXT NOT NULL,
 created_ms INTEGER NOT NULL,expires_ms INTEGER NOT NULL CHECK(expires_ms>created_ms AND expires_ms<=created_ms+300000),
 installed_ms INTEGER NOT NULL DEFAULT 0,completed_ms INTEGER NOT NULL DEFAULT 0,consumed_ms INTEGER NOT NULL DEFAULT 0,
 attempt_id TEXT NOT NULL DEFAULT '',transaction_id TEXT NOT NULL DEFAULT ''
) STRICT;
CREATE UNIQUE INDEX identity_setup_one_active ON identity_setup_completions(setup_request_id) WHERE phase IN('prepared','installed','consumed');
CREATE TABLE identity_move_link_tickets(token_hash TEXT PRIMARY KEY,account_id TEXT NOT NULL REFERENCES accounts(id) ON DELETE CASCADE,installation_id TEXT NOT NULL,epoch INTEGER NOT NULL,expires_ms INTEGER NOT NULL,UNIQUE(account_id,installation_id)) STRICT;
CREATE TABLE identity_move_codes(account_id TEXT PRIMARY KEY REFERENCES accounts(id) ON DELETE CASCADE,move_id TEXT NOT NULL REFERENCES identity_moves(id),code_hash TEXT NOT NULL UNIQUE,expires_ms INTEGER NOT NULL) STRICT;
CREATE TABLE identity_service_outbox(notice_id TEXT PRIMARY KEY,operation_id TEXT NOT NULL,server_id TEXT NOT NULL,claim_generation TEXT NOT NULL,credential_generation TEXT NOT NULL,payload BLOB NOT NULL,signature BLOB NOT NULL,created_ms INTEGER NOT NULL,delivered_ms INTEGER NOT NULL DEFAULT 0,attempts INTEGER NOT NULL DEFAULT 0,next_ms INTEGER NOT NULL DEFAULT 0) STRICT;
CREATE TABLE identity_managed_route(singleton INTEGER PRIMARY KEY CHECK(singleton=1),enabled INTEGER NOT NULL DEFAULT 1 CHECK(enabled IN(0,1)),revision INTEGER NOT NULL DEFAULT 1 CHECK(revision>0),problem TEXT NOT NULL DEFAULT '') STRICT;
INSERT INTO identity_managed_route(singleton) VALUES(1);
CREATE TRIGGER identity_kind_no_delete BEFORE DELETE ON identity_state BEGIN SELECT RAISE(ABORT,'identity_state_required');END;
CREATE TRIGGER identity_kind_insert_local_fence BEFORE INSERT ON identity_state WHEN NEW.sign_in_kind='local' AND EXISTS(SELECT 1 FROM account_portico_links) BEGIN SELECT RAISE(ABORT,'sign_in_kind_local');END;
CREATE TRIGGER identity_kind_insert_portico_fence BEFORE INSERT ON identity_state WHEN NEW.sign_in_kind='portico' AND EXISTS(SELECT 1 FROM accounts WHERE length(password_hash)>0) BEGIN SELECT RAISE(ABORT,'sign_in_kind_portico');END;

CREATE TABLE identity_sign_in_policy(
 singleton INTEGER PRIMARY KEY CHECK(singleton=1), revision INTEGER NOT NULL DEFAULT 1 CHECK(revision>=1),
 stay_signed_in_days INTEGER NOT NULL DEFAULT 90 CHECK(stay_signed_in_days IN(7,30,90,365)),
 pin_remember_days INTEGER NOT NULL DEFAULT 30 CHECK(pin_remember_days IN(0,7,30,90)),
 password_attempts TEXT NOT NULL DEFAULT 'standard' CHECK(password_attempts IN('relaxed','standard','strict')),
 pin_attempts TEXT NOT NULL DEFAULT 'standard' CHECK(pin_attempts IN('relaxed','standard','strict')),
 password_min_length INTEGER NOT NULL DEFAULT 8 CHECK(password_min_length IN(8,10,12,16)),
 member_reset_code_minutes INTEGER NOT NULL DEFAULT 60 CHECK(member_reset_code_minutes IN(15,60,1440)),
 require_two_step TEXT NOT NULL DEFAULT 'nobody' CHECK(require_two_step IN('nobody','administrators','everyone')),
 remember_accounts INTEGER NOT NULL DEFAULT 1 CHECK(remember_accounts IN(0,1)),
 ended_sessions_days INTEGER NOT NULL DEFAULT 90 CHECK(ended_sessions_days IN(30,90,365)), updated_ms INTEGER NOT NULL DEFAULT 0
) STRICT;
INSERT INTO identity_sign_in_policy(singleton) VALUES(1);

CREATE TABLE preference_scopes(
 authority TEXT NOT NULL, account_id TEXT NOT NULL, profile_id TEXT NOT NULL,
 scope TEXT NOT NULL CHECK(scope IN('profile-server','profile-device-class','profile-device')),
 device_key TEXT NOT NULL,
 revision INTEGER NOT NULL CHECK(revision>=1), updated_ms INTEGER NOT NULL,
 PRIMARY KEY(authority,account_id,profile_id,scope,device_key),
 CHECK((scope='profile-server' AND device_key='') OR (scope='profile-device-class' AND device_key IN('web','mobile','tablet','television')) OR (scope='profile-device' AND length(device_key)>0))
) STRICT, WITHOUT ROWID;

CREATE TABLE preference_values(
 authority TEXT NOT NULL, account_id TEXT NOT NULL, profile_id TEXT NOT NULL, scope TEXT NOT NULL, device_key TEXT NOT NULL,
 key TEXT NOT NULL, kind TEXT NOT NULL, bool_value INTEGER, number_value REAL, text_value TEXT,
 PRIMARY KEY(authority,account_id,profile_id,scope,device_key,key),
 FOREIGN KEY(authority,account_id,profile_id,scope,device_key) REFERENCES preference_scopes ON DELETE CASCADE,
 CHECK((kind='boolean' AND bool_value IS NOT NULL AND bool_value IN(0,1) AND number_value IS NULL AND text_value IS NULL)
 OR (kind IN('integer','number') AND bool_value IS NULL AND number_value IS NOT NULL AND text_value IS NULL AND (kind='number' OR number_value=CAST(number_value AS INTEGER)))
 OR (kind IN('string','locale') AND bool_value IS NULL AND number_value IS NULL AND text_value IS NOT NULL)
 OR (kind IN('string-list','languageList') AND bool_value IS NULL AND number_value IS NULL AND text_value IS NULL))
) STRICT, WITHOUT ROWID;

CREATE TABLE preference_list_items(
 authority TEXT NOT NULL, account_id TEXT NOT NULL, profile_id TEXT NOT NULL, scope TEXT NOT NULL, device_key TEXT NOT NULL,
 key TEXT NOT NULL, position INTEGER NOT NULL CHECK(position>=0 AND position<64), value TEXT NOT NULL,
 PRIMARY KEY(authority,account_id,profile_id,scope,device_key,key,position),
 UNIQUE(authority,account_id,profile_id,scope,device_key,key,value),
 FOREIGN KEY(authority,account_id,profile_id,scope,device_key,key) REFERENCES preference_values ON DELETE CASCADE
) STRICT, WITHOUT ROWID;

CREATE TABLE account_stream_limits(
 account_id TEXT PRIMARY KEY REFERENCES accounts(id) ON DELETE CASCADE,
 mode TEXT NOT NULL CHECK(mode IN('inherit','unlimited','limit')),
 stream_limit INTEGER,
 "away_quality" TEXT CHECK("away_quality" IN('server','2160p','1080p-high','1080p-low','720p-high','720p-low','480p','240p')),
 CHECK((mode='limit' AND stream_limit IS NOT NULL AND stream_limit BETWEEN 1 AND 1000) OR (mode IN('inherit','unlimited') AND stream_limit IS NULL))
) STRICT;

CREATE TABLE asset_stream_breadth(
 asset_id TEXT NOT NULL,
 stream_index INTEGER NOT NULL,
 audio_description INTEGER NOT NULL DEFAULT 0 CHECK(audio_description IN(0,1)),
 audio_variant TEXT NOT NULL DEFAULT '',
 chroma_subsampling TEXT NOT NULL DEFAULT '',
 fps_numerator INTEGER NOT NULL DEFAULT 0 CHECK(fps_numerator>=0),
 fps_denominator INTEGER NOT NULL DEFAULT 0 CHECK(fps_denominator>=0),
 frame_rate_mode TEXT NOT NULL DEFAULT '' CHECK(frame_rate_mode IN('','constant','variable')),
 interlace_analysis TEXT NOT NULL DEFAULT '',
 telecine INTEGER NOT NULL DEFAULT 0 CHECK(telecine IN(0,1)),
 dovi_rpu INTEGER NOT NULL DEFAULT 0 CHECK(dovi_rpu IN(0,1)),
 dovi_base_layer INTEGER NOT NULL DEFAULT 0 CHECK(dovi_base_layer IN(0,1)),
 dovi_metadata_known INTEGER NOT NULL DEFAULT 0 CHECK(dovi_metadata_known IN(0,1)),
 dovi_enhancement_type TEXT NOT NULL DEFAULT '' CHECK(dovi_enhancement_type IN('','mel','fel')),
