 UPDATE reading_attribution_state SET input_generation=input_generation+1,phase='scan' WHERE (library_id IN(SELECT library_id FROM catalog_entities WHERE id=NEW.item_id));
END;
CREATE TRIGGER reading_attribution_dvr_delete BEFORE DELETE ON dvr_catalog_retirements BEGIN
 UPDATE reading_attribution_state SET input_generation=input_generation+1,phase='scan' WHERE (library_id IN(SELECT library_id FROM catalog_entities WHERE id=OLD.item_id));
END;
CREATE TRIGGER reading_attribution_dvr_update BEFORE UPDATE ON dvr_catalog_retirements BEGIN
 UPDATE reading_attribution_state SET input_generation=input_generation+1,phase='scan' WHERE (library_id IN(SELECT library_id FROM catalog_entities WHERE id=OLD.item_id)) OR (library_id IN(SELECT library_id FROM catalog_entities WHERE id=NEW.item_id));
END;
CREATE TRIGGER reading_attribution_public_library BEFORE UPDATE OF id,kind,root ON libraries BEGIN
 UPDATE reading_attribution_state SET input_generation=input_generation+1,phase='scan' WHERE library_id IN(SELECT id FROM catalog_libraries WHERE library_id IN(OLD.id,NEW.id)); END;
CREATE TRIGGER reading_attribution_public_kind AFTER UPDATE OF kind ON libraries WHEN NEW.kind IN('book','comic') BEGIN
 INSERT INTO reading_attribution_state(library_id) SELECT id FROM catalog_libraries WHERE library_id=NEW.id ON CONFLICT(library_id) DO NOTHING; END;

CREATE TRIGGER identity_server_short_invitation_retire AFTER UPDATE ON networking_claim_identity
 WHEN NEW.server_id<>OLD.server_id OR NEW.public_key<>OLD.public_key OR NEW.reset_generation<>OLD.reset_generation
 BEGIN DELETE FROM access_invitation_short_codes; END;
CREATE TRIGGER identity_server_short_invitation_deleted AFTER DELETE ON networking_claim_identity
 BEGIN DELETE FROM access_invitation_short_codes; END;

-- PROPOSED FIRST SLICE ONLY. No effective projection/writer cutover.
CREATE TABLE credit_source_publications(
 publication_id TEXT PRIMARY KEY CHECK(length(publication_id)=32 AND publication_id NOT GLOB '*[^0-9a-f]*'),
 entity_id INTEGER NOT NULL REFERENCES catalog_entities(id) ON DELETE CASCADE,
 provider TEXT NOT NULL CHECK(length(CAST(provider AS BLOB)) BETWEEN 1 AND 64),
 accepted_record_reference TEXT NOT NULL CHECK(length(CAST(accepted_record_reference AS BLOB)) BETWEEN 1 AND 4096 AND length(trim(accepted_record_reference))>0),
 observed_at TEXT NOT NULL CHECK(length(CAST(observed_at AS BLOB)) BETWEEN 1 AND 64),
 member_count INTEGER NOT NULL CHECK(member_count BETWEEN 0 AND 128),
 sealed INTEGER NOT NULL DEFAULT 0 CHECK(sealed IN(0,1)),
 UNIQUE(publication_id,entity_id,provider)
) STRICT;
CREATE INDEX credit_source_publications_entity ON credit_source_publications(entity_id);
CREATE TABLE credit_source_rows(
 source_row_id TEXT PRIMARY KEY CHECK(length(source_row_id)=32 AND source_row_id NOT GLOB '*[^0-9a-f]*'),
 entity_id INTEGER NOT NULL REFERENCES catalog_entities(id) ON DELETE CASCADE,
 provider TEXT NOT NULL CHECK(length(CAST(provider AS BLOB)) BETWEEN 1 AND 64),
 tuple_digest TEXT NOT NULL CHECK(length(tuple_digest)=64 AND tuple_digest NOT GLOB '*[^0-9a-f]*'),
 original_record_reference TEXT NOT NULL CHECK(length(CAST(original_record_reference AS BLOB))<=4096 AND length(trim(original_record_reference))>0),
 original_credit_id TEXT NOT NULL CHECK(length(CAST(original_credit_id AS BLOB))<=256),
 original_provider_person_id TEXT NOT NULL CHECK(length(CAST(original_provider_person_id AS BLOB))<=256),
 original_person_identity_key TEXT NOT NULL CHECK(length(CAST(original_person_identity_key AS BLOB))<=512),
 original_person_token TEXT NOT NULL CHECK(length(CAST(original_person_token AS BLOB))<=256),
 original_target_kind TEXT NOT NULL CHECK(length(CAST(original_target_kind AS BLOB))<=64),
 original_target_id TEXT NOT NULL CHECK(length(CAST(original_target_id AS BLOB))<=256),
 original_credited_name TEXT NOT NULL CHECK(length(CAST(original_credited_name AS BLOB))<=1200),
 original_role TEXT NOT NULL CHECK(length(CAST(original_role AS BLOB))<=2000),
 original_department TEXT NOT NULL CHECK(length(CAST(original_department AS BLOB))<=800),
 original_source_ordinal INTEGER NOT NULL CHECK(original_source_ordinal>=0),
 UNIQUE(source_row_id,entity_id,provider),
 UNIQUE(source_row_id,entity_id)
) STRICT;
CREATE INDEX credit_source_rows_tuple ON credit_source_rows(entity_id,provider,tuple_digest);
CREATE INDEX credit_source_rows_person_reference ON credit_source_rows(original_person_identity_key,original_person_token);
CREATE TABLE credit_source_publication_members(
 publication_id TEXT NOT NULL,
 entity_id INTEGER NOT NULL,
 provider TEXT NOT NULL,
 position INTEGER NOT NULL CHECK(position>=0 AND position<128),
 source_row_id TEXT NOT NULL,
 reference_status TEXT NOT NULL CHECK(reference_status IN('new','exact','ambiguous')),
 PRIMARY KEY(publication_id,position),
 FOREIGN KEY(publication_id,entity_id,provider) REFERENCES credit_source_publications(publication_id,entity_id,provider) ON DELETE CASCADE,
 FOREIGN KEY(source_row_id,entity_id,provider) REFERENCES credit_source_rows(source_row_id,entity_id,provider),
 UNIQUE(publication_id,source_row_id)
) WITHOUT ROWID, STRICT;
CREATE INDEX credit_source_publication_members_source ON credit_source_publication_members(source_row_id,publication_id);
CREATE TABLE credit_source_heads(
 entity_id INTEGER NOT NULL REFERENCES catalog_entities(id) ON DELETE CASCADE,
 provider TEXT NOT NULL CHECK(length(CAST(provider AS BLOB)) BETWEEN 1 AND 64),
 publication_id TEXT NOT NULL,
 revision INTEGER NOT NULL CHECK(revision>0),
 PRIMARY KEY(entity_id,provider),
 FOREIGN KEY(publication_id,entity_id,provider) REFERENCES credit_source_publications(publication_id,entity_id,provider)
) WITHOUT ROWID, STRICT;
CREATE TABLE credit_owner_families(
 entity_id INTEGER PRIMARY KEY REFERENCES catalog_entities(id) ON DELETE CASCADE,
 revision INTEGER NOT NULL CHECK(revision>0),
 locked INTEGER NOT NULL CHECK(locked IN(0,1)),
 actor TEXT NOT NULL CHECK(length(CAST(actor AS BLOB)) BETWEEN 1 AND 256),
 observed_at TEXT NOT NULL CHECK(length(CAST(observed_at AS BLOB)) BETWEEN 1 AND 64)
) STRICT;
CREATE TABLE credit_owner_entries(
 entry_id TEXT PRIMARY KEY CHECK(length(entry_id)=32 AND entry_id NOT GLOB '*[^0-9a-f]*'),
 entity_id INTEGER NOT NULL REFERENCES credit_owner_families(entity_id) ON DELETE CASCADE,
 position INTEGER NOT NULL CHECK(position>=0 AND position<2048),
 operation TEXT NOT NULL CHECK(operation IN('retain','edit','exclude','add')),
 source_row_id TEXT,
 credited_name TEXT NOT NULL CHECK(length(CAST(credited_name AS BLOB)) BETWEEN 1 AND 1200),
 role TEXT NOT NULL CHECK(length(CAST(role AS BLOB))<=2000),
 department TEXT NOT NULL CHECK(length(CAST(department AS BLOB))<=800),
 UNIQUE(entity_id,position),
 FOREIGN KEY(source_row_id,entity_id) REFERENCES credit_source_rows(source_row_id,entity_id),
 CHECK((operation='add' AND source_row_id IS NULL) OR(operation<>'add' AND source_row_id IS NOT NULL))
) STRICT;
CREATE UNIQUE INDEX credit_owner_entries_source ON credit_owner_entries(entity_id,source_row_id) WHERE source_row_id IS NOT NULL;
CREATE UNIQUE INDEX credit_owner_entries_entity_id ON credit_owner_entries(entry_id,entity_id);
-- Only the one-way closure transition may update a publication header.
CREATE TRIGGER credit_source_publications_close BEFORE UPDATE ON credit_source_publications
 WHEN NOT(OLD.sealed=0 AND NEW.sealed=1 AND NEW.publication_id=OLD.publication_id AND NEW.entity_id=OLD.entity_id AND NEW.provider=OLD.provider AND NEW.accepted_record_reference=OLD.accepted_record_reference AND NEW.observed_at=OLD.observed_at AND NEW.member_count=OLD.member_count)
 BEGIN SELECT RAISE(ABORT,'credit source publication is immutable'); END;
CREATE TRIGGER credit_source_publications_seal BEFORE UPDATE OF sealed ON credit_source_publications WHEN NEW.sealed=1
 BEGIN
 SELECT CASE WHEN (SELECT count(*) FROM credit_source_publication_members WHERE publication_id=OLD.publication_id)<>NEW.member_count OR (NEW.member_count>0 AND ((SELECT min(position) FROM credit_source_publication_members WHERE publication_id=OLD.publication_id)<>0 OR (SELECT max(position) FROM credit_source_publication_members WHERE publication_id=OLD.publication_id)<>NEW.member_count-1)) THEN RAISE(ABORT,'credit source publication is incomplete') END;
 END;
CREATE TRIGGER credit_source_publications_closed_insert BEFORE INSERT ON credit_source_publications WHEN NEW.sealed<>0
 BEGIN SELECT RAISE(ABORT,'credit source publication must be assembled before sealing'); END;
CREATE TRIGGER credit_source_publications_keep BEFORE DELETE ON credit_source_publications WHEN OLD.sealed=1 AND EXISTS(SELECT 1 FROM catalog_entities WHERE id=OLD.entity_id)
 BEGIN SELECT RAISE(ABORT,'sealed credit source publication is immutable'); END;
CREATE TRIGGER credit_source_rows_immutable BEFORE UPDATE ON credit_source_rows BEGIN SELECT RAISE(ABORT,'credit source row is immutable'); END;
CREATE TRIGGER credit_source_rows_keep BEFORE DELETE ON credit_source_rows WHEN EXISTS(SELECT 1 FROM catalog_entities WHERE id=OLD.entity_id)
 BEGIN SELECT RAISE(ABORT,'credit source row is immutable'); END;
CREATE TRIGGER credit_source_members_insert BEFORE INSERT ON credit_source_publication_members
 WHEN NOT EXISTS(SELECT 1 FROM credit_source_publications p WHERE p.publication_id=NEW.publication_id AND p.entity_id=NEW.entity_id AND p.provider=NEW.provider AND p.sealed=0 AND NEW.position<p.member_count)
 BEGIN SELECT RAISE(ABORT,'credit source publication is not open'); END;
CREATE TRIGGER credit_source_members_immutable BEFORE UPDATE ON credit_source_publication_members BEGIN SELECT RAISE(ABORT,'credit source membership is immutable'); END;
CREATE TRIGGER credit_source_members_delete BEFORE DELETE ON credit_source_publication_members
 WHEN EXISTS(SELECT 1 FROM catalog_entities WHERE id=OLD.entity_id) AND EXISTS(SELECT 1 FROM credit_source_publications WHERE publication_id=OLD.publication_id AND sealed=1)
 BEGIN SELECT RAISE(ABORT,'sealed credit source membership is immutable'); END;
CREATE TRIGGER credit_source_heads_sealed_insert BEFORE INSERT ON credit_source_heads
 WHEN NOT EXISTS(SELECT 1 FROM credit_source_publications WHERE publication_id=NEW.publication_id AND entity_id=NEW.entity_id AND provider=NEW.provider AND sealed=1)
 BEGIN SELECT RAISE(ABORT,'credit source head requires sealed publication'); END;
CREATE TRIGGER credit_source_heads_sealed_update BEFORE UPDATE ON credit_source_heads
 WHEN NOT EXISTS(SELECT 1 FROM credit_source_publications WHERE publication_id=NEW.publication_id AND entity_id=NEW.entity_id AND provider=NEW.provider AND sealed=1)
 BEGIN SELECT RAISE(ABORT,'credit source head requires sealed publication'); END;
CREATE TRIGGER credit_source_publications_no_replace BEFORE INSERT ON credit_source_publications WHEN EXISTS(SELECT 1 FROM credit_source_publications WHERE publication_id=NEW.publication_id)
 BEGIN SELECT RAISE(ABORT,'credit source publication already exists'); END;
CREATE TRIGGER credit_source_rows_no_replace BEFORE INSERT ON credit_source_rows WHEN EXISTS(SELECT 1 FROM credit_source_rows WHERE source_row_id=NEW.source_row_id)
 BEGIN SELECT RAISE(ABORT,'credit source row already exists'); END;

-- Owner-requested recording root; effective binding belongs to startup only.
CREATE TABLE recording_root_request(
 singleton INTEGER PRIMARY KEY CHECK(singleton=1),revision INTEGER NOT NULL CHECK(revision BETWEEN 1 AND 9007199254740991),
 path TEXT NOT NULL DEFAULT '',folder_identity TEXT NOT NULL DEFAULT '',requested_by TEXT NOT NULL DEFAULT '',
 requested_epoch INTEGER NOT NULL DEFAULT 0 CHECK(requested_epoch>=0),
 applied_path TEXT NOT NULL DEFAULT '',applied_identity TEXT NOT NULL DEFAULT '',
 CHECK((path='' AND folder_identity='' AND requested_by='' AND requested_epoch=0) OR (path<>'' AND folder_identity<>'' AND requested_by<>'' AND requested_epoch>0)),
 CHECK((applied_path='' AND applied_identity='') OR (applied_path<>'' AND applied_identity<>''))) STRICT;
INSERT INTO recording_root_request(singleton,revision) VALUES(1,1);
-- Reading My List groups are private dynamic references, never catalogue entities.
-- Library identity is intentionally not rebound/cascaded when a library disappears.
CREATE TABLE reading_saved_groups (
 reference_id TEXT PRIMARY KEY CHECK(length(reference_id) BETWEEN 1 AND 128),
 owner_key TEXT NOT NULL CHECK(length(owner_key)>0), server_id TEXT NOT NULL CHECK(length(server_id)>0),
 library_id TEXT NOT NULL CHECK(length(library_id) BETWEEN 1 AND 128),
 group_kind TEXT NOT NULL CHECK(group_kind IN('series','magazine','newspaper')),
 series_key TEXT COLLATE BINARY NOT NULL CHECK(length(CAST(series_key AS BLOB)) BETWEEN 1 AND 1048576),
 listed INTEGER NOT NULL CHECK(listed IN(0,1)), revision INTEGER NOT NULL CHECK(revision BETWEEN 1 AND 9007199254740991),
 UNIQUE(owner_key,server_id,library_id,group_kind,series_key)
) STRICT;
CREATE INDEX reading_saved_groups_owner_listed ON reading_saved_groups(owner_key,server_id,listed,reference_id);
CREATE TABLE reading_saved_group_receipts (
 owner_key TEXT NOT NULL, server_id TEXT NOT NULL, operation_id TEXT NOT NULL,
 request_hash TEXT NOT NULL, response TEXT NOT NULL, created_at TEXT NOT NULL,
 PRIMARY KEY(owner_key,server_id,operation_id)
) STRICT;
CREATE INDEX reading_saved_group_receipts_expiry ON reading_saved_group_receipts(created_at);
CREATE TABLE reading_saved_group_owners (
 owner_key TEXT NOT NULL, server_id TEXT NOT NULL,
 revision INTEGER NOT NULL CHECK(revision BETWEEN 1 AND 9007199254740991),
 PRIMARY KEY(owner_key,server_id)
) STRICT;
CREATE TRIGGER reading_saved_group_identity_immutable BEFORE UPDATE OF reference_id,owner_key,server_id,library_id,group_kind,series_key ON reading_saved_groups
 WHEN NEW.reference_id<>OLD.reference_id OR NEW.owner_key<>OLD.owner_key OR NEW.server_id<>OLD.server_id OR NEW.library_id<>OLD.library_id OR NEW.group_kind<>OLD.group_kind OR NEW.series_key<>OLD.series_key
 BEGIN SELECT RAISE(ABORT,'private Reading group reference identity is immutable'); END;

-- Root §23: an explicit Send app log is a closed, code-only journal, separate from
-- the server-reference feedback diagnostics. Only the receiving server's owner reads it.
CREATE TABLE app_reports(
 id TEXT PRIMARY KEY,
 recipient_account_id TEXT NOT NULL CHECK(length(recipient_account_id) BETWEEN 1 AND 128),
 authority TEXT NOT NULL CHECK(length(authority) BETWEEN 1 AND 64),
 account_id TEXT NOT NULL CHECK(length(account_id) BETWEEN 1 AND 128),
 profile_id TEXT NOT NULL CHECK(length(profile_id) BETWEEN 1 AND 128),
 device_id TEXT NOT NULL CHECK(length(device_id) BETWEEN 1 AND 256),
 created_ms INTEGER NOT NULL CHECK(created_ms >= 0),
 expires_ms INTEGER NOT NULL CHECK(expires_ms > created_ms AND expires_ms <= created_ms + 604800000),
 entry_count INTEGER NOT NULL CHECK(entry_count BETWEEN 1 AND 200),
 operation_id TEXT NOT NULL CHECK(length(operation_id) BETWEEN 16 AND 128),
 intent_sha TEXT NOT NULL CHECK(length(intent_sha) = 64)
) STRICT;
CREATE TABLE app_report_entries(
 report_id TEXT NOT NULL,
 position INTEGER NOT NULL CHECK(position BETWEEN 0 AND 199),
 at_ms INTEGER NOT NULL CHECK(at_ms >= 0),
 level TEXT NOT NULL CHECK(level IN ('info','warn','error')),
 code TEXT NOT NULL CHECK(code IN ('audio_transition_unavailable','audio_edge_late','audio_processing_unavailable','equalizer_filter_unavailable','audio_autoplay_blocked')),
 PRIMARY KEY(report_id,position),
 FOREIGN KEY(report_id) REFERENCES app_reports(id) ON DELETE CASCADE
) STRICT;
CREATE INDEX app_reports_receipt ON app_reports(authority,created_ms);
CREATE INDEX app_report_entries_report ON app_report_entries(report_id);
CREATE INDEX app_reports_expiry ON app_reports(expires_ms);
CREATE UNIQUE INDEX app_reports_operation ON app_reports(authority,account_id,profile_id,device_id,operation_id);
CREATE INDEX app_reports_recipient ON app_reports(recipient_account_id,created_ms,id);

CREATE TRIGGER hosted_membership_endings_retention_insert AFTER INSERT ON hosted_membership_endings BEGIN INSERT INTO maintenance_retention_rows(table_name,record_key,created_ms) VALUES('hosted_membership_endings',CAST(NEW.rowid AS TEXT),NEW.ended_ms) ON CONFLICT(table_name,record_key) DO UPDATE SET created_ms=excluded.created_ms; END;
CREATE TRIGGER hosted_membership_endings_retention_update AFTER UPDATE OF sequence ON hosted_membership_endings BEGIN UPDATE maintenance_retention_rows SET created_ms=NEW.ended_ms WHERE table_name='hosted_membership_endings' AND record_key=CAST(NEW.rowid AS TEXT); END;
CREATE TRIGGER hosted_membership_endings_retention_delete AFTER DELETE ON hosted_membership_endings BEGIN DELETE FROM maintenance_retention_rows WHERE table_name='hosted_membership_endings' AND record_key=CAST(OLD.rowid AS TEXT); END;
-- The current profile's finite recent radios, recorded only by accepted playback starts.
CREATE TABLE personal_music_radios(
 profile_id TEXT NOT NULL,
 seed_id INTEGER NOT NULL REFERENCES catalog_entities(id) ON DELETE CASCADE,
 last_started_ms INTEGER NOT NULL CHECK(last_started_ms>=0),
 last_session_id TEXT NOT NULL,
 PRIMARY KEY(profile_id,seed_id)) STRICT;
CREATE INDEX personal_music_radios_recent ON personal_music_radios(profile_id,last_started_ms DESC,seed_id DESC);
CREATE INDEX personal_music_radios_seed ON personal_music_radios(seed_id);
CREATE TRIGGER personal_music_radios_revision_INSERT AFTER INSERT ON personal_music_radios BEGIN
 INSERT INTO personal_activity_revisions VALUES(NEW.profile_id,1) ON CONFLICT(profile_id) DO UPDATE SET revision=revision+1;
 INSERT INTO viewer_revisions(profile_id,library_id,revision) SELECT NEW.profile_id,library.library_id,1 FROM catalog_entities seed JOIN catalog_libraries library ON library.id=seed.library_id WHERE seed.id=NEW.seed_id ON CONFLICT(profile_id,library_id) DO UPDATE SET revision=revision+1;
END;
CREATE TRIGGER personal_music_radios_revision_UPDATE AFTER UPDATE ON personal_music_radios BEGIN
 INSERT INTO personal_activity_revisions VALUES(NEW.profile_id,1) ON CONFLICT(profile_id) DO UPDATE SET revision=revision+1;
 INSERT INTO viewer_revisions(profile_id,library_id,revision) SELECT NEW.profile_id,library.library_id,1 FROM catalog_entities seed JOIN catalog_libraries library ON library.id=seed.library_id WHERE seed.id=NEW.seed_id ON CONFLICT(profile_id,library_id) DO UPDATE SET revision=revision+1;
END;
CREATE TRIGGER personal_music_radios_revision_DELETE AFTER DELETE ON personal_music_radios BEGIN
 INSERT INTO personal_activity_revisions VALUES(OLD.profile_id,1) ON CONFLICT(profile_id) DO UPDATE SET revision=revision+1;
 INSERT INTO viewer_revisions(profile_id,library_id,revision) SELECT OLD.profile_id,library.library_id,1 FROM catalog_entities seed JOIN catalog_libraries library ON library.id=seed.library_id WHERE seed.id=OLD.seed_id ON CONFLICT(profile_id,library_id) DO UPDATE SET revision=revision+1;
END;

-- Exact admitted occurrence lookup must not load a whole large queue in its writer.
CREATE INDEX queue_v1_segments_entry ON queue_v1_segments(queue_id,snapshot_id,first_ordinal);

-- Account-capacity invalidations are one metadata-free pending row per account.
-- The ordinary feed flush publishes them only after the releasing transaction commits.
CREATE TRIGGER playback_v1_capacity_release AFTER UPDATE OF ended_ms ON playback_v1_sessions
WHEN OLD.ended_ms=0 AND NEW.ended_ms>0 AND OLD.account_id<>'' AND OLD.authority IN('local','hosted')
BEGIN
 INSERT INTO api_change_pending(audience,type,resource_kind,resource_id,revision,data)
 VALUES('capacity:'||OLD.authority||':'||OLD.account_id,'capacity.changed','','','','')
 ON CONFLICT(audience,type,resource_kind,resource_id) DO NOTHING;
END;
CREATE TRIGGER playback_v1_capacity_delete AFTER DELETE ON playback_v1_sessions
WHEN OLD.ended_ms=0 AND OLD.account_id<>'' AND OLD.authority IN('local','hosted')
BEGIN
 INSERT INTO api_change_pending(audience,type,resource_kind,resource_id,revision,data)
 VALUES('capacity:'||OLD.authority||':'||OLD.account_id,'capacity.changed','','','','')
 ON CONFLICT(audience,type,resource_kind,resource_id) DO NOTHING;
END;
CREATE TRIGGER playback_media_capacity_release AFTER UPDATE OF state ON playback_sessions
WHEN OLD.state NOT IN('stopped','ended','failed') AND NEW.state IN('stopped','ended','failed')
BEGIN
 INSERT INTO api_change_pending(audience,type,resource_kind,resource_id,revision,data)
 SELECT 'capacity:'||auth.authority||':'||OLD.account_id,'capacity.changed','','','',''
 FROM authorization_access auth
 WHERE auth.hash=OLD.session_hash AND auth.account_id=OLD.account_id
 AND auth.authority IN('local','hosted') AND OLD.account_id<>''
 AND NOT EXISTS(SELECT 1 FROM playback_v1_sessions v WHERE v.media_session_id=OLD.id AND v.ended_ms=0
  AND v.lease_expires_ms>CAST((julianday('now')-2440587.5)*86400000 AS INTEGER))
 AND NOT EXISTS(SELECT 1 FROM playback_private_presentations pp JOIN playback_sessions owner ON owner.id=pp.owner_session_id
  WHERE pp.session_id=OLD.id AND owner.state NOT IN('stopped','ended','failed') AND owner.expires_at>strftime('%Y-%m-%dT%H:%M:%SZ','now'))
 ON CONFLICT(audience,type,resource_kind,resource_id) DO NOTHING;
END;
CREATE TRIGGER playback_media_capacity_delete AFTER DELETE ON playback_sessions
WHEN OLD.state NOT IN('stopped','ended','failed')
BEGIN
 INSERT INTO api_change_pending(audience,type,resource_kind,resource_id,revision,data)
 SELECT 'capacity:'||auth.authority||':'||OLD.account_id,'capacity.changed','','','',''
 FROM authorization_access auth
 WHERE auth.hash=OLD.session_hash AND auth.account_id=OLD.account_id
 AND auth.authority IN('local','hosted') AND OLD.account_id<>''
 AND NOT EXISTS(SELECT 1 FROM playback_v1_sessions v WHERE v.media_session_id=OLD.id AND v.ended_ms=0
  AND v.lease_expires_ms>CAST((julianday('now')-2440587.5)*86400000 AS INTEGER))
 AND NOT EXISTS(SELECT 1 FROM playback_private_presentations pp JOIN playback_sessions owner ON owner.id=pp.owner_session_id
  WHERE pp.session_id=OLD.id AND owner.state NOT IN('stopped','ended','failed') AND owner.expires_at>strftime('%Y-%m-%dT%H:%M:%SZ','now'))
 ON CONFLICT(audience,type,resource_kind,resource_id) DO NOTHING;
END;
-- A Root42 intent binds one authenticated source to one redeemed Cast target.
-- It never contains a queue graph, bearer, media URL or future-item grant.
CREATE TABLE social_cast_queue_transfers(
 id TEXT PRIMARY KEY REFERENCES social_cast_bootstraps(id) ON DELETE CASCADE,
 authority TEXT NOT NULL,account_id TEXT NOT NULL,profile_id TEXT NOT NULL,
 source_family_id TEXT NOT NULL,source_device_id TEXT NOT NULL,
 source_session_id TEXT NOT NULL,source_generation INTEGER NOT NULL CHECK(source_generation>0),
 queue_id TEXT NOT NULL,entry_id TEXT NOT NULL,queue_revision INTEGER NOT NULL CHECK(queue_revision>=0),
 source_position INTEGER NOT NULL CHECK(source_position>=0),
 target_cast_id TEXT NOT NULL DEFAULT '',target_family_id TEXT NOT NULL DEFAULT '',
 target_device_id TEXT NOT NULL DEFAULT '',target_generation INTEGER NOT NULL DEFAULT 0,target_custody_generation INTEGER NOT NULL DEFAULT 0,
 state TEXT NOT NULL CHECK(state IN('pending','bound','cancelled','committed')),
 target_session_id TEXT NOT NULL DEFAULT '',start_key TEXT NOT NULL DEFAULT '',start_digest TEXT NOT NULL DEFAULT '',
 expires_ms INTEGER NOT NULL,created_ms INTEGER NOT NULL
) STRICT;
CREATE INDEX social_cast_queue_transfers_expiry ON social_cast_queue_transfers(expires_ms,id);

-- Root50 controller authority is normalized and independent of media custody.
CREATE TABLE social_cast_controllers(
 id TEXT PRIMARY KEY, bootstrap_id TEXT NOT NULL UNIQUE REFERENCES social_cast_bootstraps(id) ON DELETE CASCADE,
 receiver_id TEXT NOT NULL, target_id TEXT NOT NULL REFERENCES social_cast_devices(id) ON DELETE CASCADE,
 target_family_id TEXT NOT NULL, target_generation TEXT NOT NULL, server_id TEXT NOT NULL,
 authority TEXT NOT NULL, account_id TEXT NOT NULL, profile_id TEXT NOT NULL,
 sender_device_id TEXT NOT NULL, sender_family_id TEXT NOT NULL, sender_role TEXT NOT NULL, sender_epoch INTEGER NOT NULL,
 proof_digest TEXT NOT NULL, ticket_digest TEXT NOT NULL DEFAULT '', ticket_attempt TEXT NOT NULL DEFAULT '', ticket_expires_ms INTEGER NOT NULL DEFAULT 0
) STRICT;

-- Root52 private custody for ONE complete admitted weak finite ISO acquisition.
-- Source-policy reservations are owned separately by the source adapter.
CREATE TABLE owned_capture_sources(
 capture_id TEXT PRIMARY KEY CHECK(length(capture_id)=64),
 source_id TEXT NOT NULL,config_generation TEXT NOT NULL,
 object_id TEXT NOT NULL,object_revision TEXT NOT NULL,asset_id TEXT NOT NULL,
 acquisition_id TEXT NOT NULL UNIQUE,reservation_id TEXT NOT NULL UNIQUE,
 policy_witness TEXT NOT NULL,authority_witness TEXT NOT NULL,
 expected_size INTEGER NOT NULL CHECK(expected_size>0),
 created_ms INTEGER NOT NULL,expires_ms INTEGER NOT NULL CHECK(expires_ms>created_ms)
) STRICT;
CREATE TABLE owned_capture_lifecycle(
 capture_id TEXT PRIMARY KEY REFERENCES owned_capture_sources(capture_id),
 state TEXT NOT NULL CHECK(state IN('capturing','ready','retired','deleted')),
 pending_digest TEXT NOT NULL DEFAULT '',updated_ms INTEGER NOT NULL
) STRICT;
CREATE INDEX owned_capture_lifecycle_collect ON owned_capture_lifecycle(state,updated_ms,capture_id);
CREATE TABLE owned_capture_receipts(
 capture_id TEXT PRIMARY KEY REFERENCES owned_capture_sources(capture_id),
 artifact_id TEXT NOT NULL UNIQUE CHECK(length(artifact_id)=64),
 digest TEXT NOT NULL CHECK(length(digest)=64),
 size INTEGER NOT NULL CHECK(size>0),version_id TEXT NOT NULL CHECK(length(version_id)=64)
) STRICT;
CREATE TABLE owned_capture_reader_pins(
 id TEXT PRIMARY KEY,capture_id TEXT NOT NULL REFERENCES owned_capture_receipts(capture_id),
 expires_ms INTEGER NOT NULL
) STRICT;
CREATE INDEX owned_capture_reader_pins_capture ON owned_capture_reader_pins(capture_id,expires_ms);
CREATE TRIGGER owned_capture_source_immutable BEFORE UPDATE ON owned_capture_sources
BEGIN SELECT RAISE(ABORT,'owned capture provenance is immutable'); END;
CREATE TRIGGER owned_capture_receipt_immutable BEFORE UPDATE ON owned_capture_receipts
BEGIN SELECT RAISE(ABORT,'owned capture receipt is immutable'); END;
CREATE TRIGGER owned_capture_receipt_complete BEFORE INSERT ON owned_capture_receipts
WHEN NOT EXISTS(SELECT 1 FROM owned_capture_sources s JOIN owned_capture_lifecycle l ON l.capture_id=s.capture_id
 WHERE s.capture_id=NEW.capture_id AND s.expected_size=NEW.size AND l.state='capturing' AND l.pending_digest=NEW.digest)
BEGIN SELECT RAISE(ABORT,'owned capture receipt is not a completed acquisition'); END;

-- Private per-presentation remote disc facts. No public catalogue/custody grant.
CREATE TABLE playback_disc_snapshots(
 id TEXT PRIMARY KEY,session_id TEXT NOT NULL REFERENCES playback_sessions(id),
 generation INTEGER NOT NULL CHECK(generation>0),
 input_kind TEXT NOT NULL CHECK(input_kind IN('conditional','captured')),
 UNIQUE(session_id,generation)
) STRICT;
CREATE TABLE playback_disc_lifecycle(
 snapshot_id TEXT PRIMARY KEY REFERENCES playback_disc_snapshots(id) ON DELETE CASCADE,
 state TEXT NOT NULL CHECK(state IN('pending','active','retired')),
 sealed INTEGER NOT NULL DEFAULT 0 CHECK(sealed IN(0,1)),
 created_ms INTEGER NOT NULL,expires_ms INTEGER NOT NULL CHECK(expires_ms>created_ms),
 retired_ms INTEGER NOT NULL DEFAULT 0,
 CHECK(state!='active' OR sealed=1)
) STRICT;
CREATE INDEX playback_disc_lifecycle_collect ON playback_disc_lifecycle(state,expires_ms,snapshot_id);
CREATE TABLE playback_disc_snapshot_actor(
 snapshot_id TEXT PRIMARY KEY REFERENCES playback_disc_snapshots(id) ON DELETE CASCADE,
 server_id TEXT NOT NULL,
 authority TEXT NOT NULL,
 account_id TEXT NOT NULL,
 profile_id TEXT NOT NULL,
 device_id TEXT NOT NULL,
 family_id TEXT NOT NULL,
 grant_id TEXT NOT NULL,
 session_hash TEXT NOT NULL,
 epoch INTEGER NOT NULL,
 token_generation INTEGER NOT NULL,
 original_horizon_ms INTEGER NOT NULL
) STRICT;
CREATE TABLE playback_disc_snapshot_operation(
 snapshot_id TEXT PRIMARY KEY REFERENCES playback_disc_snapshots(id) ON DELETE CASCADE,
 legacy_request_id TEXT NOT NULL,
 start_key_digest TEXT NOT NULL,
 start_body_digest TEXT NOT NULL,
 queue_id TEXT NOT NULL,
 queue_entry_id TEXT NOT NULL,
 queue_owner_kind TEXT NOT NULL,
 queue_owner_id TEXT NOT NULL,
 queue_revision INTEGER NOT NULL,
 queue_custody_generation INTEGER NOT NULL
) STRICT;
CREATE TABLE playback_disc_snapshot_source(
 snapshot_id TEXT PRIMARY KEY REFERENCES playback_disc_snapshots(id) ON DELETE CASCADE,
