 BEGIN SELECT RAISE(ABORT,'private disc snapshot is still retained'); END;
CREATE TRIGGER playback_disc_snapshot_streams_insert BEFORE INSERT ON playback_disc_snapshot_streams
 WHEN NOT EXISTS(SELECT 1 FROM playback_disc_lifecycle WHERE snapshot_id=NEW.snapshot_id AND state='pending' AND sealed=0)
 BEGIN SELECT RAISE(ABORT,'private disc snapshot is sealed'); END;
CREATE TRIGGER playback_disc_snapshot_streams_immutable BEFORE UPDATE ON playback_disc_snapshot_streams
 BEGIN SELECT RAISE(ABORT,'private disc snapshot is immutable'); END;
CREATE TRIGGER playback_disc_snapshot_streams_delete BEFORE DELETE ON playback_disc_snapshot_streams
 WHEN NOT EXISTS(SELECT 1 FROM playback_disc_lifecycle WHERE snapshot_id=OLD.snapshot_id AND state='retired')
 BEGIN SELECT RAISE(ABORT,'private disc snapshot is still retained'); END;
CREATE TRIGGER playback_disc_snapshot_chapters_insert BEFORE INSERT ON playback_disc_snapshot_chapters
 WHEN NOT EXISTS(SELECT 1 FROM playback_disc_lifecycle WHERE snapshot_id=NEW.snapshot_id AND state='pending' AND sealed=0)
 BEGIN SELECT RAISE(ABORT,'private disc snapshot is sealed'); END;
CREATE TRIGGER playback_disc_snapshot_chapters_immutable BEFORE UPDATE ON playback_disc_snapshot_chapters
 BEGIN SELECT RAISE(ABORT,'private disc snapshot is immutable'); END;
CREATE TRIGGER playback_disc_snapshot_chapters_delete BEFORE DELETE ON playback_disc_snapshot_chapters
 WHEN NOT EXISTS(SELECT 1 FROM playback_disc_lifecycle WHERE snapshot_id=OLD.snapshot_id AND state='retired')
 BEGIN SELECT RAISE(ABORT,'private disc snapshot is still retained'); END;
CREATE TRIGGER playback_disc_snapshot_immutable BEFORE UPDATE ON playback_disc_snapshots
BEGIN SELECT RAISE(ABORT,'private disc snapshot identity is immutable'); END;
CREATE TRIGGER playback_disc_snapshot_delete BEFORE DELETE ON playback_disc_snapshots
WHEN NOT EXISTS(SELECT 1 FROM playback_disc_lifecycle WHERE snapshot_id=OLD.id AND state='retired')
 OR EXISTS(SELECT 1 FROM playback_disc_reader_pins WHERE snapshot_id=OLD.id)
 OR EXISTS(SELECT 1 FROM owned_capture_presentation_refs WHERE snapshot_id=OLD.id)
 OR EXISTS(SELECT 1 FROM playback_disc_subtitle_resources WHERE snapshot_id=OLD.id)
BEGIN SELECT RAISE(ABORT,'private disc snapshot still owns references'); END;
CREATE TRIGGER playback_disc_lifecycle_insert BEFORE INSERT ON playback_disc_lifecycle
WHEN NEW.state!='pending' OR NEW.sealed!=0 OR NEW.retired_ms!=0
BEGIN SELECT RAISE(ABORT,'private disc lifecycle must begin pending and unsealed'); END;
CREATE TRIGGER playback_disc_lifecycle_transition BEFORE UPDATE ON playback_disc_lifecycle
WHEN NEW.snapshot_id!=OLD.snapshot_id OR NEW.created_ms!=OLD.created_ms OR NEW.expires_ms!=OLD.expires_ms
 OR NEW.sealed<OLD.sealed OR OLD.state='retired' AND NEW.state!='retired'
 OR OLD.state='active' AND NEW.state='pending' OR NEW.state='active' AND NEW.sealed!=1
BEGIN SELECT RAISE(ABORT,'invalid private disc lifecycle transition'); END;
CREATE TRIGGER playback_disc_lifecycle_seal BEFORE UPDATE OF sealed ON playback_disc_lifecycle
WHEN NEW.sealed=1 AND OLD.sealed=0 AND (
 NOT EXISTS(SELECT 1 FROM playback_disc_snapshots s
 JOIN playback_disc_snapshot_actor a ON a.snapshot_id=s.id
 JOIN playback_disc_snapshot_operation o ON o.snapshot_id=s.id
 JOIN playback_disc_snapshot_source src ON src.snapshot_id=s.id
 JOIN playback_disc_snapshot_disc d ON d.snapshot_id=s.id
 JOIN playback_disc_snapshot_media m ON m.snapshot_id=s.id
 JOIN playback_disc_snapshot_tools t ON t.snapshot_id=s.id
 WHERE s.id=NEW.snapshot_id
 AND EXISTS(SELECT 1 FROM playback_disc_snapshot_titles title WHERE title.snapshot_id=s.id AND title.title_key=d.selected_title_key)
 AND EXISTS(SELECT 1 FROM playback_disc_snapshot_streams stream WHERE stream.snapshot_id=s.id)
 AND ((s.input_kind='conditional' AND EXISTS(SELECT 1 FROM playback_disc_conditional_inputs c WHERE c.snapshot_id=s.id)
  AND NOT EXISTS(SELECT 1 FROM playback_disc_capture_inputs c WHERE c.snapshot_id=s.id)
  AND NOT EXISTS(SELECT 1 FROM owned_capture_presentation_refs r WHERE r.snapshot_id=s.id))
 OR (s.input_kind='captured' AND NOT EXISTS(SELECT 1 FROM playback_disc_conditional_inputs c WHERE c.snapshot_id=s.id)
  AND EXISTS(SELECT 1 FROM playback_disc_capture_inputs c JOIN owned_capture_presentation_refs r ON r.snapshot_id=c.snapshot_id AND r.capture_id=c.capture_id WHERE c.snapshot_id=s.id AND r.expires_ms=NEW.expires_ms))))
)
BEGIN SELECT RAISE(ABORT,'private disc snapshot is incomplete'); END;
CREATE TRIGGER playback_disc_lifecycle_delete BEFORE DELETE ON playback_disc_lifecycle
WHEN EXISTS(SELECT 1 FROM playback_disc_snapshots WHERE id=OLD.snapshot_id)
BEGIN SELECT RAISE(ABORT,'private disc lifecycle still has a snapshot'); END;
CREATE TRIGGER playback_disc_reader_pin_insert BEFORE INSERT ON playback_disc_reader_pins
WHEN NOT EXISTS(SELECT 1 FROM playback_disc_lifecycle WHERE snapshot_id=NEW.snapshot_id AND state='active' AND sealed=1 AND NEW.expires_ms<=expires_ms)
BEGIN SELECT RAISE(ABORT,'private disc reader has no active presentation'); END;
CREATE TRIGGER playback_disc_reader_pin_immutable BEFORE UPDATE ON playback_disc_reader_pins
BEGIN SELECT RAISE(ABORT,'private disc reader pin is immutable'); END;
CREATE TRIGGER owned_capture_presentation_ref_insert BEFORE INSERT ON owned_capture_presentation_refs
WHEN NOT EXISTS(SELECT 1 FROM playback_disc_lifecycle l JOIN playback_disc_capture_inputs c ON c.snapshot_id=l.snapshot_id
 JOIN owned_capture_lifecycle capture ON capture.capture_id=c.capture_id JOIN owned_capture_sources source ON source.capture_id=c.capture_id
 WHERE l.snapshot_id=NEW.snapshot_id AND l.state='pending' AND l.sealed=0 AND c.capture_id=NEW.capture_id
 AND capture.state='ready' AND NEW.expires_ms=l.expires_ms AND NEW.expires_ms<=source.expires_ms)
BEGIN SELECT RAISE(ABORT,'private disc capture reference is not the original ready receipt'); END;
CREATE TRIGGER owned_capture_presentation_ref_immutable BEFORE UPDATE ON owned_capture_presentation_refs
BEGIN SELECT RAISE(ABORT,'private disc capture reference is immutable'); END;
CREATE TRIGGER owned_capture_presentation_ref_delete BEFORE DELETE ON owned_capture_presentation_refs
WHEN NOT EXISTS(SELECT 1 FROM playback_disc_lifecycle WHERE snapshot_id=OLD.snapshot_id AND state='retired')
 OR EXISTS(SELECT 1 FROM playback_disc_reader_pins WHERE snapshot_id=OLD.snapshot_id)
BEGIN SELECT RAISE(ABORT,'private disc presentation still retains its capture'); END;

-- Original actual-Play preparation, before any media session exists. These
-- bounded private rows retain selection/idempotency only, never prepared facts,
-- credentials, locators, byte custody, or a permission reconstructed on restart.
CREATE TABLE playback_start_preparations(
 id TEXT PRIMARY KEY,
 device_id TEXT NOT NULL CHECK(device_id<>''),
 start_key_digest TEXT NOT NULL CHECK(length(start_key_digest)=64),
 start_body_digest TEXT NOT NULL CHECK(length(start_body_digest)=64),
 item_id TEXT NOT NULL CHECK(item_id<>''),
 asset_id TEXT NOT NULL CHECK(asset_id<>''),
 part_index INTEGER NOT NULL CHECK(part_index>=0),
 replaces_session_id TEXT NOT NULL,
 replaces_generation INTEGER NOT NULL,
 token_expires_ms INTEGER NOT NULL,
 created_ms INTEGER NOT NULL CHECK(created_ms>0),
 deadline_ms INTEGER NOT NULL CHECK(deadline_ms>created_ms AND deadline_ms-created_ms<=120000 AND deadline_ms<=token_expires_ms),
 UNIQUE(device_id,start_key_digest),
 CHECK((replaces_session_id='' AND replaces_generation=0) OR (replaces_session_id<>'' AND replaces_generation>0))
) STRICT;
CREATE TABLE playback_start_preparation_lifecycle(
 operation_id TEXT PRIMARY KEY REFERENCES playback_start_preparations(id),
 state TEXT NOT NULL CHECK(state IN('pending','preparing','prepared','accepted','failed','retired')),
 revision INTEGER NOT NULL CHECK(revision>0),
 execution_id TEXT NOT NULL,
 sealed INTEGER NOT NULL CHECK(sealed IN(0,1)),
 CHECK(state<>'pending' OR execution_id=''),
 CHECK(state NOT IN('preparing','prepared','accepted') OR (execution_id<>'' AND sealed=1))
) STRICT;
CREATE UNIQUE INDEX playback_start_preparation_execution ON playback_start_preparation_lifecycle(execution_id) WHERE execution_id<>'';
CREATE INDEX playback_start_preparation_state ON playback_start_preparation_lifecycle(state,operation_id);
CREATE TABLE playback_start_preparation_actor(
 operation_id TEXT PRIMARY KEY REFERENCES playback_start_preparations(id),
 server_id TEXT NOT NULL,
 authority TEXT NOT NULL,
 account_id TEXT NOT NULL,
 profile_id TEXT NOT NULL,
 device_id TEXT NOT NULL,
 family_id TEXT NOT NULL,
 grant_id TEXT NOT NULL,
 session_hash TEXT NOT NULL CHECK(length(session_hash)=64),
 epoch INTEGER NOT NULL CHECK(epoch>=0),
 token_generation INTEGER NOT NULL CHECK(token_generation>0),
 original_horizon_ms INTEGER NOT NULL CHECK(original_horizon_ms>0)
) STRICT;
CREATE TABLE playback_start_preparation_source(
 operation_id TEXT PRIMARY KEY REFERENCES playback_start_preparations(id),
 library_id TEXT NOT NULL,
 library_source_id TEXT NOT NULL,
 asset_id TEXT NOT NULL,
 inventory_object_id TEXT NOT NULL,
 inventory_revision TEXT NOT NULL,
 root_identity TEXT NOT NULL,
 incarnation TEXT NOT NULL,
 remote_source_id TEXT NOT NULL,
 effective_configuration TEXT NOT NULL,
 read_policy_witness TEXT NOT NULL,
 read_authority_witness TEXT NOT NULL,
 library_generation INTEGER NOT NULL CHECK(library_generation>0),
 raw_configuration_generation INTEGER NOT NULL CHECK(raw_configuration_generation>0),
 profile_revision INTEGER NOT NULL CHECK(profile_revision>=0),
 size INTEGER NOT NULL CHECK(size>0),
 modified_ns INTEGER NOT NULL CHECK(modified_ns>=0)
) STRICT;
CREATE TABLE playback_start_preparation_queue(
 operation_id TEXT PRIMARY KEY REFERENCES playback_start_preparations(id),
 legacy_request_id TEXT NOT NULL CHECK(legacy_request_id<>''),
 start_key_digest TEXT NOT NULL CHECK(length(start_key_digest)=64),
 start_body_digest TEXT NOT NULL CHECK(length(start_body_digest)=64),
 queue_id TEXT NOT NULL,
 queue_entry_id TEXT NOT NULL,
 queue_owner_kind TEXT NOT NULL,
 queue_owner_id TEXT NOT NULL,
 queue_revision INTEGER NOT NULL,
 queue_custody_generation INTEGER NOT NULL,
 CHECK((queue_id='' AND queue_entry_id='' AND queue_owner_kind='' AND queue_owner_id='' AND queue_revision=0 AND queue_custody_generation=0)
 OR (queue_id<>'' AND queue_entry_id<>'' AND queue_owner_kind<>'' AND queue_owner_id<>'' AND queue_revision>0 AND queue_custody_generation>=0))
) STRICT;
CREATE TABLE playback_start_preparation_results(
 operation_id TEXT PRIMARY KEY REFERENCES playback_start_preparations(id),
 session_id TEXT NOT NULL UNIQUE,
 legacy_session_id TEXT NOT NULL,
 legacy_generation INTEGER NOT NULL CHECK(legacy_generation>0),
 snapshot_id TEXT NOT NULL UNIQUE
) STRICT;
CREATE TRIGGER playback_start_preparation_root_immutable BEFORE UPDATE ON playback_start_preparations
BEGIN SELECT RAISE(ABORT,'original preparation binding is immutable'); END;
CREATE TRIGGER playback_start_preparation_lifecycle_insert BEFORE INSERT ON playback_start_preparation_lifecycle
WHEN NEW.state<>'pending' OR NEW.revision<>1 OR NEW.execution_id<>'' OR NEW.sealed<>0
BEGIN SELECT RAISE(ABORT,'preparation must begin without an execution or session'); END;
CREATE TRIGGER playback_start_preparation_lifecycle_transition BEFORE UPDATE ON playback_start_preparation_lifecycle
WHEN NEW.operation_id<>OLD.operation_id
 OR OLD.state IN('accepted','failed','retired')
 OR NOT(
  (OLD.state='pending' AND OLD.sealed=0 AND NEW.state='pending' AND NEW.sealed=1 AND NEW.revision=OLD.revision AND NEW.execution_id=OLD.execution_id)
  OR (OLD.sealed=1 AND NEW.sealed=1 AND NEW.revision=OLD.revision+1 AND (
   (OLD.state='pending' AND NEW.state='preparing' AND NEW.execution_id<>'')
   OR (NEW.execution_id=OLD.execution_id AND (
    (OLD.state='preparing' AND NEW.state='prepared')
    OR (OLD.state='prepared' AND NEW.state='accepted')
    OR (OLD.state IN('pending','preparing','prepared') AND NEW.state IN('failed','retired'))
   ))
  ))
 )
BEGIN SELECT RAISE(ABORT,'preparation execution or terminal state cannot be replaced'); END;
CREATE TRIGGER playback_start_preparation_seal BEFORE UPDATE OF sealed ON playback_start_preparation_lifecycle
WHEN OLD.sealed=0 AND NEW.sealed=1 AND NOT EXISTS(
 SELECT 1 FROM playback_start_preparations p
 JOIN playback_start_preparation_actor a ON a.operation_id=p.id
 JOIN playback_start_preparation_source s ON s.operation_id=p.id
 JOIN playback_start_preparation_queue q ON q.operation_id=p.id
 WHERE p.id=NEW.operation_id AND a.device_id=p.device_id AND a.original_horizon_ms>=p.deadline_ms
 AND s.asset_id=p.asset_id AND q.start_key_digest=p.start_key_digest AND q.start_body_digest=p.start_body_digest
)
BEGIN SELECT RAISE(ABORT,'preparation original normalized witnesses are incomplete'); END;
CREATE TRIGGER playback_start_preparation_accept BEFORE UPDATE OF state ON playback_start_preparation_lifecycle
WHEN NEW.state='accepted' AND NOT EXISTS(SELECT 1 FROM playback_start_preparation_results WHERE operation_id=NEW.operation_id)
BEGIN SELECT RAISE(ABORT,'preparation has no exact accepted session result'); END;
CREATE TRIGGER playback_start_preparation_lifecycle_delete BEFORE DELETE ON playback_start_preparation_lifecycle
WHEN NOT EXISTS(SELECT 1 FROM playback_start_preparation_actor a
 JOIN direct_profiles p ON p.id=a.profile_id AND p.account_id=a.account_id
 JOIN direct_memberships m ON m.account_id=p.account_id
 JOIN security_purge_jobs j ON j.authority=a.authority AND j.account_id=a.account_id
  AND j.profile_id=a.profile_id AND j.profile_incarnation=p.lifetime AND j.account_incarnation=m.incarnation
 WHERE a.operation_id=OLD.operation_id AND a.authority='local' AND p.deleted=1 AND j.state IN('pending','running'))
BEGIN SELECT RAISE(ABORT,'preparation lifecycle remains an idempotency tombstone'); END;
CREATE TRIGGER playback_start_preparation_actor_insert BEFORE INSERT ON playback_start_preparation_actor
WHEN NOT EXISTS(SELECT 1 FROM playback_start_preparation_lifecycle WHERE operation_id=NEW.operation_id AND state='pending' AND sealed=0)
BEGIN SELECT RAISE(ABORT,'preparation actor cannot be attached late'); END;
CREATE TRIGGER playback_start_preparation_actor_immutable BEFORE UPDATE ON playback_start_preparation_actor
BEGIN SELECT RAISE(ABORT,'preparation actor is immutable'); END;
CREATE TRIGGER playback_start_preparation_actor_delete BEFORE DELETE ON playback_start_preparation_actor
WHEN NOT EXISTS(SELECT 1 FROM playback_start_preparation_actor a
 JOIN direct_profiles p ON p.id=a.profile_id AND p.account_id=a.account_id
 JOIN direct_memberships m ON m.account_id=p.account_id
 JOIN security_purge_jobs j ON j.authority=a.authority AND j.account_id=a.account_id
  AND j.profile_id=a.profile_id AND j.profile_incarnation=p.lifetime AND j.account_incarnation=m.incarnation
 WHERE a.operation_id=OLD.operation_id AND a.authority='local' AND p.deleted=1 AND j.state IN('pending','running'))
BEGIN SELECT RAISE(ABORT,'preparation actor remains an original witness'); END;
CREATE TRIGGER playback_start_preparation_source_insert BEFORE INSERT ON playback_start_preparation_source
WHEN NOT EXISTS(SELECT 1 FROM playback_start_preparation_lifecycle WHERE operation_id=NEW.operation_id AND state='pending' AND sealed=0)
BEGIN SELECT RAISE(ABORT,'preparation source cannot be attached late'); END;
CREATE TRIGGER playback_start_preparation_source_immutable BEFORE UPDATE ON playback_start_preparation_source
BEGIN SELECT RAISE(ABORT,'preparation source is immutable'); END;
CREATE TRIGGER playback_start_preparation_source_delete BEFORE DELETE ON playback_start_preparation_source
WHEN NOT EXISTS(SELECT 1 FROM playback_start_preparation_actor a
 JOIN direct_profiles p ON p.id=a.profile_id AND p.account_id=a.account_id
 JOIN direct_memberships m ON m.account_id=p.account_id
 JOIN security_purge_jobs j ON j.authority=a.authority AND j.account_id=a.account_id
  AND j.profile_id=a.profile_id AND j.profile_incarnation=p.lifetime AND j.account_incarnation=m.incarnation
 WHERE a.operation_id=OLD.operation_id AND a.authority='local' AND p.deleted=1 AND j.state IN('pending','running'))
BEGIN SELECT RAISE(ABORT,'preparation source remains an original witness'); END;
CREATE TRIGGER playback_start_preparation_queue_insert BEFORE INSERT ON playback_start_preparation_queue
WHEN NOT EXISTS(SELECT 1 FROM playback_start_preparation_lifecycle WHERE operation_id=NEW.operation_id AND state='pending' AND sealed=0)
BEGIN SELECT RAISE(ABORT,'preparation queue cannot be attached late'); END;
CREATE TRIGGER playback_start_preparation_queue_immutable BEFORE UPDATE ON playback_start_preparation_queue
BEGIN SELECT RAISE(ABORT,'preparation queue is immutable'); END;
CREATE TRIGGER playback_start_preparation_queue_delete BEFORE DELETE ON playback_start_preparation_queue
WHEN NOT EXISTS(SELECT 1 FROM playback_start_preparation_actor a
 JOIN direct_profiles p ON p.id=a.profile_id AND p.account_id=a.account_id
 JOIN direct_memberships m ON m.account_id=p.account_id
 JOIN security_purge_jobs j ON j.authority=a.authority AND j.account_id=a.account_id
  AND j.profile_id=a.profile_id AND j.profile_incarnation=p.lifetime AND j.account_incarnation=m.incarnation
 WHERE a.operation_id=OLD.operation_id AND a.authority='local' AND p.deleted=1 AND j.state IN('pending','running'))
BEGIN SELECT RAISE(ABORT,'preparation queue remains an original witness'); END;
CREATE TRIGGER playback_start_preparation_result_insert BEFORE INSERT ON playback_start_preparation_results
WHEN NOT EXISTS(
 SELECT 1 FROM playback_start_preparations p JOIN playback_start_preparation_lifecycle l ON l.operation_id=p.id
 JOIN playback_start_preparation_actor a ON a.operation_id=p.id
 JOIN playback_disc_snapshots snapshot ON snapshot.id=NEW.snapshot_id
 JOIN playback_disc_lifecycle life ON life.snapshot_id=snapshot.id
 JOIN playback_disc_snapshot_operation operation ON operation.snapshot_id=snapshot.id
 JOIN playback_v1_sessions session ON session.id=NEW.session_id
 WHERE p.id=NEW.operation_id AND l.state='prepared' AND l.sealed=1
 AND snapshot.session_id=NEW.legacy_session_id AND snapshot.generation=NEW.legacy_generation AND life.state='active' AND life.sealed=1
 AND operation.start_key_digest=p.start_key_digest AND operation.start_body_digest=p.start_body_digest
 AND session.device_id=p.device_id AND session.start_digest=p.start_body_digest
 AND session.account_id=a.account_id AND session.profile_id=a.profile_id AND session.authority=a.authority
 AND session.media_session_id=NEW.legacy_session_id AND session.media_generation=NEW.legacy_generation
)
BEGIN SELECT RAISE(ABORT,'preparation result is not its exact real accepted presentation'); END;
CREATE TRIGGER playback_start_preparation_result_immutable BEFORE UPDATE ON playback_start_preparation_results
BEGIN SELECT RAISE(ABORT,'preparation accepted result is immutable'); END;
CREATE TRIGGER playback_start_preparation_result_delete BEFORE DELETE ON playback_start_preparation_results
WHEN NOT EXISTS(SELECT 1 FROM playback_start_preparation_actor a
 JOIN direct_profiles p ON p.id=a.profile_id AND p.account_id=a.account_id
 JOIN direct_memberships m ON m.account_id=p.account_id
 JOIN security_purge_jobs j ON j.authority=a.authority AND j.account_id=a.account_id
  AND j.profile_id=a.profile_id AND j.profile_incarnation=p.lifetime AND j.account_incarnation=m.incarnation
 WHERE a.operation_id=OLD.operation_id AND a.authority='local' AND p.deleted=1 AND j.state IN('pending','running'))
BEGIN SELECT RAISE(ABORT,'preparation accepted result cannot be replaced'); END;

-- Private measured subtitles attach after PublishPendingTx seals the original
-- facts, before that pending presentation is activated. The relation itself is
-- not admission: the subtitle writer re-proves the original personal owner and
-- exact accepting presentation. No inventory/global disc facts are referenced.
CREATE TABLE playback_disc_subtitle_resources(
 snapshot_id TEXT NOT NULL REFERENCES playback_disc_snapshots(id),
 resource_id TEXT PRIMARY KEY REFERENCES subtitle_resources(id),
 stream_index INTEGER NOT NULL CHECK(stream_index>=0),
 UNIQUE(snapshot_id,stream_index),
 FOREIGN KEY(snapshot_id,stream_index) REFERENCES playback_disc_snapshot_streams(snapshot_id,stream_index)
) WITHOUT ROWID,STRICT;
CREATE INDEX playback_subtitle_pins_resource ON playback_subtitle_pins(resource_id,resource_revision);
CREATE TRIGGER playback_disc_subtitle_resource_insert BEFORE INSERT ON playback_disc_subtitle_resources
WHEN NOT EXISTS(
 SELECT 1 FROM playback_disc_snapshots snapshot
 JOIN playback_disc_lifecycle life ON life.snapshot_id=snapshot.id
 JOIN playback_disc_snapshot_source source ON source.snapshot_id=snapshot.id
 JOIN playback_disc_snapshot_streams stream ON stream.snapshot_id=snapshot.id AND stream.stream_index=NEW.stream_index
 JOIN playback_sessions session ON session.id=snapshot.session_id
 JOIN subtitle_resources resource ON resource.id=NEW.resource_id
 WHERE snapshot.id=NEW.snapshot_id AND life.state='pending' AND life.sealed=1
 AND stream.type='subtitle' AND resource.scope='personal' AND resource.deleted=0
 AND resource.source_id=source.asset_id AND resource.item_id=session.item_id
)
BEGIN SELECT RAISE(ABORT,'private disc subtitle is not an original pending measured stream'); END;
CREATE TRIGGER playback_disc_subtitle_resource_immutable BEFORE UPDATE ON playback_disc_subtitle_resources
BEGIN SELECT RAISE(ABORT,'private disc subtitle relation is immutable'); END;
CREATE TRIGGER playback_disc_subtitle_resource_identity BEFORE UPDATE OF item_id,source_id,scope,owner ON subtitle_resources
WHEN (NEW.item_id!=OLD.item_id OR NEW.source_id!=OLD.source_id OR NEW.scope!=OLD.scope OR NEW.owner!=OLD.owner)
 AND EXISTS(SELECT 1 FROM playback_disc_subtitle_resources WHERE resource_id=OLD.id)
BEGIN SELECT RAISE(ABORT,'private disc subtitle identity is immutable'); END;
CREATE TRIGGER playback_disc_subtitle_resource_delete BEFORE DELETE ON playback_disc_subtitle_resources
WHEN NOT EXISTS(SELECT 1 FROM playback_disc_lifecycle WHERE snapshot_id=OLD.snapshot_id AND state='retired')
 OR EXISTS(SELECT 1 FROM playback_disc_reader_pins WHERE snapshot_id=OLD.snapshot_id)
 OR EXISTS(SELECT 1 FROM playback_subtitle_pins WHERE resource_id=OLD.resource_id)
BEGIN SELECT RAISE(ABORT,'private disc subtitle is still retained'); END;
CREATE TRIGGER playback_disc_subtitle_resource_retire AFTER DELETE ON playback_disc_subtitle_resources
BEGIN UPDATE subtitle_resources SET deleted=1 WHERE id=OLD.resource_id AND scope='personal'; END;

-- Closed provider Security return openings. No credentials or sign-in grants.
CREATE TABLE identity_security_return_openings(
 operation_id TEXT PRIMARY KEY,
 actor_binding TEXT NOT NULL CHECK(length(actor_binding)=43),
 request_hash TEXT NOT NULL CHECK(length(request_hash)=43),
 opening_id TEXT NOT NULL,
 task_id TEXT NOT NULL,
 phase TEXT NOT NULL CHECK(phase IN('prepared','confirmed','cancelled')),
 payload TEXT NOT NULL,
 signature TEXT NOT NULL,
 expires_ms INTEGER NOT NULL,
 transaction_id TEXT NOT NULL DEFAULT '',
 code_digest TEXT NOT NULL DEFAULT '',
 confirmation_payload TEXT NOT NULL DEFAULT '',
 confirmation_signature TEXT NOT NULL DEFAULT '',
 CHECK(phase<>'prepared' OR (transaction_id='' AND code_digest='' AND confirmation_payload='' AND confirmation_signature='')),
 CHECK(phase<>'confirmed' OR (length(transaction_id)>=20 AND length(code_digest)=43 AND confirmation_payload<>'' AND confirmation_signature<>''))
) STRICT;
CREATE INDEX identity_security_return_actor ON identity_security_return_openings(actor_binding,phase);
CREATE TRIGGER identity_security_return_original_immutable BEFORE UPDATE ON identity_security_return_openings
WHEN NEW.operation_id<>OLD.operation_id OR NEW.actor_binding<>OLD.actor_binding
 OR NEW.request_hash<>OLD.request_hash OR NEW.opening_id<>OLD.opening_id OR NEW.task_id<>OLD.task_id
 OR NEW.payload<>OLD.payload OR NEW.signature<>OLD.signature OR NEW.expires_ms<>OLD.expires_ms
 OR (OLD.phase='cancelled' AND NEW.phase<>'cancelled')
 OR (OLD.phase='confirmed' AND NEW.phase NOT IN('confirmed','cancelled'))
 OR (OLD.phase<>'prepared' AND (NEW.transaction_id<>OLD.transaction_id OR NEW.code_digest<>OLD.code_digest
   OR NEW.confirmation_payload<>OLD.confirmation_payload OR NEW.confirmation_signature<>OLD.confirmation_signature))
BEGIN SELECT RAISE(ABORT,'original Security return cannot be replaced or reopened'); END;
CREATE TRIGGER identity_security_return_confirmation_complete BEFORE UPDATE ON identity_security_return_openings
WHEN NEW.phase='confirmed' AND (length(NEW.transaction_id)<20 OR length(NEW.code_digest)<>43
 OR NEW.confirmation_payload='' OR NEW.confirmation_signature='')
BEGIN SELECT RAISE(ABORT,'Security return confirmation requires its complete original tuple'); END;

-- Reverse FK keys: every foreign-key child column set leads an index (or is a rowid
-- alias or a partial index whose only exclusion is NULL child values). A parent
-- delete or cascade otherwise scans the whole child table; PERF-DB-006.
CREATE INDEX analysis_heads_result_id_fk ON analysis_heads(result_id);
CREATE INDEX asset_subtitles_sidecar_id_fk ON asset_subtitles(sidecar_id);
CREATE INDEX catalog_book_context_library_id_fk ON catalog_book_context(library_id);
CREATE INDEX console_report_events_report_id_fk ON console_report_events(report_id);
CREATE INDEX credit_owner_entries_source_row_id_entity_id_fk ON credit_owner_entries(source_row_id,entity_id);
CREATE INDEX credit_source_heads_publication_id_entity_id_provider_fk ON credit_source_heads(publication_id,entity_id,provider);
CREATE INDEX credit_source_publication_members_publication_id_entity_id_provider_fk ON credit_source_publication_members(publication_id,entity_id,provider);
CREATE INDEX credit_source_publication_members_source_row_id_entity_id_provider_fk ON credit_source_publication_members(source_row_id,entity_id,provider);
CREATE INDEX download_receipts_key_id_fk ON download_receipts(key_id);
CREATE INDEX dvr_recordings_source_id_fk ON dvr_recordings(source_id);
CREATE INDEX dvr_rules_source_id_fk ON dvr_rules(source_id);
