CREATE TRIGGER reading_path_catalog_dirty_pending_insert AFTER INSERT ON catalog_dirty WHEN NEW.domain=20 BEGIN
 INSERT OR IGNORE INTO reading_path_availability_pending SELECT id,library_id FROM catalog_entities WHERE id=NEW.entity_id AND kind IN(20,21);
END;
CREATE TRIGGER reading_path_catalog_dirty_pending_delete AFTER DELETE ON catalog_dirty WHEN OLD.domain=20 BEGIN
 DELETE FROM reading_path_availability_pending WHERE entity_id=OLD.entity_id AND NOT EXISTS(SELECT 1 FROM catalog_dirty WHERE domain=20 AND entity_id=OLD.entity_id) AND NOT EXISTS(SELECT 1 FROM catalog_derivation_failures WHERE domain=20 AND entity_id=OLD.entity_id);
END;
CREATE TRIGGER reading_path_catalog_derivation_failures_pending_insert AFTER INSERT ON catalog_derivation_failures WHEN NEW.domain=20 BEGIN
 INSERT OR IGNORE INTO reading_path_availability_pending SELECT id,library_id FROM catalog_entities WHERE id=NEW.entity_id AND kind IN(20,21);
END;
CREATE TRIGGER reading_path_catalog_derivation_failures_pending_delete AFTER DELETE ON catalog_derivation_failures WHEN OLD.domain=20 BEGIN
 DELETE FROM reading_path_availability_pending WHERE entity_id=OLD.entity_id AND NOT EXISTS(SELECT 1 FROM catalog_dirty WHERE domain=20 AND entity_id=OLD.entity_id) AND NOT EXISTS(SELECT 1 FROM catalog_derivation_failures WHERE domain=20 AND entity_id=OLD.entity_id);
END;
CREATE TRIGGER reading_path_pending_insert AFTER INSERT ON reading_path_availability_pending BEGIN
 INSERT INTO reading_path_dirty_work(library_id,kind,work_key) VALUES(NEW.library_id,'pending',CAST(NEW.entity_id AS TEXT)) ON CONFLICT(library_id,kind,work_key) DO UPDATE SET requested=requested+1;
END;
CREATE TRIGGER reading_path_pending_delete AFTER DELETE ON reading_path_availability_pending BEGIN
 INSERT INTO reading_path_dirty_work(library_id,kind,work_key) VALUES(OLD.library_id,'pending',CAST(OLD.entity_id AS TEXT)) ON CONFLICT(library_id,kind,work_key) DO UPDATE SET requested=requested+1;
END;
CREATE TRIGGER reading_path_entity_pending_delete BEFORE DELETE ON catalog_entities BEGIN
 DELETE FROM reading_path_availability_pending WHERE entity_id=OLD.id;
END;
CREATE TRIGGER reading_path_entity_pending_move AFTER UPDATE OF library_id,kind ON catalog_entities WHEN OLD.library_id IS NOT NEW.library_id OR OLD.kind IS NOT NEW.kind BEGIN
 DELETE FROM reading_path_availability_pending WHERE entity_id=OLD.id;
 INSERT OR IGNORE INTO reading_path_availability_pending SELECT NEW.id,NEW.library_id WHERE NEW.kind IN(20,21) AND (EXISTS(SELECT 1 FROM catalog_dirty WHERE domain=20 AND entity_id=NEW.id) OR EXISTS(SELECT 1 FROM catalog_derivation_failures WHERE domain=20 AND entity_id=NEW.id));
END;
CREATE TRIGGER reading_path_run_open AFTER INSERT ON inventory_runs BEGIN
 INSERT INTO reading_path_dirty_work(library_id,kind,work_key) SELECT cl.id,'coverage',NEW.source_id FROM library_sources s JOIN catalog_libraries cl ON cl.library_id=s.library_id JOIN libraries l ON l.id=s.library_id WHERE s.id=NEW.source_id AND l.kind IN('book','comic') ON CONFLICT(library_id,kind,work_key) DO UPDATE SET requested=requested+1;

 INSERT INTO reading_path_source_barrier SELECT NEW.source_id,NEW.job_id,NEW.root_incarnation,NEW.source_generation,NEW.root_identity,(SELECT root FROM library_sources WHERE id=NEW.source_id),0,0,'open','' WHERE EXISTS(SELECT 1 FROM library_sources s JOIN libraries l ON l.id=s.library_id WHERE s.id=NEW.source_id AND l.kind IN('book','comic')) ON CONFLICT(source_id) DO UPDATE SET job_id=excluded.job_id,incarnation=excluded.incarnation,source_generation=excluded.source_generation,root_identity=excluded.root_identity,root=excluded.root,coverage_revision=0,after_issue=0,phase='open',reason='';
END;
CREATE TRIGGER reading_path_run_seal AFTER UPDATE OF phase ON inventory_runs WHEN NEW.phase IN('sidecars','analysis_enqueue') AND OLD.phase IN('reconciling','verifying') BEGIN
 UPDATE reading_path_source_barrier SET phase='sealed',reason=CASE WHEN NEW.authoritative=1 THEN '' ELSE 'untrusted_coverage' END WHERE source_id=NEW.source_id AND job_id=NEW.job_id;
END;
CREATE TRIGGER reading_path_run_cancel AFTER UPDATE OF status ON jobs WHEN NEW.status IN('cancelled','failed','interrupted') BEGIN
 UPDATE reading_path_source_barrier SET phase='cancelled',reason=NEW.status WHERE job_id=NEW.id;
END;
CREATE TRIGGER reading_path_scan_report AFTER UPDATE OF status ON jobs WHEN NEW.status IN('complete','complete_with_warnings') AND OLD.status NOT IN('complete','complete_with_warnings') BEGIN
 INSERT INTO reading_path_dirty_work(library_id,kind,work_key) SELECT cl.id,'report',NEW.id FROM inventory_runs r JOIN library_sources s ON s.id=r.source_id JOIN catalog_libraries cl ON cl.library_id=s.library_id JOIN libraries l ON l.id=s.library_id WHERE r.job_id=NEW.id AND l.kind IN('book','comic') ON CONFLICT(library_id,kind,work_key) DO UPDATE SET requested=requested+1;
END;
CREATE TRIGGER reading_path_work_enqueued AFTER INSERT ON reading_path_dirty_work BEGIN
 UPDATE reading_path_dirty_work SET served=(SELECT turn FROM reading_path_clock WHERE singleton=1) WHERE library_id=NEW.library_id AND kind=NEW.kind AND work_key=NEW.work_key;
END;
CREATE TRIGGER reading_path_run_identity AFTER UPDATE OF root_identity ON inventory_runs WHEN OLD.root_identity IS NOT NEW.root_identity BEGIN
 UPDATE reading_path_source_barrier SET root_identity=NEW.root_identity WHERE source_id=NEW.source_id AND job_id=NEW.job_id AND phase='open';
END;
CREATE TRIGGER reading_path_inventory_canonical_insert AFTER INSERT ON inventory_objects WHEN EXISTS(SELECT 1 FROM library_sources s JOIN libraries l ON l.id=s.library_id WHERE s.id=NEW.source_id AND l.kind IN('book','comic')) BEGIN
 INSERT INTO reading_path_dirty_work(library_id,kind,work_key) SELECT cl.id,'asset',NEW.asset_id FROM library_sources s JOIN catalog_libraries cl ON cl.library_id=s.library_id JOIN libraries l ON l.id=s.library_id WHERE s.id=NEW.source_id AND l.kind IN('book','comic') ON CONFLICT(library_id,kind,work_key) DO UPDATE SET requested=requested+1;
