CREATE TRIGGER mb_retire_recording_parent_empty BEFORE DELETE ON mb_recording_evidence WHEN EXISTS(SELECT 1 FROM mb_recording_credits WHERE revision_id=OLD.revision_id) BEGIN SELECT RAISE(ABORT,'MusicBrainz parent requires bounded child retirement');END;
CREATE TRIGGER mb_retire_release_parent_empty BEFORE DELETE ON mb_release_evidence WHEN EXISTS(SELECT 1 FROM mb_release_credits WHERE revision_id=OLD.revision_id) OR EXISTS(SELECT 1 FROM mb_release_group_types WHERE release_revision=OLD.revision_id) OR EXISTS(SELECT 1 FROM mb_release_media WHERE release_revision=OLD.revision_id) OR EXISTS(SELECT 1 FROM mb_release_tracks WHERE release_revision=OLD.revision_id) OR EXISTS(SELECT 1 FROM mb_track_credits WHERE release_revision=OLD.revision_id) BEGIN SELECT RAISE(ABORT,'MusicBrainz parent requires bounded child retirement');END;
CREATE TRIGGER mb_retire_track_empty BEFORE DELETE ON mb_release_tracks WHEN EXISTS(SELECT 1 FROM mb_track_credits WHERE release_revision=OLD.release_revision AND track_id=OLD.track_id) BEGIN SELECT RAISE(ABORT,'MusicBrainz track requires bounded credit retirement');END;
CREATE TRIGGER mb_retire_medium_empty BEFORE DELETE ON mb_release_media WHEN EXISTS(SELECT 1 FROM mb_release_tracks WHERE release_revision=OLD.release_revision AND medium_position=OLD.position) BEGIN SELECT RAISE(ABORT,'MusicBrainz medium requires bounded track retirement');END;

CREATE INDEX mb_operations_terminal_age ON mb_publication_operations(finished_at,created_at,id) WHERE status IN('applied','stale','failed');
CREATE INDEX mb_operations_terminal_order ON mb_publication_operations(created_at DESC,id DESC) WHERE status IN('applied','stale','failed');
CREATE INDEX mb_operations_expired ON mb_publication_operations(lease_until,id) WHERE status IN('claimed','staged');
CREATE INDEX mb_release_aliases_retire ON mb_release_aliases(observed_at,requested_id,evidence_revision);
CREATE INDEX mb_recording_aliases_retire ON mb_recording_aliases(observed_at,requested_id,evidence_revision);

CREATE INDEX mb_evidence_builds_owned_due ON mb_evidence_builds(expires_at,build_id) WHERE state='ready' AND owner_operation<>'';


-- P2-52b: admitted catalog mutation custody; never query result storage.
CREATE TABLE catalog_entity_mutations(
 mutation_id TEXT PRIMARY KEY,
 generation INTEGER NOT NULL DEFAULT 1 CHECK(generation>0),
 family_id TEXT NOT NULL,
 parent_mutation_id TEXT REFERENCES catalog_entity_mutations(mutation_id) ON DELETE RESTRICT,
 owner_kind TEXT NOT NULL CHECK(owner_kind IN('title','administration','missing','library','merge','identity','mb-adoption','empty-parent')),
 owner_id TEXT NOT NULL,
 owner_generation INTEGER NOT NULL CHECK(owner_generation>0),
 entity_id INTEGER REFERENCES catalog_entities(id) ON DELETE RESTRICT,
 subject_id INTEGER NOT NULL,
 public_id TEXT NOT NULL,
 entity_kind INTEGER NOT NULL,
 library_id INTEGER NOT NULL,
 entity_incarnation TEXT NOT NULL,
 publication_incarnation TEXT NOT NULL,
 source_digest TEXT NOT NULL,
 target_id INTEGER REFERENCES catalog_entities(id) ON DELETE RESTRICT,
 target_subject_id INTEGER NOT NULL DEFAULT 0,
 target_public_id TEXT NOT NULL DEFAULT '',
 target_incarnation TEXT NOT NULL DEFAULT '',
 target_publication_incarnation TEXT NOT NULL DEFAULT '',
 subject_ancestor_1 INTEGER REFERENCES catalog_entities(id) ON DELETE RESTRICT,
 subject_ancestor_2 INTEGER REFERENCES catalog_entities(id) ON DELETE RESTRICT,
 subject_ancestor_3 INTEGER REFERENCES catalog_entities(id) ON DELETE RESTRICT,
 subject_ancestor_4 INTEGER REFERENCES catalog_entities(id) ON DELETE RESTRICT,
 target_ancestor_1 INTEGER REFERENCES catalog_entities(id) ON DELETE RESTRICT,
 target_ancestor_2 INTEGER REFERENCES catalog_entities(id) ON DELETE RESTRICT,
 target_ancestor_3 INTEGER REFERENCES catalog_entities(id) ON DELETE RESTRICT,
 target_ancestor_4 INTEGER REFERENCES catalog_entities(id) ON DELETE RESTRICT,
 mode TEXT NOT NULL CHECK(mode IN('remove','members','force','merge','adopt')),
 phase TEXT NOT NULL CHECK(phase IN('admitted','children','drain','finalize','album-identity','artist-identity','terminal')),
 status TEXT NOT NULL DEFAULT 'active' CHECK(status IN('active','blocked','waiting','terminal')),
 outcome TEXT NOT NULL DEFAULT 'pending' CHECK(outcome IN('pending','removed','retained','merged','stale','blocked')),
 cursor INTEGER NOT NULL DEFAULT 0,
 current_child TEXT REFERENCES catalog_entity_mutations(mutation_id) ON DELETE RESTRICT,
 current_key INTEGER NOT NULL DEFAULT 0,
 provider TEXT NOT NULL DEFAULT '',
 provider_kind TEXT NOT NULL DEFAULT '',
 provider_id TEXT NOT NULL DEFAULT '',
 accepted_revision TEXT NOT NULL DEFAULT '',
 cause_operation TEXT NOT NULL DEFAULT '',
 acknowledged INTEGER NOT NULL DEFAULT 0 CHECK(acknowledged IN(0,1)),
 child_count INTEGER NOT NULL DEFAULT 0 CHECK(child_count>=0),
 CHECK(owner_kind<>'empty-parent' OR (entity_kind=2 AND mode='members' AND parent_mutation_id IS NULL AND target_id IS NULL AND target_subject_id=0 AND target_public_id='' AND target_incarnation='' AND target_publication_incarnation='' AND current_child IS NULL AND cause_operation='empty-show' AND provider='' AND provider_kind='' AND provider_id='' AND accepted_revision='' AND owner_id=public_id AND public_id<>'' AND phase IN('admitted','finalize','terminal') AND status IN('active','terminal'))),
 CHECK(status<>'waiting' OR (owner_kind='mb-adoption' AND mode='adopt' AND phase='artist-identity' AND entity_kind=6 AND parent_mutation_id IS NULL AND target_id IS NULL AND current_child IS NULL AND provider='musicbrainz' AND provider_kind='release' AND accepted_revision<>'' AND cause_operation<>'' AND public_id<>'' AND entity_incarnation<>'' AND subject_ancestor_1 IS NOT NULL)),
 CHECK((status='terminal' AND phase='terminal' AND entity_id IS NULL AND target_id IS NULL AND outcome<>'pending') OR
       (status<>'terminal' AND entity_id IS NOT NULL AND phase<>'terminal'))
) STRICT;
CREATE UNIQUE INDEX catalog_entity_mutations_subject ON catalog_entity_mutations(entity_id) WHERE status<>'terminal' AND mode<>'adopt';
CREATE UNIQUE INDEX catalog_entity_mutations_owner ON catalog_entity_mutations(owner_kind,owner_id,owner_generation,subject_id,mode);
CREATE INDEX catalog_entity_mutations_target ON catalog_entity_mutations(target_id,family_id) WHERE status<>'terminal';
CREATE INDEX catalog_entity_mutations_runnable ON catalog_entity_mutations(status,owner_kind,mutation_id);
CREATE INDEX catalog_entity_mutations_parent ON catalog_entity_mutations(parent_mutation_id);
CREATE INDEX catalog_entity_mutations_family ON catalog_entity_mutations(family_id,status);
CREATE TRIGGER catalog_entity_pin_free_delete BEFORE DELETE ON catalog_entities
 WHEN EXISTS(SELECT 1 FROM mb_song_links WHERE item_id=OLD.id) OR EXISTS(SELECT 1 FROM mb_album_links WHERE album_id=OLD.id)
 BEGIN SELECT RAISE(ABORT,'catalog entity still has MusicBrainz pins'); END;
CREATE TRIGGER mb_song_links_catalog_mutation_insert BEFORE INSERT ON mb_song_links
 WHEN EXISTS(WITH RECURSIVE ancestors(id,depth) AS (
 SELECT NEW.item_id,0 UNION ALL SELECT e.parent_id,a.depth+1 FROM ancestors a JOIN catalog_entities e ON e.id=a.id WHERE e.parent_id IS NOT NULL AND a.depth<4)
 SELECT 1 FROM ancestors a JOIN catalog_entity_mutations m ON (m.entity_id=a.id OR m.target_id=a.id) WHERE m.status<>'terminal') BEGIN SELECT RAISE(ABORT,'catalog entity mutation fences MusicBrainz acquisition'); END;
CREATE TRIGGER mb_song_links_catalog_mutation_update BEFORE UPDATE ON mb_song_links
 WHEN EXISTS(WITH RECURSIVE ancestors(id,depth) AS (
 SELECT NEW.item_id,0 UNION ALL SELECT e.parent_id,a.depth+1 FROM ancestors a JOIN catalog_entities e ON e.id=a.id WHERE e.parent_id IS NOT NULL AND a.depth<4)
 SELECT 1 FROM ancestors a JOIN catalog_entity_mutations m ON (m.entity_id=a.id OR m.target_id=a.id) WHERE m.status<>'terminal') BEGIN SELECT RAISE(ABORT,'catalog entity mutation fences MusicBrainz acquisition'); END;
CREATE TRIGGER mb_album_links_catalog_mutation_insert BEFORE INSERT ON mb_album_links
 WHEN EXISTS(WITH RECURSIVE ancestors(id,depth) AS (
 SELECT NEW.album_id,0 UNION ALL SELECT e.parent_id,a.depth+1 FROM ancestors a JOIN catalog_entities e ON e.id=a.id WHERE e.parent_id IS NOT NULL AND a.depth<4)
 SELECT 1 FROM ancestors a JOIN catalog_entity_mutations m ON (m.entity_id=a.id OR m.target_id=a.id) WHERE m.status<>'terminal') BEGIN SELECT RAISE(ABORT,'catalog entity mutation fences MusicBrainz acquisition'); END;
CREATE TRIGGER mb_album_links_catalog_mutation_update BEFORE UPDATE ON mb_album_links
 WHEN EXISTS(WITH RECURSIVE ancestors(id,depth) AS (
 SELECT NEW.album_id,0 UNION ALL SELECT e.parent_id,a.depth+1 FROM ancestors a JOIN catalog_entities e ON e.id=a.id WHERE e.parent_id IS NOT NULL AND a.depth<4)
 SELECT 1 FROM ancestors a JOIN catalog_entity_mutations m ON (m.entity_id=a.id OR m.target_id=a.id) WHERE m.status<>'terminal') BEGIN SELECT RAISE(ABORT,'catalog entity mutation fences MusicBrainz acquisition'); END;

CREATE INDEX catalog_entity_mutations_entity_fk ON catalog_entity_mutations(entity_id);

CREATE INDEX catalog_entity_mutations_target_fk ON catalog_entity_mutations(target_id);

CREATE INDEX catalog_entity_mutations_child_fk ON catalog_entity_mutations(current_child);

CREATE INDEX catalog_entity_mutations_subject_ancestor_1_fk ON catalog_entity_mutations(subject_ancestor_1,status,family_id);

CREATE INDEX catalog_entity_mutations_subject_ancestor_2_fk ON catalog_entity_mutations(subject_ancestor_2,status,family_id);

CREATE INDEX catalog_entity_mutations_subject_ancestor_3_fk ON catalog_entity_mutations(subject_ancestor_3,status,family_id);

CREATE INDEX catalog_entity_mutations_subject_ancestor_4_fk ON catalog_entity_mutations(subject_ancestor_4,status,family_id);

CREATE INDEX catalog_entity_mutations_target_ancestor_1_fk ON catalog_entity_mutations(target_ancestor_1,status,family_id);

CREATE INDEX catalog_entity_mutations_target_ancestor_2_fk ON catalog_entity_mutations(target_ancestor_2,status,family_id);

CREATE INDEX catalog_entity_mutations_target_ancestor_3_fk ON catalog_entity_mutations(target_ancestor_3,status,family_id);

CREATE INDEX catalog_entity_mutations_target_ancestor_4_fk ON catalog_entity_mutations(target_ancestor_4,status,family_id);

CREATE INDEX catalog_entity_mutations_provider ON catalog_entity_mutations(provider,provider_kind,provider_id,library_id,entity_kind,family_id) WHERE status<>'terminal' AND mode='adopt';

-- P2-52b bounded custody acknowledgement and indexed member progress.
CREATE INDEX catalog_entity_mutations_gc_leaf ON catalog_entity_mutations(status,acknowledged,child_count,mutation_id);
CREATE INDEX catalog_entity_mutations_ack_roots ON catalog_entity_mutations(status,acknowledged,parent_mutation_id,mutation_id);
CREATE TRIGGER catalog_entity_mutations_child_join AFTER INSERT ON catalog_entity_mutations WHEN NEW.parent_mutation_id IS NOT NULL BEGIN UPDATE catalog_entity_mutations SET child_count=child_count+1 WHERE mutation_id=NEW.parent_mutation_id; END;
CREATE TRIGGER catalog_entity_mutations_child_leave AFTER DELETE ON catalog_entity_mutations WHEN OLD.parent_mutation_id IS NOT NULL BEGIN UPDATE catalog_entity_mutations SET child_count=child_count-1 WHERE mutation_id=OLD.parent_mutation_id; END;
CREATE TRIGGER catalog_entity_mutations_parent_immutable BEFORE UPDATE OF parent_mutation_id ON catalog_entity_mutations WHEN OLD.parent_mutation_id IS NOT NEW.parent_mutation_id BEGIN SELECT RAISE(ABORT,'immutable catalog mutation parent'); END;
CREATE INDEX catalog_songs_album_entity ON catalog_songs(album_id,entity_id);
CREATE INDEX catalog_book_files_book_entity ON catalog_book_files(book_id,entity_id);
CREATE INDEX catalog_episodes_show_entity ON catalog_episodes(show_id,entity_id);
CREATE INDEX catalog_episodes_season_entity ON catalog_episodes(season_id,entity_id) WHERE season_id IS NOT NULL;
CREATE INDEX catalog_seasons_show_entity ON catalog_seasons(show_id,entity_id);

CREATE INDEX catalog_entity_mutations_parent_key ON catalog_entity_mutations(parent_mutation_id,mutation_id);

-- Exact command owner/member keys; independent of unrelated custody history.
CREATE INDEX catalog_entity_mutations_command_root ON catalog_entity_mutations(owner_kind,owner_id,owner_generation,mutation_id) WHERE parent_mutation_id IS NULL;
CREATE INDEX catalog_entity_mutations_command_public ON catalog_entity_mutations(owner_kind,owner_id,public_id,mode,owner_generation DESC,mutation_id);
CREATE INDEX catalog_entity_mutations_command_subject ON catalog_entity_mutations(owner_kind,owner_id,subject_id,mode,owner_generation DESC,mutation_id);

-- Narrow album-to-artist identity handoff; no outgoing mutation exemption.
CREATE UNIQUE INDEX catalog_entity_mutations_artist_identity ON catalog_entity_mutations(library_id,provider,provider_kind,provider_id) WHERE entity_kind=5 AND owner_kind='identity' AND mode='adopt' AND parent_mutation_id IS NULL AND status IN('active','blocked');
CREATE TRIGGER catalog_entity_mutations_wait_binding BEFORE UPDATE OF status,phase,entity_id,public_id,entity_incarnation,subject_ancestor_1 ON catalog_entity_mutations WHEN NEW.status='waiting' AND NOT EXISTS(SELECT 1 FROM catalog_entities e JOIN catalog_albums a ON a.entity_id=e.id JOIN catalog_entities artist ON artist.id=a.artist_id AND artist.kind=5 AND artist.library_id=e.library_id JOIN mb_album_heads h ON h.album_id=e.id WHERE e.id=NEW.entity_id AND e.kind=6 AND pid(e.public_id)=NEW.public_id AND h.incarnation=NEW.entity_incarnation AND e.parent_id=NEW.subject_ancestor_1 AND a.artist_id=NEW.subject_ancestor_1) BEGIN SELECT RAISE(ABORT,'stale catalog artist handoff binding'); END;
CREATE TRIGGER catalog_entity_mutations_wait_parent BEFORE UPDATE OF parent_id ON catalog_entities WHEN OLD.parent_id IS NOT NEW.parent_id AND EXISTS(SELECT 1 FROM catalog_entity_mutations WHERE entity_id=OLD.id AND status='waiting') BEGIN SELECT RAISE(ABORT,'catalog artist handoff retains album parent'); END;
CREATE TRIGGER catalog_entity_mutations_wait_artist BEFORE UPDATE OF artist_id ON catalog_albums WHEN OLD.artist_id IS NOT NEW.artist_id AND EXISTS(SELECT 1 FROM catalog_entity_mutations WHERE entity_id=OLD.entity_id AND status='waiting') BEGIN SELECT RAISE(ABORT,'catalog artist handoff retains album artist'); END;
CREATE TRIGGER catalog_entity_mutations_wait_binding_insert BEFORE INSERT ON catalog_entity_mutations WHEN NEW.status='waiting' AND NOT EXISTS(SELECT 1 FROM catalog_entities e JOIN catalog_albums a ON a.entity_id=e.id JOIN catalog_entities artist ON artist.id=a.artist_id AND artist.kind=5 AND artist.library_id=e.library_id JOIN mb_album_heads h ON h.album_id=e.id WHERE e.id=NEW.entity_id AND e.kind=6 AND pid(e.public_id)=NEW.public_id AND h.incarnation=NEW.entity_incarnation AND e.parent_id=NEW.subject_ancestor_1 AND a.artist_id=NEW.subject_ancestor_1) BEGIN SELECT RAISE(ABORT,'stale catalog artist handoff binding'); END;

CREATE INDEX catalog_entity_mutations_automatic_missing ON catalog_entity_mutations(library_id,mutation_id) WHERE owner_kind='missing' AND cause_operation='automatic-missing' AND status='active' AND parent_mutation_id IS NULL;

-- P2-28 normalized maintained facet base facts: begin
CREATE TABLE catalog_facet_base_usage (
 id INTEGER PRIMARY KEY CHECK(id=1), used_bytes INTEGER NOT NULL DEFAULT 0 CHECK(used_bytes>=0)
) STRICT;
INSERT INTO catalog_facet_base_usage(id) VALUES(1);
-- Library-lifetime accepted target high-water, shared by every genre class.
-- Retained until library deletion; the fixed 128-byte charge includes its key.
CREATE TABLE catalog_search_genre_accepted_targets (
 library_id INTEGER PRIMARY KEY REFERENCES catalog_libraries(id) ON DELETE CASCADE,
 max_entity_id INTEGER NOT NULL CHECK(max_entity_id>=0)
) STRICT;
CREATE TRIGGER catalog_search_genre_accepted_targets_insert AFTER INSERT ON catalog_search_genre_accepted_targets BEGIN
 UPDATE catalog_facet_base_usage SET used_bytes=used_bytes+128 WHERE id=1;
END;
CREATE TRIGGER catalog_search_genre_accepted_targets_delete AFTER DELETE ON catalog_search_genre_accepted_targets BEGIN
 UPDATE catalog_facet_base_usage SET used_bytes=used_bytes-128 WHERE id=1;
END;
CREATE TABLE catalog_facet_base_classes (
 id INTEGER PRIMARY KEY AUTOINCREMENT,
 library_id INTEGER NOT NULL, library TEXT NOT NULL, field TEXT NOT NULL,
 policy TEXT NOT NULL, source TEXT NOT NULL, active_base INTEGER,
 FOREIGN KEY(active_base,id) REFERENCES catalog_facet_bases(id,class_id) DEFERRABLE INITIALLY DEFERRED,
 UNIQUE(library_id,field,policy,source)
) STRICT;
CREATE INDEX catalog_facet_base_classes_active ON catalog_facet_base_classes(active_base,id);
CREATE TABLE catalog_facet_base_values (
 id INTEGER PRIMARY KEY AUTOINCREMENT, library_id INTEGER NOT NULL, field TEXT NOT NULL,
 value TEXT NOT NULL CHECK(value<>''), UNIQUE(library_id,field,value)
) STRICT;
CREATE TABLE catalog_facet_base_texts (
 id INTEGER PRIMARY KEY AUTOINCREMENT,
 value_id INTEGER NOT NULL REFERENCES catalog_facet_base_values(id),
 label TEXT NOT NULL, folded TEXT NOT NULL, UNIQUE(value_id,label), UNIQUE(id,value_id)
) STRICT;
CREATE TABLE catalog_facet_bases (
 id INTEGER PRIMARY KEY AUTOINCREMENT,
 class_id INTEGER NOT NULL REFERENCES catalog_facet_base_classes(id),
 witness TEXT NOT NULL, authority TEXT NOT NULL, complete INTEGER NOT NULL DEFAULT 0 CHECK(complete IN(0,1)),
 total INTEGER NOT NULL DEFAULT 0 CHECK(total>=0),
 charged_bytes INTEGER NOT NULL DEFAULT 0 CHECK(charged_bytes>=0), UNIQUE(id,class_id)
) STRICT;
CREATE INDEX catalog_facet_bases_class ON catalog_facet_bases(class_id,id);
CREATE INDEX catalog_facet_bases_demand ON catalog_facet_bases(class_id,witness,authority,id);
CREATE TABLE catalog_facet_base_rows (
 base_id INTEGER NOT NULL REFERENCES catalog_facet_bases(id),
 value_id INTEGER NOT NULL REFERENCES catalog_facet_base_values(id),
 text_id INTEGER NOT NULL,
 negative_count INTEGER NOT NULL CHECK(negative_count<0),
 label_order TEXT NOT NULL COLLATE BINARY, value_order TEXT NOT NULL COLLATE BINARY,
 charged_bytes INTEGER NOT NULL CHECK(charged_bytes>0),
 PRIMARY KEY(base_id,value_id),
 FOREIGN KEY(text_id,value_id) REFERENCES catalog_facet_base_texts(id,value_id)
) STRICT, WITHOUT ROWID;
CREATE INDEX catalog_facet_base_order ON catalog_facet_base_rows(base_id,negative_count,label_order,value_order,value_id);
CREATE INDEX catalog_facet_base_rows_value ON catalog_facet_base_rows(value_id);
CREATE INDEX catalog_facet_base_rows_text ON catalog_facet_base_rows(text_id,value_id);
CREATE TABLE catalog_facet_base_work (
 base_id INTEGER PRIMARY KEY REFERENCES catalog_facet_bases(id), cursor TEXT NOT NULL
) STRICT;
CREATE TRIGGER catalog_facet_base_row_insert AFTER INSERT ON catalog_facet_base_rows BEGIN
 UPDATE catalog_facet_bases SET total=total+1,charged_bytes=charged_bytes+NEW.charged_bytes WHERE id=NEW.base_id;
 UPDATE catalog_facet_base_usage SET used_bytes=used_bytes+NEW.charged_bytes WHERE id=1;
END;
CREATE TRIGGER catalog_facet_base_row_delete AFTER DELETE ON catalog_facet_base_rows BEGIN
 UPDATE catalog_facet_bases SET total=total-1,charged_bytes=charged_bytes-OLD.charged_bytes WHERE id=OLD.base_id;
 UPDATE catalog_facet_base_usage SET used_bytes=used_bytes-OLD.charged_bytes WHERE id=1;
END;
CREATE TRIGGER catalog_facet_base_value_insert AFTER INSERT ON catalog_facet_base_values BEGIN
 UPDATE catalog_facet_base_usage SET used_bytes=used_bytes+64+2*length(CAST(NEW.value AS BLOB)) WHERE id=1;
END;
CREATE TRIGGER catalog_facet_base_value_delete AFTER DELETE ON catalog_facet_base_values BEGIN
 UPDATE catalog_facet_base_usage SET used_bytes=used_bytes-64-2*length(CAST(OLD.value AS BLOB)) WHERE id=1;
END;
CREATE TRIGGER catalog_facet_base_text_insert AFTER INSERT ON catalog_facet_base_texts BEGIN
 UPDATE catalog_facet_base_usage SET used_bytes=used_bytes+64+2*length(CAST(NEW.label AS BLOB))+length(CAST(NEW.folded AS BLOB)) WHERE id=1;
END;
CREATE TRIGGER catalog_facet_base_text_delete AFTER DELETE ON catalog_facet_base_texts BEGIN
 UPDATE catalog_facet_base_usage SET used_bytes=used_bytes-64-2*length(CAST(OLD.label AS BLOB))-length(CAST(OLD.folded AS BLOB)) WHERE id=1;
END;
-- COMPLETE bases/texts are immutable. Only bounded retirement may remove rows;
-- readers revalidate basis existence and live authority after composition.
-- Deliberately no ON DELETE CASCADE through this potentially large projection.

CREATE TRIGGER catalog_facet_base_row_immutable_insert BEFORE INSERT ON catalog_facet_base_rows
WHEN (SELECT complete FROM catalog_facet_bases WHERE id=NEW.base_id)=1 BEGIN SELECT RAISE(ABORT,'immutable complete facet base'); END;
CREATE TRIGGER catalog_facet_base_row_immutable_update BEFORE UPDATE ON catalog_facet_base_rows
BEGIN SELECT RAISE(ABORT,'replace staged facet rows instead of updating'); END;
CREATE TRIGGER catalog_facet_base_row_immutable_delete BEFORE DELETE ON catalog_facet_base_rows
WHEN (SELECT complete FROM catalog_facet_bases WHERE id=OLD.base_id)=1 BEGIN SELECT RAISE(ABORT,'retire facet base before removing rows'); END;
CREATE TRIGGER catalog_facet_base_text_immutable BEFORE UPDATE ON catalog_facet_base_texts
WHEN NEW.value_id<>OLD.value_id OR NEW.label<>OLD.label OR NEW.folded<>OLD.folded
BEGIN SELECT RAISE(ABORT,'immutable shared facet text'); END;
CREATE TRIGGER catalog_facet_base_value_immutable BEFORE UPDATE ON catalog_facet_base_values
WHEN NEW.library_id<>OLD.library_id OR NEW.field<>OLD.field OR NEW.value<>OLD.value
BEGIN SELECT RAISE(ABORT,'immutable shared facet identity'); END;
-- active_base is a deferred composite FK back to this class's own base; NULL
-- means unavailable. Activation and complete flip are in one transaction.
-- RetireStep refuses active bases, marks retained input incomplete before bounded
-- removal, and live/basis readback makes racing or evicted preparations stale.
CREATE TRIGGER catalog_facet_base_class_identity BEFORE UPDATE OF library_id,library,field,policy,source ON catalog_facet_base_classes
WHEN NEW.library_id<>OLD.library_id OR NEW.library<>OLD.library OR NEW.field<>OLD.field OR NEW.policy<>OLD.policy OR NEW.source<>OLD.source
BEGIN SELECT RAISE(ABORT,'immutable facet class identity'); END;
CREATE TRIGGER catalog_facet_base_active_complete BEFORE UPDATE OF active_base ON catalog_facet_base_classes
WHEN NEW.active_base IS NOT NULL AND NOT EXISTS(SELECT 1 FROM catalog_facet_bases WHERE id=NEW.active_base AND class_id=NEW.id AND complete=1)
BEGIN SELECT RAISE(ABORT,'facet activation requires own COMPLETE base'); END;
CREATE TRIGGER catalog_facet_base_image_identity BEFORE UPDATE OF class_id,witness,authority ON catalog_facet_bases
WHEN NEW.class_id<>OLD.class_id OR NEW.witness<>OLD.witness OR NEW.authority<>OLD.authority
BEGIN SELECT RAISE(ABORT,'immutable facet base image'); END;
CREATE TRIGGER catalog_facet_base_class_charge_insert AFTER INSERT ON catalog_facet_base_classes BEGIN
 UPDATE catalog_facet_base_usage SET used_bytes=used_bytes+192+length(CAST(NEW.library AS BLOB))+length(CAST(NEW.field AS BLOB))+length(CAST(NEW.policy AS BLOB))+length(CAST(NEW.source AS BLOB)) WHERE id=1;
END;
CREATE TRIGGER catalog_facet_base_class_charge_delete AFTER DELETE ON catalog_facet_base_classes BEGIN
 UPDATE catalog_facet_base_usage SET used_bytes=used_bytes-192-length(CAST(OLD.library AS BLOB))-length(CAST(OLD.field AS BLOB))-length(CAST(OLD.policy AS BLOB))-length(CAST(OLD.source AS BLOB)) WHERE id=1;
END;
CREATE TRIGGER catalog_facet_base_image_charge_insert AFTER INSERT ON catalog_facet_bases BEGIN
 UPDATE catalog_facet_base_usage SET used_bytes=used_bytes+192+length(CAST(NEW.witness AS BLOB))+length(CAST(NEW.authority AS BLOB)) WHERE id=1;
END;
CREATE TRIGGER catalog_facet_base_image_charge_delete AFTER DELETE ON catalog_facet_bases BEGIN
 UPDATE catalog_facet_base_usage SET used_bytes=used_bytes-192-length(CAST(OLD.witness AS BLOB))-length(CAST(OLD.authority AS BLOB)) WHERE id=1;
END;
CREATE TRIGGER catalog_facet_base_work_charge_insert AFTER INSERT ON catalog_facet_base_work BEGIN
 UPDATE catalog_facet_base_usage SET used_bytes=used_bytes+128+length(CAST(NEW.cursor AS BLOB)) WHERE id=1;
END;
CREATE TRIGGER catalog_facet_base_work_charge_delete AFTER DELETE ON catalog_facet_base_work BEGIN
 UPDATE catalog_facet_base_usage SET used_bytes=used_bytes-128-length(CAST(OLD.cursor AS BLOB)) WHERE id=1;
END;

CREATE TRIGGER catalog_facet_base_work_charge_update AFTER UPDATE OF cursor ON catalog_facet_base_work BEGIN
 UPDATE catalog_facet_base_usage SET used_bytes=used_bytes+length(CAST(NEW.cursor AS BLOB))-length(CAST(OLD.cursor AS BLOB)) WHERE id=1;
END;
-- SOURCE-INTEGRATION EXTENSIONS (existing baseline tables).
-- P2-28 normalized maintained facet base facts: end

-- P2-28 facet source membership stamps: begin
-- Linked-decade BASE inputs must have an accepting stamp even if a future
-- browse producer writes memberships without touching its existing work key.
CREATE TRIGGER catalog_facet_base_membership_source_insert AFTER INSERT ON catalog_browse_memberships BEGIN
 UPDATE catalog_facet_source_state SET source_epoch=source_epoch+1 WHERE singleton=1;
END;
CREATE TRIGGER catalog_facet_base_membership_source_update AFTER UPDATE ON catalog_browse_memberships BEGIN
 UPDATE catalog_facet_source_state SET source_epoch=source_epoch+1 WHERE singleton=1;
END;
CREATE TRIGGER catalog_facet_base_membership_source_delete AFTER DELETE ON catalog_browse_memberships BEGIN
 UPDATE catalog_facet_source_state SET source_epoch=source_epoch+1 WHERE singleton=1;
END;

-- P2-28 facet source membership stamps: end

-- Scan admission is an existing source fact, never a query job.
CREATE INDEX catalog_facet_active_scans ON jobs(id) WHERE status IN('queued','running');

-- P2-28 maintained genre candidates: begin
-- Parent integrates into baseline after shared facet base schema. BASE facts only.
CREATE TABLE catalog_search_genre_state(singleton INTEGER PRIMARY KEY CHECK(singleton=1),art_epoch INTEGER NOT NULL DEFAULT 1) STRICT;
INSERT INTO catalog_search_genre_state(singleton) VALUES(1);
CREATE TABLE catalog_search_genre_ready(
 base_id INTEGER NOT NULL REFERENCES catalog_facet_bases(id),value_id INTEGER NOT NULL REFERENCES catalog_facet_base_values(id),
 last_target INTEGER NOT NULL DEFAULT 0,backdrops INTEGER NOT NULL DEFAULT 0 CHECK(backdrops BETWEEN 0 AND 100),posters INTEGER NOT NULL DEFAULT 0 CHECK(posters BETWEEN 0 AND 100),
 PRIMARY KEY(base_id,value_id)) STRICT, WITHOUT ROWID;
CREATE INDEX catalog_search_genre_ready_value ON catalog_search_genre_ready(value_id,base_id);
-- Only top100 per value/role. Positions have gaps for bounded insertion. No
-- full-catalogue candidate/order index, duplicated title or serialized art DTO.
CREATE TABLE catalog_search_genre_targets(
 base_id INTEGER NOT NULL REFERENCES catalog_facet_bases(id),entity_id INTEGER NOT NULL,
 public_id BLOB NOT NULL CHECK(length(public_id)=16),kind INTEGER NOT NULL CHECK(kind IN(1,2)),rating REAL NOT NULL,sort_key TEXT NOT NULL,
 backdrop BLOB CHECK(backdrop IS NULL OR length(backdrop)=32),poster BLOB CHECK(poster IS NULL OR length(poster)=32),
 PRIMARY KEY(base_id,entity_id)) STRICT, WITHOUT ROWID;
CREATE TABLE catalog_search_genre_candidates(
 base_id INTEGER NOT NULL,value_id INTEGER NOT NULL,role INTEGER NOT NULL CHECK(role IN(1,2)),position INTEGER NOT NULL CHECK(position<>0),entity_id INTEGER NOT NULL,
 PRIMARY KEY(base_id,value_id,role,position),
 FOREIGN KEY(base_id,value_id) REFERENCES catalog_search_genre_ready(base_id,value_id),
 FOREIGN KEY(base_id,entity_id) REFERENCES catalog_search_genre_targets(base_id,entity_id)) STRICT, WITHOUT ROWID;
CREATE INDEX catalog_search_genre_candidate_target ON catalog_search_genre_candidates(base_id,entity_id,value_id,role,position);
CREATE TRIGGER catalog_search_genre_target_charge_insert AFTER INSERT ON catalog_search_genre_targets BEGIN
 UPDATE catalog_facet_base_usage SET used_bytes=used_bytes+256+2*length(CAST(NEW.sort_key AS BLOB)) WHERE id=1;
END;
CREATE TRIGGER catalog_search_genre_target_charge_delete AFTER DELETE ON catalog_search_genre_targets BEGIN
 UPDATE catalog_facet_base_usage SET used_bytes=used_bytes-256-2*length(CAST(OLD.sort_key AS BLOB)) WHERE id=1;
END;
CREATE TRIGGER catalog_search_genre_ready_charge_insert AFTER INSERT ON catalog_search_genre_ready BEGIN
 UPDATE catalog_facet_base_usage SET used_bytes=used_bytes+80 WHERE id=1;
END;
CREATE TRIGGER catalog_search_genre_ready_charge_delete AFTER DELETE ON catalog_search_genre_ready BEGIN
 UPDATE catalog_facet_base_usage SET used_bytes=used_bytes-80 WHERE id=1;
END;
CREATE TRIGGER catalog_search_genre_candidate_insert AFTER INSERT ON catalog_search_genre_candidates BEGIN
 UPDATE catalog_search_genre_ready SET backdrops=backdrops+(NEW.role=1),posters=posters+(NEW.role=2) WHERE base_id=NEW.base_id AND value_id=NEW.value_id;
 UPDATE catalog_facet_base_usage SET used_bytes=used_bytes+96 WHERE id=1;
END;
CREATE TRIGGER catalog_search_genre_candidate_delete AFTER DELETE ON catalog_search_genre_candidates BEGIN
 UPDATE catalog_search_genre_ready SET backdrops=backdrops-(OLD.role=1),posters=posters-(OLD.role=2) WHERE base_id=OLD.base_id AND value_id=OLD.value_id;
 UPDATE catalog_facet_base_usage SET used_bytes=used_bytes-96 WHERE id=1;
END;
CREATE TRIGGER catalog_search_genre_candidate_limit BEFORE INSERT ON catalog_search_genre_candidates
WHEN (SELECT count(*) FROM catalog_search_genre_candidates WHERE base_id=NEW.base_id AND value_id=NEW.value_id AND role=NEW.role)>=100
BEGIN SELECT RAISE(ABORT,'genre top candidate bound'); END;
CREATE TRIGGER catalog_search_genre_candidate_immutable_insert BEFORE INSERT ON catalog_search_genre_candidates
WHEN (SELECT complete FROM catalog_facet_bases WHERE id=NEW.base_id)=1 BEGIN SELECT RAISE(ABORT,'immutable genre base'); END;
CREATE TRIGGER catalog_search_genre_candidate_immutable_update BEFORE UPDATE ON catalog_search_genre_candidates
WHEN (SELECT complete FROM catalog_facet_bases WHERE id=OLD.base_id)=1 BEGIN SELECT RAISE(ABORT,'immutable genre base'); END;
CREATE TRIGGER catalog_search_genre_candidate_immutable_delete BEFORE DELETE ON catalog_search_genre_candidates
WHEN (SELECT complete FROM catalog_facet_bases WHERE id=OLD.base_id)=1 BEGIN SELECT RAISE(ABORT,'retire genre base before removing art'); END;
CREATE TRIGGER catalog_search_genre_art_selection_insert AFTER INSERT ON artwork_selections BEGIN UPDATE catalog_search_genre_state SET art_epoch=art_epoch+1 WHERE singleton=1; END;
CREATE TRIGGER catalog_search_genre_art_selection_update AFTER UPDATE ON artwork_selections BEGIN UPDATE catalog_search_genre_state SET art_epoch=art_epoch+1 WHERE singleton=1; END;
CREATE TRIGGER catalog_search_genre_art_selection_delete AFTER DELETE ON artwork_selections BEGIN UPDATE catalog_search_genre_state SET art_epoch=art_epoch+1 WHERE singleton=1; END;
CREATE TRIGGER catalog_search_genre_art_source_insert AFTER INSERT ON artwork_sources BEGIN UPDATE catalog_search_genre_state SET art_epoch=art_epoch+1 WHERE singleton=1; END;
CREATE TRIGGER catalog_search_genre_art_source_update AFTER UPDATE ON artwork_sources BEGIN UPDATE catalog_search_genre_state SET art_epoch=art_epoch+1 WHERE singleton=1; END;
CREATE TRIGGER catalog_search_genre_art_source_delete AFTER DELETE ON artwork_sources BEGIN UPDATE catalog_search_genre_state SET art_epoch=art_epoch+1 WHERE singleton=1; END;
CREATE TRIGGER catalog_search_genre_art_blob_insert AFTER INSERT ON artwork_blobs BEGIN UPDATE catalog_search_genre_state SET art_epoch=art_epoch+1 WHERE singleton=1; END;
CREATE TRIGGER catalog_search_genre_art_blob_update AFTER UPDATE ON artwork_blobs BEGIN UPDATE catalog_search_genre_state SET art_epoch=art_epoch+1 WHERE singleton=1; END;
CREATE TRIGGER catalog_search_genre_art_blob_delete AFTER DELETE ON artwork_blobs BEGIN UPDATE catalog_search_genre_state SET art_epoch=art_epoch+1 WHERE singleton=1; END;
-- Rank changes affect representative choice even when genres/visibility do not.
CREATE TRIGGER catalog_search_genre_rank_update AFTER UPDATE OF rating_max,sort_key ON catalog_browse_rows
WHEN OLD.rating_max IS NOT NEW.rating_max OR OLD.sort_key IS NOT NEW.sort_key
BEGIN UPDATE catalog_search_genre_state SET art_epoch=art_epoch+1 WHERE singleton=1; END;
-- Distinct-value directory walk, not a holder/candidate graph. Integer progress
-- survives orphan GC; captured ID high water makes content inserts finite.
CREATE INDEX catalog_search_genre_value_walk ON catalog_facet_base_values(library_id,field,id);
CREATE TRIGGER catalog_search_genre_target_immutable_update BEFORE UPDATE ON catalog_search_genre_targets
WHEN (SELECT complete FROM catalog_facet_bases WHERE id=OLD.base_id)=1 BEGIN SELECT RAISE(ABORT,'immutable genre target basis'); END;
CREATE TRIGGER catalog_search_genre_ready_immutable_update BEFORE UPDATE ON catalog_search_genre_ready
WHEN (SELECT complete FROM catalog_facet_bases WHERE id=OLD.base_id)=1 BEGIN SELECT RAISE(ABORT,'immutable genre ready basis'); END;

-- P2-28 maintained genre candidates: end

-- P2-28 current-show contribution staging: begin
-- ID-only current show, owned by maintained BASE build, never a query result.
-- One WITHOUT ROWID primary B-tree + one integer reverse-FK B-tree. Conservative
-- logical charge: 128 bytes per entry, including both indexes; no label bytes.
CREATE TABLE catalog_facet_base_show_seen (
 base_id INTEGER NOT NULL REFERENCES catalog_facet_bases(id),
 value_id INTEGER NOT NULL REFERENCES catalog_facet_base_values(id),
 PRIMARY KEY(base_id,value_id)
) STRICT, WITHOUT ROWID;
CREATE INDEX catalog_facet_base_show_seen_value ON catalog_facet_base_show_seen(value_id);
CREATE TRIGGER catalog_facet_base_show_seen_insert AFTER INSERT ON catalog_facet_base_show_seen BEGIN
 UPDATE catalog_facet_base_usage SET used_bytes=used_bytes+128 WHERE id=1;
END;
CREATE TRIGGER catalog_facet_base_show_seen_delete AFTER DELETE ON catalog_facet_base_show_seen BEGIN
 UPDATE catalog_facet_base_usage SET used_bytes=used_bytes-128 WHERE id=1;
END;
CREATE TRIGGER catalog_facet_base_show_seen_immutable BEFORE UPDATE ON catalog_facet_base_show_seen
BEGIN SELECT RAISE(ABORT,'replace current-show contribution IDs instead of updating'); END;
CREATE TRIGGER catalog_facet_base_show_seen_complete BEFORE INSERT ON catalog_facet_base_show_seen
WHEN (SELECT complete FROM catalog_facet_bases WHERE id=NEW.base_id)=1
BEGIN SELECT RAISE(ABORT,'immutable complete facet base'); END;
CREATE TRIGGER catalog_facet_base_show_seen_activation BEFORE UPDATE OF complete ON catalog_facet_bases
WHEN NEW.complete=1 AND EXISTS(SELECT 1 FROM catalog_facet_base_show_seen WHERE base_id=NEW.id)
BEGIN SELECT RAISE(ABORT,'clear current-show contributions before activation'); END;
-- P2-28 current-show contribution staging: end

-- Approved A1 command-journal and actual-preparation linkage fragment. Lead composes baseline.
-- Confirmed executable commands only. No query, traversal cursor or preview storage.
CREATE TABLE selection_action_groups (
 id INTEGER PRIMARY KEY CHECK(id>0),
 binding TEXT NOT NULL, operation_id TEXT NOT NULL, request_hash TEXT NOT NULL,
 account_id TEXT NOT NULL, library_id TEXT NOT NULL, action TEXT NOT NULL CHECK(action IN ('delete','download')),
 profile_id TEXT NOT NULL, server_id TEXT NOT NULL, authority TEXT NOT NULL, role TEXT NOT NULL,
 session_hash TEXT NOT NULL, session_epoch INTEGER NOT NULL CHECK(session_epoch>=0), expires_at TEXT NOT NULL,
 principal_device_id TEXT NOT NULL, grant_kind TEXT NOT NULL,
 delete_files INTEGER CHECK(delete_files IN(0,1)), device_id TEXT NOT NULL, quality TEXT NOT NULL,
 state TEXT NOT NULL CHECK(state IN ('capturing','sealed','running','cancelling')),
 total INTEGER NOT NULL CHECK(total BETWEEN 1 AND 9007199254740991), admitted INTEGER NOT NULL DEFAULT 0 CHECK(admitted BETWEEN 0 AND total),
 expected_digest TEXT NOT NULL CHECK(length(expected_digest)=64 AND expected_digest NOT GLOB '*[^0-9a-f]*'), seal_count INTEGER, seal_digest TEXT,
 done INTEGER NOT NULL DEFAULT 0 CHECK(done>=0), failed INTEGER NOT NULL DEFAULT 0 CHECK(failed>=0),
 bytes_deleted INTEGER NOT NULL DEFAULT 0 CHECK(bytes_deleted>=0), files_deleted INTEGER NOT NULL DEFAULT 0 CHECK(files_deleted>=0),
 error_code TEXT NOT NULL DEFAULT '' CHECK(length(error_code)<=160), terminal_state TEXT NOT NULL DEFAULT '' CHECK(terminal_state IN('','complete','partial','failed','cancelled')),
 created_ms INTEGER NOT NULL CHECK(created_ms>0),
 UNIQUE(binding,operation_id),
 CHECK(done+failed<=admitted),
 CHECK((action='delete' AND delete_files IS NOT NULL AND device_id='' AND quality='') OR (action='download' AND delete_files IS NULL AND length(device_id) BETWEEN 1 AND 160 AND quality<>'')),
 CHECK((seal_count IS NULL AND seal_digest IS NULL AND state IN('capturing','cancelling')) OR (seal_count IS NOT NULL AND seal_digest IS NOT NULL AND seal_count=total AND seal_digest=expected_digest AND state IN('sealed','running','cancelling')))
) STRICT;
CREATE INDEX selection_action_groups_account ON selection_action_groups(account_id,id);
CREATE TABLE selection_action_targets (
 group_id INTEGER NOT NULL REFERENCES selection_action_groups(id), entity_id INTEGER NOT NULL CHECK(entity_id>0),
 seq INTEGER NOT NULL CHECK(seq>0), item_id TEXT NOT NULL CHECK(length(item_id) BETWEEN 1 AND 160), library_id TEXT NOT NULL, kind TEXT NOT NULL CHECK(kind IN('movie','episode','song','audiobook_file')),
 title TEXT NOT NULL, identity TEXT NOT NULL, version_id TEXT NOT NULL,
 download_identity TEXT NOT NULL, lifetime TEXT NOT NULL,
 ready INTEGER NOT NULL DEFAULT 0 CHECK(ready IN(0,1)), error_code TEXT NOT NULL DEFAULT '' CHECK(length(error_code)<=160),
 PRIMARY KEY(group_id,entity_id), UNIQUE(group_id,seq)
) STRICT;
CREATE TABLE selection_action_files (
 group_id INTEGER NOT NULL, seq INTEGER NOT NULL CHECK(seq>0), target_id INTEGER NOT NULL CHECK(target_id>0),
 asset_id INTEGER NOT NULL CHECK(asset_id>0), token TEXT NOT NULL, path TEXT NOT NULL, root TEXT NOT NULL,
 root_identity TEXT NOT NULL, size INTEGER NOT NULL CHECK(size>=0), modified_ns INTEGER NOT NULL,
 shared INTEGER NOT NULL CHECK(shared IN(0,1)), present INTEGER NOT NULL CHECK(present IN(0,1)), part INTEGER NOT NULL,
 start REAL NOT NULL CHECK(abs(start)<=1e308), end REAL CHECK(end IS NULL OR abs(end)<=1e308), edition TEXT NOT NULL,
 source_id TEXT NOT NULL, source_incarnation TEXT NOT NULL, source_generation INTEGER NOT NULL CHECK(source_generation>=0),
 started INTEGER NOT NULL DEFAULT 0 CHECK(started IN(0,1)),
 PRIMARY KEY(group_id,seq),
 FOREIGN KEY(group_id,target_id) REFERENCES selection_action_targets(group_id,entity_id)
) STRICT;
CREATE INDEX selection_action_files_target ON selection_action_files(group_id,target_id,seq);
CREATE TABLE selection_action_history (
 id INTEGER PRIMARY KEY CHECK(id>0),
 binding TEXT NOT NULL, operation_id TEXT NOT NULL, request_hash TEXT NOT NULL,
 account_id TEXT NOT NULL, library_id TEXT NOT NULL, action TEXT NOT NULL CHECK(action IN('delete','download')),
 profile_id TEXT NOT NULL, server_id TEXT NOT NULL, authority TEXT NOT NULL, role TEXT NOT NULL,
 session_hash TEXT NOT NULL, session_epoch INTEGER NOT NULL CHECK(session_epoch>=0), expires_at TEXT NOT NULL,
 principal_device_id TEXT NOT NULL, grant_kind TEXT NOT NULL,
 state TEXT NOT NULL CHECK(state IN('complete','partial','failed','cancelled')), total INTEGER NOT NULL CHECK(total BETWEEN 1 AND 9007199254740991), admitted INTEGER NOT NULL CHECK(admitted BETWEEN 0 AND total),
 done INTEGER NOT NULL CHECK(done>=0), failed INTEGER NOT NULL CHECK(failed>=0), bytes_deleted INTEGER NOT NULL CHECK(bytes_deleted>=0),
 files_deleted INTEGER NOT NULL CHECK(files_deleted>=0), error_code TEXT NOT NULL CHECK(length(error_code)<=160), expires_ms INTEGER NOT NULL CHECK(expires_ms>0),
 UNIQUE(binding,operation_id),
 CHECK(done+failed<=admitted)
) STRICT;
CREATE INDEX selection_action_history_expiry ON selection_action_history(expires_ms,id);
CREATE INDEX selection_action_history_account ON selection_action_history(account_id,id);

-- Actual admitted download preparations, including reused preparations.
-- This is domain transfer ownership, never query membership or query scratch.
CREATE TABLE download_action_claims(
 profile_key TEXT NOT NULL,
 device_id TEXT NOT NULL,
 operation_id TEXT NOT NULL,
 preparation_id TEXT NOT NULL REFERENCES download_preparations(id) ON DELETE CASCADE,
 PRIMARY KEY(profile_key,device_id,operation_id,preparation_id),
 FOREIGN KEY(profile_key,device_id,operation_id) REFERENCES download_action_transfers(profile_key,device_id,operation_id)
) WITHOUT ROWID, STRICT;
CREATE INDEX download_action_claims_preparation ON download_action_claims(preparation_id);
-- Exact pinned-source/profile selection, excluding invalid transfer digests.
CREATE INDEX prepared_media_download_pinned ON prepared_media_versions(
 item_id,asset_id,profile_id,source_revision,created_ms,id)
 WHERE state='published' AND length(digest)=64 AND digest NOT GLOB '*[^0-9a-f]*';


-- Actual confirmed device-transfer ownership, no query membership or result cache.
CREATE TABLE download_action_transfers(
 id INTEGER PRIMARY KEY,
 profile_key TEXT NOT NULL CHECK(length(profile_key)>0),
 device_id TEXT NOT NULL CHECK(length(device_id) BETWEEN 1 AND 160),
 operation_id TEXT NOT NULL CHECK(length(operation_id) BETWEEN 1 AND 160),
 closed INTEGER NOT NULL DEFAULT 0 CHECK(closed IN(0,1)),
 created_ms INTEGER NOT NULL CHECK(created_ms>0),
 closed_ms INTEGER NOT NULL DEFAULT 0 CHECK(closed_ms>=0),
 UNIQUE(profile_key,device_id,operation_id),
 CHECK((closed=0 AND closed_ms=0) OR (closed=1 AND closed_ms>0))
) STRICT;

CREATE TABLE catalog_item_metric_jobs(
 link_available INTEGER NOT NULL DEFAULT 0,
 link_unavailable INTEGER NOT NULL DEFAULT 0,
 item_id INTEGER PRIMARY KEY REFERENCES catalog_entities(id) ON DELETE CASCADE,
 sequence INTEGER NOT NULL,
 phase INTEGER NOT NULL DEFAULT 0 CHECK(phase BETWEEN 0 AND 2),
 after_asset INTEGER NOT NULL DEFAULT 0,
 after_provider TEXT NOT NULL DEFAULT '',
 max_duration REAL,
 max_size INTEGER NOT NULL DEFAULT 0,
 max_height INTEGER NOT NULL DEFAULT 0,
 critic REAL,
 rating REAL,
 after_entity INTEGER NOT NULL DEFAULT 0,
 after_source INTEGER NOT NULL DEFAULT -1) STRICT;

CREATE TABLE catalog_browse_row_work(
 domain INTEGER PRIMARY KEY CHECK(domain IN(18,35)),
 entity_id INTEGER NOT NULL,
 revision INTEGER NOT NULL,
 phase INTEGER NOT NULL DEFAULT 0 CHECK(phase BETWEEN 0 AND 2),
 after_term INTEGER NOT NULL DEFAULT 0) STRICT;

CREATE TABLE catalog_browse_row_keys(
 domain INTEGER NOT NULL CHECK(domain IN(18,35)),
 field INTEGER NOT NULL CHECK(field IN(0,1)),
 value_key TEXT NOT NULL,
 PRIMARY KEY(domain,field,value_key)) WITHOUT ROWID, STRICT;

CREATE TRIGGER catalog_browse_metric_links_insert AFTER INSERT ON catalog_browse_member_metrics BEGIN
 INSERT INTO catalog_browse_member_links(entity_id,available,unavailable,members) SELECT NEW.entity_id,NEW.available_links,NEW.unavailable_links,0 WHERE EXISTS(SELECT 1 FROM catalog_entities WHERE id=NEW.entity_id) ON CONFLICT(entity_id) DO UPDATE SET available=available+excluded.available,unavailable=unavailable+excluded.unavailable;
 INSERT INTO catalog_dirty(domain,entity_id,revision) SELECT 35,id,1 FROM catalog_entities WHERE id=NEW.entity_id ON CONFLICT(domain,entity_id) DO UPDATE SET revision=revision+1;
END;

CREATE TRIGGER catalog_browse_metric_links_delete AFTER DELETE ON catalog_browse_member_metrics BEGIN
 UPDATE catalog_browse_member_links SET available=available-OLD.available_links,unavailable=unavailable-OLD.unavailable_links WHERE entity_id=OLD.entity_id;
 INSERT INTO catalog_dirty(domain,entity_id,revision) SELECT 35,id,1 FROM catalog_entities WHERE id=OLD.entity_id ON CONFLICT(domain,entity_id) DO UPDATE SET revision=revision+1;
END;

CREATE TABLE catalog_browse_counter_repairs(
 entity_id INTEGER PRIMARY KEY,
 revision INTEGER NOT NULL DEFAULT 0,
 phase INTEGER NOT NULL DEFAULT 0 CHECK(phase BETWEEN 0 AND 2),
 after_item INTEGER NOT NULL DEFAULT 0,
 after_source INTEGER NOT NULL DEFAULT -1,
 available INTEGER NOT NULL DEFAULT 0,
 unavailable INTEGER NOT NULL DEFAULT 0,
 members INTEGER NOT NULL DEFAULT 0) STRICT;

CREATE TRIGGER compact_visibility_dirty_member_update AFTER UPDATE OF entity_id,item_id,source ON catalog_browse_memberships
 WHEN OLD.entity_id IS NOT NEW.entity_id OR OLD.item_id IS NOT NEW.item_id OR OLD.source IS NOT NEW.source BEGIN
 UPDATE compact_visibility_source_state SET sequence=sequence+1 WHERE id=1;
 INSERT INTO compact_visibility_source_jobs(kind,library_id,subject_id,sequence,first_pending) SELECT 1,library_id,entity_id,(SELECT sequence FROM compact_visibility_source_state WHERE id=1),(SELECT sequence FROM compact_visibility_source_state WHERE id=1) FROM catalog_browse_rows WHERE entity_id=OLD.entity_id
 ON CONFLICT(kind,library_id,subject_id,subject_text) DO UPDATE SET sequence=excluded.sequence,first_pending=min(first_pending,excluded.first_pending),rerun_first=CASE WHEN pass_sequence=0 THEN rerun_first WHEN rerun_first=0 THEN excluded.first_pending ELSE min(rerun_first,excluded.first_pending) END;
 INSERT INTO compact_visibility_source_jobs(kind,library_id,subject_id,sequence,first_pending) SELECT 1,library_id,entity_id,(SELECT sequence FROM compact_visibility_source_state WHERE id=1),(SELECT sequence FROM compact_visibility_source_state WHERE id=1) FROM catalog_browse_rows WHERE entity_id=NEW.entity_id
 ON CONFLICT(kind,library_id,subject_id,subject_text) DO UPDATE SET sequence=excluded.sequence,first_pending=min(first_pending,excluded.first_pending),rerun_first=CASE WHEN pass_sequence=0 THEN rerun_first WHEN rerun_first=0 THEN excluded.first_pending ELSE min(rerun_first,excluded.first_pending) END;
END;

CREATE TRIGGER compact_visibility_dirty_attribute_update AFTER UPDATE OF item_id,term_id ON catalog_item_attribute_edges
 WHEN OLD.item_id IS NOT NEW.item_id OR OLD.term_id IS NOT NEW.term_id BEGIN
 UPDATE compact_visibility_source_state SET sequence=sequence+1 WHERE id=1;
 INSERT INTO compact_visibility_source_jobs(kind,subject_id,sequence,first_pending) SELECT 2,OLD.item_id,(SELECT sequence FROM compact_visibility_source_state WHERE id=1),(SELECT sequence FROM compact_visibility_source_state WHERE id=1) WHERE (SELECT f.field FROM catalog_attribute_terms t JOIN catalog_attribute_fields f ON f.id=t.field_id WHERE t.id=OLD.term_id) IN('contentRating','label')
 ON CONFLICT(kind,library_id,subject_id,subject_text) DO UPDATE SET sequence=excluded.sequence,first_pending=min(first_pending,excluded.first_pending),rerun_first=CASE WHEN pass_sequence=0 THEN rerun_first WHEN rerun_first=0 THEN excluded.first_pending ELSE min(rerun_first,excluded.first_pending) END;
 INSERT INTO compact_visibility_source_jobs(kind,subject_id,sequence,first_pending) SELECT 2,NEW.item_id,(SELECT sequence FROM compact_visibility_source_state WHERE id=1),(SELECT sequence FROM compact_visibility_source_state WHERE id=1) WHERE (SELECT f.field FROM catalog_attribute_terms t JOIN catalog_attribute_fields f ON f.id=t.field_id WHERE t.id=NEW.term_id) IN('contentRating','label')
 ON CONFLICT(kind,library_id,subject_id,subject_text) DO UPDATE SET sequence=excluded.sequence,first_pending=min(first_pending,excluded.first_pending),rerun_first=CASE WHEN pass_sequence=0 THEN rerun_first WHEN rerun_first=0 THEN excluded.first_pending ELSE min(rerun_first,excluded.first_pending) END;
END;

CREATE TABLE compact_visibility_source_state(
 id INTEGER PRIMARY KEY CHECK(id=1),turn INTEGER NOT NULL DEFAULT 0,sequence INTEGER NOT NULL DEFAULT 0) STRICT;

CREATE TABLE compact_visibility_source_jobs(
 kind INTEGER NOT NULL CHECK(kind BETWEEN 1 AND 4),
 library_id INTEGER NOT NULL DEFAULT 0,subject_id INTEGER NOT NULL DEFAULT 0,subject_text TEXT NOT NULL DEFAULT '',
 sequence INTEGER NOT NULL,first_pending INTEGER NOT NULL,
 pass_sequence INTEGER NOT NULL DEFAULT 0,rerun_first INTEGER NOT NULL DEFAULT 0,
 cursor_phase INTEGER NOT NULL DEFAULT 0,cursor_entity INTEGER NOT NULL DEFAULT 0,cursor_source INTEGER NOT NULL DEFAULT -1,
 fence_entity INTEGER NOT NULL DEFAULT 0,fence_source INTEGER NOT NULL DEFAULT -1,term_id INTEGER NOT NULL DEFAULT 0,
 PRIMARY KEY(kind,library_id,subject_id,subject_text)) WITHOUT ROWID, STRICT;

CREATE INDEX compact_visibility_source_jobs_frontier ON compact_visibility_source_jobs(first_pending);

CREATE INDEX compact_visibility_source_jobs_turn ON compact_visibility_source_jobs(kind,first_pending,library_id,subject_id,subject_text);

INSERT INTO compact_visibility_source_state(id,turn,sequence) VALUES(1,0,0);

CREATE INDEX compact_visibility_dirty_frontier ON compact_visibility_dirty(class_id,first_sequence,entity_id);

CREATE TRIGGER catalog_browse_metric_links_update AFTER UPDATE OF entity_id,available_links,unavailable_links ON catalog_browse_member_metrics
 WHEN OLD.entity_id IS NOT NEW.entity_id OR OLD.available_links IS NOT NEW.available_links OR OLD.unavailable_links IS NOT NEW.unavailable_links BEGIN
 UPDATE catalog_browse_member_links SET available=available-OLD.available_links,unavailable=unavailable-OLD.unavailable_links WHERE entity_id=OLD.entity_id;
 INSERT INTO catalog_browse_member_links(entity_id,available,unavailable,members) SELECT NEW.entity_id,NEW.available_links,NEW.unavailable_links,0 WHERE EXISTS(SELECT 1 FROM catalog_entities WHERE id=NEW.entity_id) ON CONFLICT(entity_id) DO UPDATE SET available=available+excluded.available,unavailable=unavailable+excluded.unavailable;
 INSERT INTO catalog_dirty(domain,entity_id,revision) SELECT 35,id,1 FROM catalog_entities WHERE id=OLD.entity_id ON CONFLICT(domain,entity_id) DO UPDATE SET revision=revision+1;
 INSERT INTO catalog_dirty(domain,entity_id,revision) SELECT 35,id,1 FROM catalog_entities WHERE id=NEW.entity_id ON CONFLICT(domain,entity_id) DO UPDATE SET revision=revision+1;
END;
-- P251 lifetime owners and restartable profile retirement. No query results.
CREATE TABLE identity_installations(
 installation_hash TEXT PRIMARY KEY CHECK(length(installation_hash)=64),
 incarnation TEXT NOT NULL UNIQUE CHECK(length(incarnation)=32),
 registration_revision INTEGER NOT NULL DEFAULT 0
  CHECK(registration_revision BETWEEN 0 AND 9007199254740991),
 registration_nonce TEXT NOT NULL DEFAULT '' CHECK(length(registration_nonce) IN(0,22)),
 registration_root TEXT NOT NULL DEFAULT '' CHECK(length(registration_root) IN(0,22)),
 retired INTEGER NOT NULL DEFAULT 0 CHECK(retired IN(0,1))
) STRICT;
CREATE TABLE user_mutation_roots(
 id TEXT PRIMARY KEY CHECK(length(id)=22),
 installation_incarnation TEXT NOT NULL CHECK(length(installation_incarnation)=32),
 account_id TEXT NOT NULL, profile_id TEXT NOT NULL,
 account_incarnation TEXT NOT NULL, profile_incarnation TEXT NOT NULL CHECK(length(profile_incarnation)=32),
 family_id TEXT NOT NULL,
 registration_revision INTEGER NOT NULL CHECK(registration_revision BETWEEN 1 AND 9007199254740991),
 state TEXT NOT NULL CHECK(state IN('active','draining')),
 UNIQUE(installation_incarnation,registration_revision)
) STRICT;
CREATE UNIQUE INDEX user_mutation_roots_active ON user_mutation_roots(installation_incarnation) WHERE state='active';
CREATE UNIQUE INDEX user_mutation_roots_draining ON user_mutation_roots(installation_incarnation) WHERE state='draining';
CREATE INDEX user_mutation_roots_profile ON user_mutation_roots(account_id,profile_id,profile_incarnation,id);
CREATE INDEX user_mutation_roots_family ON user_mutation_roots(family_id,id);
CREATE TRIGGER user_mutation_root_capacity BEFORE INSERT ON user_mutation_roots BEGIN
 SELECT CASE WHEN NOT EXISTS(SELECT 1 FROM user_mutation_global WHERE singleton=1
 AND ordinary_bytes+stop_bytes+1024<=33554432 AND ordinary_bytes+1024<=31457280)
 THEN RAISE(ABORT,'user_mutation_capacity') END;
END;
CREATE TRIGGER user_mutation_root_charge AFTER INSERT ON user_mutation_roots BEGIN
 UPDATE user_mutation_global SET ordinary_bytes=ordinary_bytes+1024 WHERE singleton=1;
END;
CREATE TRIGGER user_mutation_root_release AFTER DELETE ON user_mutation_roots BEGIN
 UPDATE user_mutation_global SET ordinary_bytes=ordinary_bytes-1024 WHERE singleton=1;
END;
CREATE TABLE security_purge_jobs(
 job_id TEXT PRIMARY KEY CHECK(length(job_id)=22),
 authority TEXT NOT NULL CHECK(authority='local'),
 account_id TEXT NOT NULL, profile_id TEXT NOT NULL,
 account_incarnation TEXT NOT NULL, profile_incarnation TEXT NOT NULL,
 desired_revision INTEGER NOT NULL DEFAULT 1 CHECK(desired_revision>0),
 phase INTEGER NOT NULL DEFAULT 0 CHECK(phase>=0),
 cursor_key TEXT NOT NULL DEFAULT '' CHECK(length(cursor_key)<=512),
 process_epoch TEXT NOT NULL DEFAULT '',
 attempt INTEGER NOT NULL DEFAULT 0 CHECK(attempt>=0),
 next_attempt_ms INTEGER NOT NULL DEFAULT 0 CHECK(next_attempt_ms>=0),
 state TEXT NOT NULL CHECK(state IN('pending','running','blocked')),
 UNIQUE(authority,account_id,profile_id,profile_incarnation)
) STRICT;
CREATE INDEX security_purge_due ON security_purge_jobs(state,next_attempt_ms,job_id);
CREATE INDEX user_mutation_receipts_profile ON user_mutation_receipts(scope_id,profile_id,profile_incarnation,key);
CREATE INDEX user_mutation_receipts_root ON user_mutation_receipts(root_id,key);
CREATE INDEX personal_conflicts_profile ON personal_conflicts(profile_id,id);
CREATE INDEX console_exports_actor ON console_exports(actor,id);

